window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-pediatria-ped-4"]={"block":"medcurso:medcurso-pediatria-ped-4","label":"Medcurso · PED 4","count":429,"questions":[{"id":"medcurso-pediatria-ped-4-345460","number":"345460","sourceNumber":"345460","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Homem de 25 anos é atendido durante viagem ao Jalapão (TO) com dor abdominal,\nvômitos e diarreia com sangue. No exame\nfísico sua temperatura axilar é de 36,8ºC, frequência\ncardíaca de 120 bpm e pressão arterial de 110/75 mmHg. Exames complementares realizados na\nurgência mostram: hemoglobina = 9,5 g/l; leucometria = 13.000/mm³ ; contagem relativa de\nneutrófilos = 83%; contagem de plaquetas = 30.000/mm³; ureia sérica = 156 mg/dL; creatinina\nsérica = 5,2 mg/dL. Além da reposição adequada de líquidos por via intravenosa, qual a próxima\nabordagem mais apropriada para este paciente:","options":{"A":"Azitromicina por via oral.","B":"Imunoglobulina intravenosa.","C":"Ceftriaxona e metronidazol, ambos por via intravenosa.","D":"Avaliação especializada visando hemodiálise e possível plasmaferese."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343782","number":"343782","sourceNumber":"343782","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 4 meses de idade, deu entrada na emergência pediátrica com quadro de\ndesconforto respiratório leve, febre e saturação de 95%. O exame da ausculta pulmonar revelava\nsibilos difusos. Iniciou o quadro com coriza e congestão nasal há 6 dias atrás que evolui com a\ndescrição clínica acima. A radiografia de tórax apresentava o seguinte aspecto: A respeito da\ndescrição clínica acima, qual o provável diagnóstico e agente etiológico envolvido?","options":{"A":"Pneumonia aguda da comunidade, Mycoplasma pneumoniae.","B":"Tuberculose pulmonar, Staphylococcus aureus.","C":"Bronquiolite viral aguda, Vírus Sincicial Respiratório.","D":"Bronquiolite viral aguda, Adenovírus."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343784","number":"343784","sourceNumber":"343784","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Adolescente comparece a Unidade Básica de Saúde com queixa de distensão\nabdominal, sensação de plenitude gástrica e\nmeteorismo intestinal após o uso de alimentos que\ncontenham leite. O quadro trata-se de uma intolerância a lactose. Em relação ao tema, marque\nabaixo a resposta correta:","options":{"A":"Não ocorre na fase adulta.","B":"Pode ser congênita ou secundária a infecção intestinal ou desnutrição grave.","C":"O tratamento se baseia na exclusão da proteína do leite de vaca da dieta.","D":"Ocorre devido uma reação de hipersensibilidade mediada por lgE."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343793","number":"343793","sourceNumber":"343793","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente com 3 meses de idade apresenta diagnóstico de alergia a proteína do leite de\nvaca. A criança já não mama mais ao seio materno, qual das opções abaixo deve ser adotada para\nalimentação dessa criança?","options":{"A":"Antecipar a transição alimentar.","B":"Usar fórmula láctea hidrolisada.","C":"Usar fórmula láctea isenta de lactose.","D":"Antecipar a transição alimentar e usar composto lácteo."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-345502","number":"345502","sourceNumber":"345502","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança com 2 anos de vida apresenta quadro de diarreia há 3 meses, com fezes\nsemilíquidas, sem sangue e de odor fétido.\nSua mãe relata que esse quadro é intercalado com\nfezes pastosas. Nega febre e apresenta vômitos esporádicos. Ao exame: pálida (+), afebril, muito\nemagrecida (peso e altura abaixo do percentil 10). Pulmões sem ruídos adventícios, cardiovascular\nnormal, abdome distendido e sem visceromegalias. O pediatra levantou a hipótese diagnóstica de\nDoença Celíaca? Marque a alternativa CORRETA em relação aos exames que devem ser\nsolicitados para paciente com suspeita de doença celíaca:","options":{"A":"Anticorpo antiendomísio e anticorpo antitransglutaminase tecidual.","B":"Teste do suor com pilocarpina e iontoforese.","C":"IgE especifica para alimentos e Anticorpo antiendomísio.","D":"Curva de tolerância à lactose e anticorpo antitransglutaminase tecidual."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-345503","number":"345503","sourceNumber":"345503","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 7 anos de idade, com quadro de desnutrição marasmático. Em\natendimento clínico na emergência, seu pai\nrelata que o garoto não come bem e tem constipação\nintestinal há 2 anos. Só consegue evacuar com supositório. Ao exame: estado geral decaído, pálido\n(++/4+). Pulmões e cardiovascular normais. Abdome bem distendido, com timpanismo aumentado e\ncom fecaloma palpável em abdome inferior. Qual conduta CORRETA para esse paciente em\nrelação ao fecaloma?","options":{"A":"No momento deve ser orientado só dieta laxante para idade e uso de lactulona oral.","B":"Iniciar desimpactação do fecaloma com uso da lactulona oral.","C":"No momento não realizar a desimpactação e iniciar o uso de leite de magnésio.","D":"Realizar desimpactação do fecaloma com solução de sorbitol ou polietilenoglicol dose\n1,0-1,5grs."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-345504","number":"345504","sourceNumber":"345504","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Diarréia aguda é uma doença prevalente em menores de 5 anos no Brasil. Uma das\ncomplicações é a desidratação. Marque a alternativa ERRADA em relação à fisiopatologia da\ndiarreia aguda na criança:","options":{"A":"Nos casos de diarreia infecciosa acompanhado da síndrome hemolítico urêmica tem como\nprincipal etiologia a E. Coli Enterohemorrágica (cepa O157: H7).","B":"No mecanismo invasivo o principal agente etiológico a Shiguella, podendo apresentar tenesmo e\nsangue nas fezes.","C":"O mecanismo secretor ocorre quando a criança ingere muito hidrato de carbono estimulando a\nliberação do AMPc e GMPc com aumento da secreção de água e eletrólitos nas fezes.","D":"O mecanismo secretor ocorre quando a criança tem diarreia pelo agente etiológico E. coli\ntoxigênica e atua estimulando a liberação\ndo AMPc e GMPc com aumento da secreção de água e\neletrólitos nas fezes."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283291","number":"283291","sourceNumber":"283291","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A otite média aguda apresenta importante morbidade na população pediátrica,\nespecialmente entre os 6 aos 24 meses de idade.\nQual dos abaixo NÃO são fatores de risco para a\nocorrência dessa patologia:","options":{"A":"Dormir em decúbito dorsal.","B":"Exposição ao tabaco e ambientes poluídos.","C":"Frequentar berçários e creches.","D":"Uso de chupetas."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283292","number":"283292","sourceNumber":"283292","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Bronquiolite aguda é uma doença que ocorre em lactentes (menores de 2 anos de\nidade) precedida por infecção viral de vias aéreas superiores e seguida por esforço respiratório,\nsibilância e/ou crepitação. Com relação a esse diagnóstico marque o principal agente etiológico da\ndoença tanto em países desenvolvidos como em países em desenvolvimento.","options":{"A":"Rinovírus.","B":"Vírus Sincicial Respiratório.","C":"Coronavírus.","D":"Parainfluenza."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283299","number":"283299","sourceNumber":"283299","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menor de 4 anos de idade com quadro de febre diária há 4 dias, variando de 38,5 a\n39ºC, além de tosse produtiva, falta de\napetite e cansaço. No exame físico, criança vígil, responsiva\naos comandos, hidratada, afebril, com estertores subcrepitantes em base pulmonar esquerda, com\nFR de 55 inc/min, FC de 100 bat/min, sem demais alterações pertinentes. O Rx de tórax mostrou\ncondensação em base de pulmão E. Qual a conduta recomendada pela OMS nesse caso?","options":{"A":"Internação hospitalar e penicilina 200mg/kg/dia endovenoso.","B":"Tratamento ambulatorial e amoxicilina 50mg/kg/dia.","C":"Internação hospitalar e ceftriaxone 100mg/kg/dia.","D":"Tratamento ambulatorial com sintomáticos."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283300","number":"283300","sourceNumber":"283300","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A regurgitação infantil ocorre na maioria dos lactentes saudáveis, resolvendo\nespontaneamente entre 12 aos 18 meses, sendo\nsinal de alerta para refluxo patológico, a presença\nde:","options":{"A":"Retardo no ganho ponderal.","B":"Dois ou mais episódios de regurgitação durante o dia.","C":"Choro noturno.","D":"Ocorre após alimentação e duração menor que 3 minutos."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283302","number":"283302","sourceNumber":"283302","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"As infecções das vias aéreas superiores são problemas comumente encontrados nos\nserviços de atendimento médico pediátrico. Assinale a alternativa CORRETA:","options":{"A":"A otite média aguda é uma doença de início súbito, caracterizada pela presença de efusão no\nouvido médio, sendo fatores de risco frequentar berçários e uso de chupetas.","B":"A primeira escolha em antibioticoterapia no tratamento da sinusite bacteriana é amoxicilina\nassociado com acido clavulânico por 7 dias.","C":"A faringoamigdalite de etiologia bacteriana é mais frequente que a viral, especialmente nas\ncrianças abaixo de 3 anos de idade.","D":"A rinofaringite viral é o quadro infeccioso pouco frequente na infância, podendo ocorrer de 5 a 8\nepisódios por ano em menores de 5 anos imunocompetentes."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-281124","number":"281124","sourceNumber":"281124","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 56 anos de idade relata otalgia a esquerda com 2 semanas de evolução,\nassociada a otorreia. Evolui com dor em região de mastóide e febre. Realizou TC que evidenciou\nvelamento de mastóide à esquerda. Assinale a assertiva que contém os patógenos mais\ncomumente associados à condição.","options":{"A":"S. pneumoniae, H. influenzae, M catarrhalis.","B":"Clostridium sp., H. influenzae, M catarrhalis.","C":"S. pneumoniae, S. aureus, P. aeruginosa.","D":"S. aureus, H. influenzae, M catarrhalis.","E":"S. aureus, P. aeruginosa, anaeróbios."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-281125","number":"281125","sourceNumber":"281125","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Homem, 30 anos de idade, procura pronto atendimento com queixa de tosse seca,\nsecreção nasal importante e dor na face em peso. Os sintomas se iniciaram há 17 dias,\nmelhoraram por volta do quinto dia e logo depois evoluíram com piora progressivamente. Único\nachado alterado de exame físico: secreção posterior em orofaringe. As condutas diagnóstica e\nterapêutica corretas são, respectivamente,","options":{"A":"Tomografia de seios da face; amoxicilina-clavulanato e sintomáticos.","B":"Radiografia de seios da face; apenas sintomáticos.","C":"Tomografia de seios da face; apenas sintomáticos.","D":"Radiografia da face; amoxicilina-clavulanato e sintomáticos.","E":"Exame clínico já realizado, sem necessidade de exame de imagem; amoxicilina-clavulanato e\nsintomáticos."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291793","number":"291793","sourceNumber":"291793","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino, 3 anos de idade, chega à Unidade de Pronto Atendimento, UPA, com\ndificuldade respiratória há aproximadamente 12\nhoras. A senhora relata febre e tosse produtiva há\n3 dias. No momento, encontra-se em estado geral comprometido; taquipneico, com tiragem\nsubcostal; T.: 39ºC; FC: 120bpm; FR: 38ipm; SatO2 : 88% em ar ambiente. A ausculta respiratória\nevidencia murmúrios vesiculares hipoaudíveis em base do hemitórax direito. A Radiografia de tórax\nem PA e perfil mostra opacificação em 1/3 inferior com obliteração do seio costo-frênico à Direita\nIndique o agente etiológico mais provável, nesse caso.","options":{"A":"Streptococcus pneumoniae.","B":"Staphylococcus aureus.","C":"Moraxella catarrhalis.","D":"Enterobactéria."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283322","number":"283322","sourceNumber":"283322","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual exame permite confirmar o diagnóstico da doença de Hirschsprung?","options":{"A":"Manometria retal com ausência de reflexo de relaxamento do esfíncter interno.","B":"Anatomia patológica com espessamento das fibras musculares e imunohistoquimica com\naumento da atividade da desmolase.","C":"Anatomia patológica do reto com ausência de células ganglionares e imunohistoquímica com\naumento da atividade da acetilcolinesterase.","D":"Tomografia computadorizada do abdome com distensão de alças intestinais até a altura do reto."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283323","number":"283323","sourceNumber":"283323","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Recém-nascido com 3 semanas de vida inicia com vômitos alimentares pos prandiais,\napresentando piora progressiva ao longo dos dias. Voltou ao peso de nascimento. Chega para seu\natendimento com 10 dias de início dos sintomas. Qual dos seguintes achados não é esperado em\nseu exame físico?","options":{"A":"Ondas de Kussmaul abdominais.","B":"Oliva palpável em hipocôndrio direito.","C":"Desidratação.","D":"Distensão abdominal tão exuberante que exibe circulação colateral."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-281152","number":"281152","sourceNumber":"281152","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pré-escolar de 4 anos vem à consulta com queixa de febre alta e calafrio há 3 dias,\nacompanhada de dor abdominal, cefaleia e artralgia. Ao exame apresenta estomatite aftosa,\nfaringite e adenite cervical. Mãe relata que já apresentou vários episódios semelhantes desde os\ndois anos de idade com duração de 3 a 6 dias, usando ou não antibióticos. Os episódios recorrem a\ncada cerca de 4 semanas, ficando assintomático entre as crises. Baseado na sua principal hipótese\ndiagnóstica, o tratamento mais adequado a este paciente seria:","options":{"A":"antibiótico de amplo espectro.","B":"imunoglobulina humana.","C":"antiinflamatório.","D":"prednisona.","E":"aciclovir."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-247181","number":"247181","sourceNumber":"247181","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A lactase é encontrada","options":{"A":"Nas microvilosidades dos enterócitos, especialmente na região da cripta.","B":"Nas microvilosidades dos enterócitos, especialmente no ápice da vilosidade.","C":"Na secreção pancreática em quantidade na saliva.","D":"Na secreção pancreática em quantidade proporcional à lipase.","E":"Na secreção pancreática e nas microvilosidades dos enterócitos do ápice e da cripta."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-247182","number":"247182","sourceNumber":"247182","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"De acordo com a Organização Mundial da Saúde, o elemento que reduz o risco de\nrecorrência da diarreia aguda e da diarreia persistente é","options":{"A":"O zinco.","B":"O cobre.","C":"A vitamina C.","D":"A vitamina E.","E":"A vitamina B12."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-247185","number":"247185","sourceNumber":"247185","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino de 2 anos, com história de febre há 3 dias, acompanhada de coriza amarelada.\nHá dois dias irritabilidade e há um dia com T=\n39°C e recusa-se a deambular (chora). Ao exame\nfísico, apresenta dor às manobras de movimentação de quadril esquerdo. Qual o diagnóstico mais\nprovável?","options":{"A":"Febre reumática.","B":"Leucemia linfoide aguda.","C":"Artrite séptica.","D":"Necrose asséptica do quadril.","E":"Artrite idiopática juvenil."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-247191","number":"247191","sourceNumber":"247191","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A pneumonia por Mycoplasma pneumoniae predomina","options":{"A":"Em pré-escolares, é geralmente febril e a toxemia é importante.","B":"Na adolescência, é geralmente afebril e a toxemia não é importante.","C":"Em pré-escolares, é geralmente afebril e a toxemia não é importante.","D":"Na adolescência, é geralmente febril e a toxemia não é importante.","E":"Na adolescência, é geralmente febril e a toxemia é importante."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-247192","number":"247192","sourceNumber":"247192","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A primeira manifestação clínica que pode estar presente na fibrose cística é:","options":{"A":"Desidratação com hiprocloremia e hiponametrimia com acidose metabólica.","B":"Colestase neonatal.","C":"Cirrose biliar focal.","D":"Desidratação com hipocloremia e hiponatremia com alcalose metabólica.","E":"Íleo meconial."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-251922","number":"251922","sourceNumber":"251922","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Recém-nascido, do sexo masculino, na terceira semana de vida, começou apresentar\nvômitos não-biliosos em jato e irritabilidade,\nmas sem recusa ao seio materno. Mãe nega febre e\nnão apresenta outras queixas. Ao exame físico, constatou-se perda ponderal (300g do peso do\nnascimento) e visualização de ondas de Kussmaul, orientadas do quadrante superior esquerdo\npara o direito, além de pequena tumoração próxima ao umbigo. Baseado nas informações, qual a\nhipótese diagnóstica?","options":{"A":"Refluxo gastro-esofágico.","B":"Intussuscepção intestinal.","C":"Estenose hipertrófica de piloro.","D":"Hérnia umbilical."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-251923","number":"251923","sourceNumber":"251923","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A pneumonia comunitária (PAC) é um diagnóstico frequente dentro dos consultórios\npediátricos, sendo o pneumococo, o responsável pela\nmaioria dos casos. Marque qual dos fatores\nabaixo NÃO é de risco para aquisição de infecções respiratórias.","options":{"A":"Presença de convulsão febril.","B":"Permanência em creches.","C":"Desnutrição.","D":"Anemia falciforme."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-251924","number":"251924","sourceNumber":"251924","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A OMS alerta para os \"sinais de perigo\" no que se referem as doenças na infância, eles\nindicam que a criança deve ser referenciada imediatamente ao hospital na presença deles, fato que\ntem sido confirmado nas ultimas revisões sistemáticas. São eles, EXCETO:","options":{"A":"Alteração do sensório.","B":"Estridor em repouso.","C":"Tiragem intercostal.","D":"Convulsão."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-251927","number":"251927","sourceNumber":"251927","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Com relação a diarreia na infância assinale a alternativa CORRETA:","options":{"A":"Na grande maioria dos casos, a diarreia aguda é autolimitada, sendo a reposição de água e\neletrólitos, na quase totalidade dos casos, o tratamento fundamental independentemente do agente\nenvolvido.","B":"Na diarreia crônica os exames complementares são mais importantes que a história clínica e o\nexame físico detalhado, sendo necessário submeter a criança a uma exaustiva investigação\ncomplementar.","C":"As diarreias secretoras atuam principalmente em segmentos do intestino grosso e contém\ngrande volume de líquidos e eletrólitos,\nraramente com sangue e muco.","D":"O uso de antibiótico tem ação benéfica na diarreia e não provoca desequilíbrio na flora normal\ndo intestino, sendo indicados em casos\nespecíficos, como em desnutridos graves e lactentes de\nbaixa idade com clara evidência de toxemia."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-217712","number":"217712","sourceNumber":"217712","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Bronquiolite Viral Aguda (BVA) ocorre em lactentes, menores de 2 anos de idade,\nprecedida por infecções de vias aéreas\nsuperiores e seguida de esforço respiratório, sibilância e/ou\ncrepitação, sendo o principal AGENTE ETIOLÓGICO da doença, tanto em países desenvolvidos\ncomo nos em desenvolvimento, o:","options":{"A":"Rinovírus.","B":"Adenovírus.","C":"Metapneumovírus.","D":"Vírus Sincicial Respiratório."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-217711","number":"217711","sourceNumber":"217711","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Otite Média Aguda (OMA) é um infecção com desenvolvimento rápido de sinais e\nsintomas de inflamação aguda na cavidade da orelha média. O ACHADO MAIS SIGNIFICATIVO\npara o diagnóstico clínico da Otite Média Aguda é:","options":{"A":"Secreção amarelada e fétida da membrana timpânica.","B":"Hiperemia da membrana timpânica.","C":"Abaulamento da membrana timpânica.","D":"Opacidade da membrana timpânica."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-217716","number":"217716","sourceNumber":"217716","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A constipação intestinal é um sintoma gastrointestinal bastante frequente nas consultas\npediátricas. Assinale a alternativa CORRETA com relação ao tema:","options":{"A":"As crianças menores de 1 ano devem ser tratadas com orientações dietéticas e óleo mineral.","B":"A origem da constipação intestinal é de causa orgânica em mais de 50% dos casos.","C":"O tratamento de manutenção consiste em realizar a desimpactação fecal com uso de enemas ou\nlaxantes orais.","D":"São causas secundárias de constipação intestinal: fibrose cística, doença celíaca, espinha bífida\ne uso de sais de ferro."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-217736","number":"217736","sourceNumber":"217736","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto à faringotonsilite estreptocócica:","options":{"A":"Odinofagia (geralmente de início súbito) e febre (acima de 38ºC) são sintomas de\nfaringotonsilite estreptocócica e podem estar associados\nà cefaleia, náuseas, vômitos e dor de\nabdominal.","B":"A amoxicilina é o fármaco de primeira escolha para o tratamento de faringite estreptocócica por\nsua comprovada efetividade, segurança, espectro limitado e baixo custo.","C":"A claritromicina pode ser utilizada em pacientes alérgicos à amoxicilina; porém, geralmente, é\nevitada em razão dos efeitos adversos gastrintestinais.","D":"A indicação de tonsilectomia por causa infecciosa baseia-se na ocorrência de sete episódios em\num ano, cinco episódios anuais por dois anos\nconsecutivos ou três episódios anuais por três anos\nconsecutivos."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-217740","number":"217740","sourceNumber":"217740","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente, com 9 meses de idade, chega à Unidade Básica de Saúde (UBS) com\nquadro de diarreia líquido pastosa, sem\nmuco e/ou sangue, com 4-5 evacuações ao dia,\nacompanhada de febre baixa (37,5°C), que iniciou-se há 2 dias. A alimentação é feita com leite\nmaterno e complementação adequada. O calendário vacinal encontra-se em dia e a curva de\ncrescimento dentro dos parâmetros da normalidade. A mãe estava fazendo uso de soro caseiro e\nobservou que o lactente vinha recusando a alimentação nas últimas 24 horas. Ao exame físico o\nlactente apresentava letargia, olhos fundos e sinal da prega com retorno lento ao estado anterior.\nDe acordo com a Organização Mundial de Saúde, qual a classificação do quadro diarreico e a\nconduta terapêutica? Diarreia com desidratação...","options":{"A":"Moderada; iniciar a hidratação oral na UBS e liberar conforme melhora clínica.","B":"Leve; iniciar a hidratação oral na UBS e liberar conforme melhora clínica.","C":"Grave; referir urgentemente para o hospital.","D":"Leve, iniciar a hidratação na UBS."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-182616","number":"182616","sourceNumber":"182616","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente com diarreia crônica com exame de fezes (parasitológico) e teste fecal para\nantígenos de Giardia lamblia negativos, com teste para gordura fecal anormal, sem nenhuma pista\nsobre a etiologia e com teste da D-xilose anormal. Qual a próxima etapa de investigação para\nmelhor elucidação etiológica?","options":{"A":"Coprocultura.","B":"Biópsia de intestino delgado.","C":"Tomografia para avaliar pâncreas.","D":"Teste de secretina."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183195","number":"183195","sourceNumber":"183195","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Recém-nascido de 20 dias de vida chega ao hospital com história de vômitos em jato,\nde conteúdo branco, há 3 dias. No exame físico, apresentava peristaltismo visível no epigastro e\npalpava-se tumoração em hipocôndrio direto, logo abaixo do lobo direto do fígado. A criança\napresentava-se emagrecida, mas em bom estado geral. Quanto à história pregressa, esse RN\nnasceu de termo, parto normal, sem intercorrências, com apgar de 8 e 10 no primeiro e quinto\nminutos, respectivamente. Qual o provável diagnóstico e qual exame complementar pode auxiliar\nno diagnóstico?","options":{"A":"Refluxo Gasto-esofágico, RX contrastado (SEED).","B":"Atresia de Duodeno, Raio X contrastado.","C":"Estenose Hipertrófica do Piloro, ultrassonografia.","D":"Atresia de Duodeno, Raio X simples.","E":"Estenose Hipertrófica do Piloro, RX contrastado."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-182703","number":"182703","sourceNumber":"182703","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Considerando as pneumonias na infância, qual dos achados clínicos abaixo é o\nprimeiro a desaparecer quando a criança responde ao tratamento?","options":{"A":"Febre.","B":"Taquipneia.","C":"Tosse.","D":"Irritabilidade."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-182607","number":"182607","sourceNumber":"182607","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Considerando as Infecções das Vias Aéreas Superiores (IVAS) na infância, leia as\nalternativas abaixo: I. Os agentes etiológicos mais frequentemente encontrados na Otite Média\nAguda são: Streptococcus pneumoniae, Haemophilus influenzae e Moraxella catarhallis. II. A\ncoloração amarelada ou esverdeada da secreção nasal das crianças corresponde à proliferação\nbacteriana, sendo um marcador de infecção. III. O uso de antitussígenos, expectorantes e\nmucolíticos não apresenta benefícios sobre os sintomas ou evolução do quadro. Pergunta-se: quais\nafirmativas estão ERRADAS?","options":{"A":"II e III.","B":"Somente a II.","C":"Somente a III.","D":"Nenhuma."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-182666","number":"182666","sourceNumber":"182666","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual a melhor opção para o manejo de uma criança com quadro de diarreia e algum\ngrau de desidratação, sem choque?","options":{"A":"Plano A: tratamento em domicílio com aumento da oferta de líquidos, incluindo a administração\nde soro de reidratação oral, além da manutenção\nda alimentação.","B":"Plano B: administrar o soro de reidratação via oral em domicílio e manter alimentação com\naumento da ingesta hídrica.","C":"Plano B: administrar o soro de reidratação via oral sob supervisão médica, manter o aleitamento\nmaterno e suspender outros alimentos somente durante a terapia de reparação por via oral.","D":"Plano C: internação hospitalar com correção da desidratação grave com terapia de reidratação\npor via parenteral."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-182649","number":"182649","sourceNumber":"182649","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"O refluxo gastroesofágico (RGE) é um evento fisiológico normal que afeta\n\nrecém-nascido e lactentes, porém quando a doença do refluxo gastroesofágico (DRGE) acontece,\nhá necessidade de tratamento médico. Qual dos\nachados abaixo NÃO faz parte do quadro de\nDRGE?","options":{"A":"Irritabilidade extrema.","B":"Ganho ponderal adequado.","C":"Arqueamento do tronco.","D":"Recusa alimentar."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-159055","number":"159055","sourceNumber":"159055","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação à diarréia aguda na infância NÃO se pode afirmar:","options":{"A":"É definida como a eliminação súbita de fezes de conteúdo líquido acima do habitual, associada a\num aumento do número de evacuações.","B":"Se caracteriza pela ocorrência de má absorção intestinal de água e eletrólitos.","C":"Tem uma evolução potencialmente autolimitada, com duração inferior ou igual a 7 dias.","D":"De etiologia infecciosa na grande maioria dos casos, com duração inferior ou igual a 14 dias."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-159051","number":"159051","sourceNumber":"159051","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Não pode ser considerada uma característica da faringoamigdalite na infância:","options":{"A":"Faringoamigdalite estreptocócica (Streptococos beta hemolítico do grupo A) é a causa mais\ncomum das amigdalites bacterianas.","B":"Tosse frequente, rouquidão e diarréia são manifestações clínicas caracteristicas da amigdalite\nviral.","C":"A faixa etária de maior prevalência da amigdalite bacteriana é entre 5 a 11 anos.","D":"A síndrome nefrótica é uma sequela tardia da amigdalite estreptocócica."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-135990","number":"135990","sourceNumber":"135990","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Enfermeira de uma USF da Capital, responsável pela sala de vacinas, é perguntada\npor um Acadêmico de Medicina sobre o tempo\nmínimo entre a primeira dose da vacina contra a\nHepatite B, que é ao nascer, e a segunda dose, sendo a resposta dada:","options":{"A":"30 dias;","B":"45 dias;","C":"60 dias;","D":"90 dias;"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-108624","number":"108624","sourceNumber":"108624","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação à vacina antipneumocócica 10-valente, é INCORRETO afirmar:","options":{"A":"Induz resistência ao S. pneumoniae contra a penicilina.","B":"É eficaz em reduzir em torno de 50% dos casos de otite média aguda pneumocócica.","C":"Modificou a etiologia das IVAS, nos locais onde faz parte do calendário oficial de vacinação\npública.","D":"Aumenta a incidência de IVAS por sorotipos não contidos na vacina."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-84522","number":"84522","sourceNumber":"84522","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A mãe do recém-nascido João pergunta ao médico do que é composta a nova vacina\npentavalente, recomendada pelo Ministério da Saúde a partir de 2012. Assinale a alternativa que\napresenta o que o médico deve responder.","options":{"A":"DPT + Hib + hepatite B.","B":"DPT + Hib + BCG.","C":"DPT + BCG + hepatite B.","D":"DPT + Hib + VIP.","E":"DPT + BCG + VIP."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-84454","number":"84454","sourceNumber":"84454","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A vacina profilática contra o papilomavírus humano está indicada para a população\nfeminina de que faixa etária?","options":{"A":"29 a 36 anos.","B":"9 a 26 anos.","C":"19 a 46 anos.","D":"16 a 29 anos.","E":"26 a 39 anos."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-372084","number":"372084","sourceNumber":"372084","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual das alternativas a seguir apresenta definição mais adequada para broncogramas\naéreos?","options":{"A":"Consolidação com áreas de aspecto sólido hipoecogênicas subpleurais.","B":"Dimensões maiores dos brônquios no período neonatal.","C":"Consolidações em localização mais profunda que não se estendem até a pleura.","D":"Formações ecogênicas lineares."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343180","number":"343180","sourceNumber":"343180","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa correta sobre o(s) exame(s) complementar(es) indicado(s) no\ndiagnóstico diferencial da bronquiolite obliterante.","options":{"A":"Tomografia de tórax.","B":"Raio X e ressonância magnética de tórax.","C":"Raio X de tórax, eletrocardiograma e ecocardiograma.","D":"Hemograma, DHL e ácido úrico."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343194","number":"343194","sourceNumber":"343194","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. A principal hipótese diagnóstica é:","options":{"A":"Displasia neuronal do tipo B.","B":"Constipação funcional.","C":"Doença de Hirschsprung.","D":"Enterocolite necrotizante."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343195","number":"343195","sourceNumber":"343195","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. Das alternativas abaixo, a conduta mais adequada é:","options":{"A":"Cirurgia de urgência.","B":"Tratamento clínico com ajuste dietéticos e laxativos, apenas.","C":"Dieta zero, sonda gástrica em drenagem e antibioticoterapia.","D":"Colostomia e abaixamento de cólon posteriormente ou manejo de cólon e tratamento cirúrgico\nendoanal sem colostomia."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-314201","number":"314201","sourceNumber":"314201","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"O diário das eliminações é uma ferramenta importante para a avaliação, o diagnóstico e\naté mesmo para o controle terapêutico das disfunções do trato urinário inferior e da disfunção\nvesical e intestinal. Nesse sentido, assinale a afirmativa correta.","options":{"A":"A utilização da EB, na análise dos hábitos intestinais, é mais aceita para o diagnóstico de\nconstipação funcional na população pediátrica.","B":"A obtenção de diários longos é mais comumente indicada.","C":"A utilização de questionários, alguns padronizados e validados, pode ser útil e complementar\npara a padronização e a avaliação dos sintomas\nurinários.","D":"O diário das eliminações é uma ferramenta para a avaliação e o diagnóstico de disfunção do\ntrato urinário inferior e da disfunção vesical e intestinal, não indicada para o controle\nterapêutico."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-313439","number":"313439","sourceNumber":"313439","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Todas as alternativas abaixo apresentam causa de tosse em pediatria; assinale aquela\nque apresenta a causa mais frequente de tosse aguda.","options":{"A":"Asma.","B":"Pneumonia.","C":"Linfangite.","D":"Resfriado comum."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-313440","number":"313440","sourceNumber":"313440","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"O uso do cateter nasal de alto fluxo pode trazer alguns efeitos adversos. Das\nalternativas abaixo assinale aquela que apresenta\nos principais efeitos adversos relacionados à\nventilação com cateter nasal de alto fluxo.","options":{"A":"Aerofagia e epistaxe.","B":"Pneumomediastino e pneumonia aspirativa.","C":"Pneumotórax e descolamento de retina.","D":"Agitação e cefaleia."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-315178","number":"315178","sourceNumber":"315178","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa VERDADEIRA:","options":{"A":"O sinal mais confiável para o diagnóstico de Otite Media Aguda (OMA) é o abaulamento de\nmembrana timpânica.","B":"A hiperemia de membrana timpânica é sinal confiável de OMA.","C":"Otorreia purulenta é sinal patognomônico de OMA.","D":"Recomenda-se dose única de Ceftriaxona na OMA.","E":"OMA é sinônimo de antibioticoterapia."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-314208","number":"314208","sourceNumber":"314208","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Considerando o diagnóstico e manifestações clínicas da Sinusite Aguda em pediatria,\nassinale a alternativa correta.","options":{"A":"IVAS virais, sinusite crônica e rinite alérgica integram o diagnóstico diferencial da sinusite\naguda.","B":"O exame de imagem é indicado na sinusite aguda apenas quando houver suspeita de\ncomplicações intracranianas ou para esclarecer a natureza da enfermidade.","C":"Queixas de cefaleia e dor facial (no seio da face afetado ou nos dentes) são bastante comuns\nem adolescentes e crianças.","D":"A cultura de aspirado do seio da face é um método utilizado como rotina para o diagnóstico."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-313446","number":"313446","sourceNumber":"313446","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente masculino previamente hígido, sem nenhuma comorbidade antenatal, hoje\ncom 6 semanas de vida, é levado ao\natendimento de urgência pela mãe com queixa de vômitos de\ninício há 7 dias. A mãe descreve vômitos de conteúdo alimentar, mais intensos após as mamadas,\nem jato, sem exteriorização de conteúdo bilioso. Associa a este período uma piora no estado geral,\nbem como perda ponderal. Nega febre. Nega diarreia. Nega trauma. Ao exame físico encontra-se\ndescorado, desidratado, taquipneico, normocárdico, anictérico, acianótico, afebril. Aparelho\ncardiopulmonar sem alterações importantes. Ausência de sinais de irritação meníngea, com\nfontanela anterior discretamente deprimida. Abdome com ruídos, flácido, distendido em andar\nsuperior, indolor, sem sinais de irritação peritoneal. Ausência de massas palpáveis. Foi realizado\nexames séricos que evidenciaram discreta leucocitose e alcalose metabólica. Foi submetido a\nradiografia de abdome abaixo. O tratamento definitivo mais adequado para este caso é:","options":{"A":"Tratamento clínico com inibidor de bomba de prótons e orientação dietética.","B":"Piloromiotomia.","C":"Ligadura da fístula traqueoesofágica e anastomose esôfago-esofágica término-terminal se\nhouver distância entre os cotos menor que 3 vértebras.","D":"Gastrostomia e anastomose esôfago-esofágica tardia."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-313447","number":"313447","sourceNumber":"313447","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente masculino previamente hígido, sem nenhuma comorbidade antenatal, hoje\ncom 6 semanas de vida, é levado ao\natendimento de urgência pela mãe com queixa de vômitos de\ninício há 7 dias. A mãe descreve vômitos de conteúdo alimentar, mais intensos após as mamadas,\nem jato, sem exteriorização de conteúdo bilioso. Associa a este período uma piora no estado geral,\nbem como perda ponderal. Nega febre. Nega diarreia. Nega trauma. Ao exame físico encontra-se\ndescorado, desidratado, taquipneico, normocárdico, anictérico, acianótico, afebril. Aparelho\ncardiopulmonar sem alterações importantes. Ausência de sinais de irritação meníngea, com\nfontanela anterior discretamente deprimida. Abdome com ruídos, flácido, distendido em andar\nsuperior, indolor, sem sinais de irritação peritoneal. Ausência de massas palpáveis. Foi realizado\nexames séricos que evidenciaram discreta leucocitose e alcalose metabólica. Foi submetido a\nradiografia de abdome abaixo. O distúrbio ácido-base encontrado é mais bem justificado na\nseguinte alternativa.","options":{"A":"A alcalose metabólica é a alteração mais comum encontrada nestes pacientes devido a grande\nperda de ácidos pelos vômitos incoercíveis\ne repetidos.","B":"A alcalose metabólica é a alteração menos encontrada nestes pacientes devido a grande perda\nde bicarbonato, devido ao aumento da excreção\nrenal de bicarbonato.","C":"A alcalose respiratória é a alteração mais comum encontrada nestes pacientes devido a grande\nperda de ácidos pelos vômitos incoercíveis\ne repetidos.","D":"A alcalose metabólica não é o distúrbio mais comum encontrado nestes pacientes. Tratando-se\nda patologia acima a acidose metabólica é o\nachado mais comum em pacientes com este\ndiagnóstico devido a grande perda volêmica."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-313452","number":"313452","sourceNumber":"313452","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A apendicite aguda em neonatos e lactentes, faixa etária incomum para a apresentação\ndesta patologia, tem forte associação com:","options":{"A":"Estenose hipertrófica de piloro.","B":"Atresia duodenal.","C":"Atresia esofágica.","D":"Doença de Hirschsprung."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307066","number":"307066","sourceNumber":"307066","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina, 2 meses de idade, nascida a termo com peso: 3.200g e comprimento: 49cm,\nusando apenas leite materno, sugando\nadequadamente, é levada à UBS com relato de cólicas e\ndiarreia, além de regurgitações esparsas. Ao exame, peso: 4.000g: comprimento: 54cm. Está ativa,\nem bom estado geral, hidratada, eupneíca, afebril, corada. Observam-se algumas manchas\navermelhadas na pele, principalmente em face e dobras. A mãe informa que ficam mais claras após\no banho. Diante do quadro descrito, indique a principal suspeita diagnóstica.","options":{"A":"Doença metabólica primária.","B":"Síndrome do intestino irritável.","C":"Alergia à proteína do leite de vaca.","D":"Gastrite por refluxo gastroesofágico."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307067","number":"307067","sourceNumber":"307067","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina, 2 meses de idade, nascida a termo com peso: 3.200g e comprimento: 49cm,\nusando apenas leite materno, sugando\nadequadamente, é levada à UBS com relato de cólicas e\ndiarreia, além de regurgitações esparsas. Ao exame, peso: 4.000g: comprimento: 54cm. Está ativa,\nem bom estado geral, hidratada, eupneíca, afebril, corada. Observam-se algumas manchas\navermelhadas na pele, principalmente em face e dobras. A mãe informa que ficam mais claras após\no banho. A conduta diagnóstica adequada, nessa situação, é:","options":{"A":"Solicitar manometria esofágica.","B":"Realizar teste de provocação oral.","C":"Solicitar RAST para leite de vaca.","D":"Solicitar endoscopia digestiva alta."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307068","number":"307068","sourceNumber":"307068","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina, 2 meses de idade, nascida a termo com peso: 3.200g e comprimento: 49cm,\nusando apenas leite materno, sugando\nadequadamente, é levada à UBS com relato de cólicas e\ndiarreia, além de regurgitações esparsas. Ao exame, peso: 4.000g: comprimento: 54cm. Está ativa,\nem bom estado geral, hidratada, eupneíca, afebril, corada. Observam-se algumas manchas\navermelhadas na pele, principalmente em face e dobras. A mãe informa que ficam mais claras após\no banho. A conduta terapêutica imediata, mais adequada, no caso descrito, é:","options":{"A":"Substituir leite materno por fórmula de aminoácidos.","B":"Substituir leite materno por fórmula de soja.","C":"Suspender derivados do leite na dieta materna.","D":"Prescrever probiótico e manter o aleitamento materno como está."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307072","number":"307072","sourceNumber":"307072","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina, 3 anos de idade, é trazida à UPA com história de inapetência, coriza e febre\nbaixa há uma semana, passando a apresentar\ntosse seca. A febre aumentou de intensidade e a\ntosse tornou-se produtiva há, aproximadamente, 4 dias. No momento, encontra-se hipoativa, em\nregular estado geral. Temperatura: 38,6ºC, FR: 125ipm, com tiragem intercostal. À ausculta mostra\nroncos e crépitos disseminados. Sem outros achados anormais ao exame segmentar. Indique o\nagente etiológico mais provável do quadro atual:","options":{"A":"Adenovírus.","B":"Haemophilus influenzae.","C":"Vírus Sincicial respiratório.","D":"Streptococcus pneumoniae."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307073","number":"307073","sourceNumber":"307073","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina, 3 anos de idade, é trazida à UPA com história de inapetência, coriza e febre\nbaixa há uma semana, passando a apresentar\ntosse seca. A febre aumentou de intensidade e a\ntosse tornou-se produtiva há, aproximadamente, 4 dias. No momento, encontra-se hipoativa, em\nregular estado geral. Temperatura: 38,6ºC, FR: 125ipm, com tiragem intercostal. À ausculta mostra\nroncos e crépitos disseminados. Sem outros achados anormais ao exame segmentar. Considere os\nelementos fisiopatológicos apresentados e identifique os que atuam modificando o processo de\nevolução do quadro dessa criança: I) Aumento da secreção brônquica. II) Aumento da atividade\nciliar. III) Alteração na produção de anticorpos. IV) Redução da ação bactericida dos macrófagos\nalveolares. Indique a alternativa que contém as respostas corretas.","options":{"A":"I, II e III","B":"I, II e IV","C":"I, III e IV","D":"II, III e IV"},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307074","number":"307074","sourceNumber":"307074","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina, 3 anos de idade, é trazida à UPA com história de inapetência, coriza e febre\nbaixa há uma semana, passando a apresentar\ntosse seca. A febre aumentou de intensidade e a\ntosse tornou-se produtiva há, aproximadamente, 4 dias. No momento, encontra-se hipoativa, em\nregular estado geral. Temperatura: 38,6ºC, FR: 125ipm, com tiragem intercostal. À ausculta mostra\nroncos e crépitos disseminados. Sem outros achados anormais ao exame segmentar. Sobre o uso\nde radiografia de tórax em crianças, em situações como a descrita, pode-se afirmar:","options":{"A":"É imprescindível para indicar hospitalização.","B":"É imprescindível para iniciar o tratamento específico.","C":"Fornece indícios sobre a etiologia do processo.","D":"É inespecífica e demanda mais exames para tratamento."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-280409","number":"280409","sourceNumber":"280409","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa correta em relação à diarreia crônica de caráter funcional.","options":{"A":"A vitamina A é particularmente importante para a melhoria do processo diarreico.","B":"O uso de lactose na dieta da criança deve sempre ser restringido desde o início do quadro.","C":"O excesso de açúcares na dieta deve ser corrigido, assim como se indica restringir os sucos\nricos em sorbitol.","D":"Utilizam-se fórmulas de proteína extremamente hidrolisada."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-280413","number":"280413","sourceNumber":"280413","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre o diagnóstico diferencial das manifestações de alarme para causas orgânicas de\ndor abdominal, assinale a alternativa incorreta.","options":{"A":"Na avaliação clínica da dor abdominal da criança não devem ser esquecidas as causas agudas\ncomo apendicite aguda.","B":"O teste genético oferece informações sobre tolerância à lactose e indica má absorção nos\nprimeiros anos de vida.","C":"Na prática para caracterização laboratorial da hipolactasia do tipo adulto, pode ser usado o\nteste\nda sobrecarga de lactose.","D":"Existem dois subtipos de dispepsia funcional: a síndrome de desconforto pós-prandial e a\nsíndrome da dor epigástrica."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-275989","number":"275989","sourceNumber":"275989","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"João, 4 anos, está com odinofagia, coriza abundante e obstrução nasal há 3 dias. É o\nsexto episódio no ano. O médico diagnosticou o quadro como resfriado comum. Em relação a esse\nquadro, assinale a alternativa INCORRETA.","options":{"A":"As duas principais complicações desse quadro são a otite média aguda e a sinusite bacteriana\naguda.","B":"O tratamento consiste essencialmente em hidratação, lavagem nasal com soro fisiológico,\nantipiréticos, caso haja febre, e analgésicos, caso haja dor.","C":"Um dos medicamentos a serem utilizados no quadro de resfriado comum é o AAS, uma vez que,\npor não ter contraindicações importantes,\npode ser utilizado com segurança.","D":"Tanto a otite média aguda quanto a sinusite bacteriana aguda possuem os mesmos agentes\netiológicos: Streptococcus pneumoniae, Haemophilus influenzae e Moraxella catarrhalis.","E":"O principal agente etiológico é o rinovírus."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-280415","number":"280415","sourceNumber":"280415","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"São opções de desimpactação fecal todas as abaixo, exceto:","options":{"A":"Lactulose.","B":"Polietileno glicol.","C":"Solução salina.","D":"Supositório."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-275990","number":"275990","sourceNumber":"275990","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"As infecções das vias aéreas inferiores são responsáveis por grande parte dos óbitos\nrelacionados às infecções respiratórias agudas. Em relação a esse tema, assinale a alternativa\nINCORRETA.","options":{"A":"No lactente, alguns dos principais sinais que indicam uma gravidade do quadro de pneumonia\nbacteriana por micro-organismos típicos são batimento de asa nasal, gemência e cianose.","B":"O tratamento recomendado da pneumonia afebril do lactente consiste na administração de\neritromicina ou azitromicina.","C":"A pneumonia bacteriana por micro-organismos típicos tem como principal agente etiológico em\ntodas as faixas etárias, excetuando o período neonatal, o Streptococcus pneumoniae.","D":"A bronquiolite viral aguda caracteristicamente provoca o primeiro episódio de sibilância nos\nprimeiros anos de vida.","E":"Os principais agentes etiológicos da pneumonia afebril do lactente são E. coli e M. pneumoniae."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-278626","number":"278626","sourceNumber":"278626","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Levando-se em consideração a patogênese e manifestações clinicas da Otite Média\nAguda (OMA), assinale a alternativa incorreta.","options":{"A":"A obstrução tubária de caráter extraluminal inclui tecido linfoide nasofaríngeo hipertrofiado ou\ntumor.","B":"Febre, anorexia, diarreia e otorréia purulenta são sinais sistêmicos da OMA.","C":"A obstrução tubaria de caráter intraluminal é caracterizada por edema inflamatório da mucosa\ntubária, mais comumente causado por infecção aguda das vias aéreas.","D":"A maioria dos episódios de OMA é iniciado em casos de IVAS de origem viral ou bacteriana,\nmas a OMA também pode se desenvolver na\nausência dessa infecção."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-279047","number":"279047","sourceNumber":"279047","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a bactéria Streptococcus pneumoniae, assinale a alternativa correta.","options":{"A":"A metodologia padrão ouro para a identificação dos sorotipos circulantes é a PCR clássica.","B":"O pneumococo é classificado em cerca de 70 sorotipos até o momento.","C":"As bactérias do gênero Streptococcus se caracterizam morfologicamente por serem cocos\nGRAM positivos, com morfologia de diplococos,\narranjados aos pares ou em cadeias curtas.","D":"A capacidade de causar doença no homem varia pouco entre os sorotipos de Streptococcus."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-278628","number":"278628","sourceNumber":"278628","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa incorreta sobre a constipação em crianças.","options":{"A":"Pode ocorrer em diversas faixas etárias, sobretudo em crianças do sexo masculino e em idade\npré-escolar.","B":"Na grande maioria dos casos, é proveniente de causa benigna.","C":"Trata-se de uma das acusas mais comuns de procura ao pronto socorro.","D":"São diagnósticos diferenciais alterações neurológicas, doença de Hirshsprung e malformações\nanorretais."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-279049","number":"279049","sourceNumber":"279049","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual das alternativas a seguir não é uma complicação do íleo meconial?","options":{"A":"Volvo.","B":"Perfuração.","C":"Peritonite.","D":"Má rotação."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-275996","number":"275996","sourceNumber":"275996","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A desidratação na criança é uma condição que deve ser analisado com cautela. Uma\ndas causas principais de desidratação na\ninfância é a gastroenterite aguda. Após classificar o\nestado de desidratação, o tratamento deve ser instituído. No plano A, os responsáveis pela criança\ndevem orientados a buscar assistência médica caso haja algum dos sinais de gravidade. Em\nrelação a esse tema, qual alternativa abaixo não consiste em um sinal de gravidade?","options":{"A":"Aparecimento ou piora da febre.","B":"Ausência de sangue nas fezes.","C":"Não conseguir beber nem mamar no peito.","D":"Piora do estado geral.","E":"Dificuldade para beber."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-279052","number":"279052","sourceNumber":"279052","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual é a complicação mais temida e potencialmente fatal da doença de Hirschsprung\nnão diagnosticada?","options":{"A":"Perfuração intestinal.","B":"Volvo.","C":"Enterocolite.","D":"Neoplasia."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-279053","number":"279053","sourceNumber":"279053","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"O principal objetivo no manejo do paciente com bronquiolite viral aguda é:","options":{"A":"Garantir que o paciente aceite a dieta habitual e não tenha sinais de agravo do ponto d evista\nrespiratório.","B":"Reduzir a possibilidade de intubação orotraqueal.","C":"Controlar a evolução da febre.","D":"Reduzir o processo de evolução da doença para a forma grave, indicando internação precoce\nem todos os casos."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283748","number":"283748","sourceNumber":"283748","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino, 3 anos de idade, chega à Unidade de Pronto Atendimento, UPA, com\ndificuldade respiratória há aproximadamente 12\nhoras. A senhora relata febre e tosse produtiva há\n3 dias. No momento, encontra-se em estado geral comprometido; taquipneico, com tiragem\nsubcostal; T.: 39ºC; FC: 120bpm; FR: 38ipm; SatO? : 88% em ar ambiente. A ausculta respiratória\nevidencia murmúrios vesiculares hipoaudíveis em base do hemitórax direito. A Radiografia de tórax\nem PA e perfil mostra opacificação em 1/3 inferior com obliteração do seio costo-frênico à Direita.\n\nIndique o agente etiológico mais provável, nesse caso.","options":{"A":"Streptococcus pneumoniae.","B":"Staphylococcus aureus.","C":"Moraxella catarrhalis.","D":"Enterobactéria."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-283749","number":"283749","sourceNumber":"283749","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino, 3 anos de idade, chega à Unidade de Pronto Atendimento, UPA, com\ndificuldade respiratória há aproximadamente 12\nhoras. A senhora relata febre e tosse produtiva há\n3 dias. No momento, encontra-se em estado geral comprometido; taquipneico, com tiragem\nsubcostal; T.: 39ºC; FC: 120bpm; FR: 38ipm; SatO? : 88% em ar ambiente. A ausculta respiratória\nevidencia murmúrios vesiculares hipoaudíveis em base do hemitórax direito. A Radiografia de tórax\nem PA e perfil mostra opacificação em 1/3 inferior com obliteração do seio costo-frênico à Direita.\n\nIdentifique o antibiótico preconizado no SUS, como primeira escolha, para iniciar, no momento, o\ntratamento, dessa criança.","options":{"A":"Oxacilina.","B":"Ceftriaxone.","C":"Gentamicina.","D":"Penicilina Cristalina."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-231343","number":"231343","sourceNumber":"231343","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa verdadeira:","options":{"A":"Na insuficiência respiratória os sinais mais confiáveis são taquipneia, batimento de asa do\nnariz,\ngemência e tiragem.","B":"A oferta suplementar de oxigênio inalatório é suficiente em todas as fases da insuficiência\nrespiratória","C":"A saturação de O2 mínima na sala de emergência pode ser recomendada como de 89%","D":"Recomenda-se no trauma a suplementação de O2 apenas se Escala de Coma de Gasglow\nmenor ou igual a 8.","E":"A ventilação com pressão positiva é utilizada apenas na fase quatro da insuficiência\nrespiratória"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-231347","number":"231347","sourceNumber":"231347","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a diarreia aguda na infância é CORRETO afirmar:","options":{"A":"O leite de vaca deve ser retirado da dieta","B":"É um quadro, na maioria das vezes, auto limitado","C":"Deve-se optar por dieta constipante","D":"A etiologia mais frequente nos meses quentes é rotavírus","E":"Se o quadro for muito intenso deve ser ministrado antidiarreico"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-249288","number":"249288","sourceNumber":"249288","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa correta em relação à laringomalácia.","options":{"A":"É a principal causa de estridor de início agudo no lactente.","B":"Pode estar associada à faringomalácia em pacientes com comorbidades neurológicas.","C":"A conduta inicial é a traqueostomia.","D":"A supraglotoplastia é a cirurgia de escolha e deve ser realizada em todos os casos, pois trata de\num procedimento de baixa morbidade."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-249296","number":"249296","sourceNumber":"249296","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre os episódios de sibilância em crianças, assinale a alternativa correta:","options":{"A":"Toda sibilância é indicada.","B":"O refluxo gastroesofágico e as infecções respiratórias virais recorrentes são diagnósticos\ndiferencias comuns.","C":"A sibilância recorrente é bem frequente em crianças com até 7 anos de idade.","D":"A sibilância por infecção viral é sempre uma apresentação clínica inicial da asma."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-249297","number":"249297","sourceNumber":"249297","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação aos sinais de alerta da cólica do lactente, assinale a alternativa correta:","options":{"A":"Choro extremamente alto.","B":"Ritmo do choro também durante o dia.","C":"Sintomas após 3 meses.","D":"Ingesta de drogas por parte da mãe."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-249409","number":"249409","sourceNumber":"249409","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa correta sobre os distúrbios funcionais do tubo digestivo, segundo\nos critérios de Roma:","options":{"A":"São comuns em crianças abaixo de 4 anos, sendo a cólica infantil o distúrbio mais encontrado.","B":"Apresentam diferenças em relação ao gênero e à raça, sendo mais prevalente em meninas.","C":"São mais prevalentes em filhos mais novos e em crianças de pais divorciados ou separados.","D":"Têm como quadro clínico crianças com fezes mais duras quando os pais também apresentam\nfezes endurecidas."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-252930","number":"252930","sourceNumber":"252930","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino, 30 meses de idade, é levado à UPA com febre há 72 horas. Sua mãe refere\nque a temperatura tem ultrapassado os 39ºC\nque o menor não tem aceito alimentos, vem\napresentando irritabilidade e diminuiu as eliminações (atribuindo à reduzida ingestão). No momento,\na temperatura é 39,6ºC. Não foram observadas alterações ao exame físico segmentar.\n\nConsiderando os aspectos do caso relatado, indique o parâmetro de maior confiabilidade no\nleucograma dessa criança para a suspeita diagnóstica de causa bacteriana.","options":{"A":"Contagem global acima de 15 mil cel/mm³.","B":"Contagem global de neutrófilos acima de 6000 cel/mm³.","C":"Contagem de bastões maior que 5%.","D":"Contagem de segmentados maior que 70%."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-252931","number":"252931","sourceNumber":"252931","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino, 30 meses de idade, é levado à UPA com febre há 72 horas. Sua mãe refere\nque a temperatura tem ultrapassado os 39ºC\nque o menor não tem aceito alimentos, vem\napresentando irritabilidade e diminuiu as eliminações (atribuindo à reduzida ingestão). No momento,\na temperatura é 39,6ºC. Não foram observadas alterações ao exame físico segmentar. Identifique o\nprincipal agente responsável por bacteremia oculta na faixa etária dessa criança.","options":{"A":"Escherichia coli.","B":"Streptococcus pneumoniae.","C":"Haemophilus influenzae.","D":"Salmonella sp."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-201793","number":"201793","sourceNumber":"201793","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A pneumonia bacteriana é ainda uma das grandes causas de morbimortalidade em\nespecial em crianças pequenas. Assinale a alternativa CORRETA:","options":{"A":"Em lactentes os achados mais importantes do exame físico são as alterações de ausculta\nrespiratória.","B":"O Ra de tórax deve ser considerado de rotina na\ninvestigação diagnóstica de pneumonia da\ncomunidade.","C":"O leucograma e Proteína C Reativa (PCR) tem\nexcelente acurácia em diferenciar pneumonia\nbacteriana e viral.","D":"A taquipneia é sinal relevante, sendo ponto de corte para definição a freq. respiratória acima de\n40 irpm para crianças de 1 a 4 anos.","E":"Em geral pneumatocele, consolidação, derrame\npleural sugerem etiologia viral."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-216306","number":"216306","sourceNumber":"216306","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Na síndrome hemolítica urêmica há a presença de qual das células no sangue\nperiférico?","options":{"A":"Hemácias em foice.","B":"Esquisócitos.","C":"Hemácias em alvo.","D":"Granulações tóxicas."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-216245","number":"216245","sourceNumber":"216245","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual das alternativas apresenta a tríade da Síndrome Hemolítica Urêmica?","options":{"A":"Anemia hemolítica, hipoalbuminemia e plaquetose.","B":"Anemia hemolítica, insuficiência renal aguda e trombocitopenia.","C":"Anemia hemolítica, hipoalbuminemia e plaquetopenia.","D":"Anemia hemolítica, insuficiência renal aguda e hipertensão arterial."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-219900","number":"219900","sourceNumber":"219900","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente do sexo masculino, na quinta semana de vida, previamente hígido, apresenta\nvômitos não biliosos há 1 semana, em jato.\nAo exame físico nota-se perda de peso e sinais de\ndesidratação leve. Considerando tratar-se de patologia com indicação cirúrgica, o diagnóstico MAIS\nPROVÁVEL é:","options":{"A":"Atresia jejunal","B":"Estenose hipertrófica de piloro","C":"Hérnia inguinal estrangulada.","D":"Volvo intestinal agudo."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-219850","number":"219850","sourceNumber":"219850","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pré-escolar de 3 anos com relato de diarreia há 5 dias, fezes líquidas e fétidas, sem\nsangue ou pus. Mãe foi orientada a fazer\nuso de hidratação frequente em casa com água e sucos,\nmas não houve melhora. Há 2 dias a criança evoluiu também com vômitos. O achado clínico que\npermite a utilização de Terapia de Reidratação Oral nessa situação é:","options":{"A":"Alteração de consciência com escala de coma de Glasgow entre 10 e 12 pontos.","B":"Aumento da frequência cardíaca com frequência de 160 batimentos por minuto.","C":"Íleo paralítico grave com distensão abdominal e ausência de ruídos hidroaéreos.","D":"Vômitos persistentes com frequência maior do que seis em uma hora."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-219871","number":"219871","sourceNumber":"219871","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 5 meses de idade está evoluindo com regurgitações e choro frequentes. A\nmãe vem à consulta questionando a\npossibilidade de \"refluxo\" pois o filho de sua vizinha tem os\nmesmos sintomas e está usando medicação para tratamento. Não há outros sintomas associados.\nA criança recebe leite materno e alimentação complementar com papas e frutas. O peso da criança\nestá entre os escores Z zero e +1. Ao exame físico, não existem alterações. Com relação à conduta\ninicial relacionada a este caso, a afirmativa CORRETA é:","options":{"A":"Recomendar a exclusão de proteína do leite de vaca da alimentação por 2 a 4 semanas.","B":"Recomendar o fracionamento das refeições e posição vertical pós-alimentação.","C":"Recomendar o início de tratamento com medicação pró-cinética como a domperidona.","D":"Recomendar o posicionamento em decúbito lateral direito para diminuir os episódios de refluxo."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-219857","number":"219857","sourceNumber":"219857","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 3 meses que, segundo a mãe, apresenta evacuações espontâneas com\nfezes explosivas, mas de consistência habitual\npara um lactente, a cada 15 dias. Está fazendo uso\nde supositório a cada 3 dias para que ocorra a evacuação. Há relato de distensão abdominal e\ncólicas frequentes. Ao exame físico, o abdome é tenso e difusamente doloroso. O lactente está em\naleitamento materno exclusivo. Considerando os possíveis diagnósticos para o quadro, a conduta e\ndiagnóstico MAIS ADEQUADOS são:","options":{"A":"Iniciar dieta laxativa com suco de frutas e considerar como hábito intestinal do lactente em\naleitamento.","B":"Prescrever laxativo por via oral e considerar como constipação crônica funcional","C":"Solicitar colonoscopia com biópsia e considerar como doença inflamatória intestinal.","D":"Solicitar enema baritado por via baixa e considerar como aganglionose colônica."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-215496","number":"215496","sourceNumber":"215496","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A moléstia de Hirschsprung é a suboclusão intestinal baixa decorrente da ausência de\ngânglios nervosos entéricos. Assinale a alternativa INCORRETA.","options":{"A":"O quadro clínico é de retardo de eliminação do mecônio, distensão abdominal acentuada e\nevacuação explosiva ao toque.","B":"A doença praticamente inexiste em prematuros e os sintomas, quase sempre, se iniciam após o\nsegundo mês de vida, predominando no sexo\nfeminino.","C":"O diagnóstico é feito pelo enema opaco que mostra o cólon proximal dilatado e o terminal\nestreitado, formando o clássico cone de transição.","D":"O tratamento é cirúrgico e consiste na ressecção do segmento ganglionar e reconstrução do\ntrânsito anal."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-219882","number":"219882","sourceNumber":"219882","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Estudante de 18 anos do sexo masculino apresenta rinorreia, febre não termometrada e\ndor de garganta há dois dias. Sem passado mórbido de importância. Ao exame, apresenta\nfrequência cardíaca = 100 bpm, frequência respiratória = 20 irpm e temperatura axilar = 39,3°C; a\nfaringe está hiperemiada e há exsudato branco sobre as tonsilas. Sem outras alterações ao exame\nfísico. Qual dos seguintes microorganismos é o agente causal MAIS PROVÁVEL desse quadro?","options":{"A":"Candida albicans.","B":"Haemophilus influenzae.","C":"Staphylococcus aureus.","D":"Streptococcus pyogenes."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-212165","number":"212165","sourceNumber":"212165","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Enrico, 11 meses e 4 dias, vem apresentando quadro de febre diária (39 °C) há cerca\nde 1 semana, bem como tosse, inicialmente\nseca e agora produtiva. Sua genitora refere ainda\ninapetência, recusa de líquidos e sonolência excessiva. Ao exame físico, sua frequência respiratória\né de 55 ipm, com a presença de estertores finos em hemitórax direito à ausculta pulmonar, tiragem\nsubcostal importante e batimento de asa do nariz. De acordo com as características descritas, qual\na hipótese diagnóstica mais provável e qual a melhor conduta terapêutica para Enrico?","options":{"A":"Pneumonia comunitária, devendo ser realizado tratamento ambulatorial, com cobertura para o\nStreptococcus pneumoniae.","B":"Pneumonia comunitária grave, devendo ser realizado internamento hospitalar, monitorização e\nantibioticoterapia endovenosa, para cobertura da Chlamydia trachomatis.","C":"Pneumonia comunitária muito grave, devendo ser realizado internamento hospitalar,\nmonitorização e antibioticoterapia endovenosa para cobertura da Listeria monocytogenes.","D":"Pneumonia comunitária grave, devendo ser realizado internamento hospitalar, monitorização e\nantibioticoterapia endovenosa, para cobertura do Streptococcus pneumoniae.","E":"Pneumonia comunitária muito grave, devendo ser realizado internamento hospitalar,\nmonitorização e antibioticoterapia endovenosa,\npara cobertura do Streptococcus pneumoniae."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-212233","number":"212233","sourceNumber":"212233","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"José Vinícius, 1 mês e 5 dias de vida, há uma semana começou a apresentar episódios\nde vômitos, em jato, com restos alimentares, 30\nminutos após a alimentação, porém com fome\ninsaciável, perda de peso e desidratação. À palpação do abdome, notou-se distensão da região\nepigástrica e ondas de Kussmaul após a alimentação. Nesse contexto, qual é a principal hipótese\ndiagnóstica e como essa hipótese pode ser confirmada?","options":{"A":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do duplo trilho\ne sinal do cordão, obtidos quando pequenas\nquantidades de líquido podem ser vistas aprisionadas entre as dobras de mucosa ecogênica\nredundante.","B":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do mamilo\nmucoso, que corresponde ao anel hiperecoico do\nmúsculo pilórico hipertrofiado em torno da mucosa ecogênica centralmente localizada.","C":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do alvo,\nobtido quando pequenas quantidades de líquido podem\nser vistas aprisionadas entre as dobras de mucosa ecogênica redundante.","D":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal da cérvice,\nque corresponde à protrusão de mucosa pilórica\nredundante em direção ao antro gástrico.","E":"Estenose hipertrófica de piloro, podendo realizar ultrassonografia do trato gastrointestinal\nsuperior para visualização do sinal do ombro,\nque corresponde à endentação da camada muscular\nno antro cheio de líquido."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-212221","number":"212221","sourceNumber":"212221","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Josué, 3 anos e 11 meses, começou a apresentar febre (38 °C) há 72 horas, bem como\nvários episódios de vômitos e aumento do número de evacuações, sem muco ou sangue, seguido\nde torpor e extremidades frias. Sua genitora, notando que havia também diminuído o volume de\ndiurese e ocorrido perda ponderal, procurou então atendimento em serviço de emergência, quando\nfoi instituída hidratação endovenosa. Seu peso anterior ao quadro era 20 kg e no momento de\nadmissão hospitalar foi 17 kg. Nesse caso, é correto afirmar que se trata de quadro de desidratação","options":{"A":"moderada (perda ponderal até 10%), com sinais possíveis de choque associado, permanecendo\na indicação de hidratação venosa.","B":"grave (perda ponderal 5-10%), possivelmente associada a choque, com correta administração\nde terapia de hidratação endovenosa.","C":"grave (perda ponderal até 10%), sem sinais possíveis de choque associado. Apesar disso,\npermanece a indicação de hidratação venosa.","D":"grave (perda ponderal acima de 10%), possivelmente associada a choque, tendo sido correta a\nindicação de hidratação endovenosa.","E":"moderada (perda ponderal acima de 10%), com sinais possíveis de choque associado. Apesar\ndisso, permanece a indicação de hidratação venosa."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183098","number":"183098","sourceNumber":"183098","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"São causas de constipação intestinal na criança, EXCETO:","options":{"A":"Desidratação.","B":"Uso de drogas antidepressivas.","C":"Abscesso / Fissura anal.","D":"Doença Celíaca."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183118","number":"183118","sourceNumber":"183118","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à Coqueluche:","options":{"A":"O homem é o único hospedeiro conhecido da Bordetella pertussis.","B":"A transmissão se dá pelo contato direto do doente, por isso a importância do isolamento de\ncontato.","C":"A coqueluche é uma doença causada predominantemente pela B. pertussis, mas uma doença\nsemelhante está associada à infecção por B. parapertussis, B. bronchiseptica e adenovírus.","D":"A doença sintomática dura de 6 a 8 semanas e geralmente é dividida em estágios: catarral,\nparoxístico e convalescente."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183644","number":"183644","sourceNumber":"183644","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina de 5 anos apresenta rinossinusite bacteriana recorrente. Não apresenta refluxo\ngastroesofágico, imunodeficiência, imotilidade ciliar ou fibrose cística. O otorrinolaringologista\nrealizou endoscopia nasal e verificou adenoidite. Sugeriu a realização de adenoidectomia. Qual\nseria a melhor conduta do pediatra?","options":{"A":"Discordar da indicação cirúrgica, pois adenoides fazemparte do sistema imunológico.","B":"Concordar com a cirurgia, pois há evidências de que muitas crianças com\nrinossinusitebacateriana recorrente ou crônica\napresentam bactérias sob forma de biofilme nas\nadenoides e só melhoram após adenoidectomia.","C":"Afirmar para a mãe que a única indicação de adenoidectomia é a hipertrofia, que acarreta\nobstrução nasal permanente e/ou apneia obstrutiva do sono.","D":"Dizer que não existem evidências que correlacionem à melhora da rinossinusite crônica com a\nadenoidectomia."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183088","number":"183088","sourceNumber":"183088","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"São causas de obstrução de vias aéreas em pediatria, em crianças acima de 2 anos,\ntodas apresentadas nas alternativas abaixo, EXCETO:","options":{"A":"Epiglotite.","B":"Corpos estranhos.","C":"Mononucleose.","D":"Ascaridíase."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-180143","number":"180143","sourceNumber":"180143","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa verdadeira:","options":{"A":"O sinal mais confiável para o diagnostico de Otite\n\nMedia Aguda (OMA) é o abaulamento de membrana timpânica","B":"A hiperemia de membrana timpânica é sinal confiável de OMA","C":"Otorreia purulenta é sinal patognomônico de OMA","D":"Recomenda-se dose única de Ceftriaxona na OMA","E":"OMA é sinônimo de antibioticoterapia"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183092","number":"183092","sourceNumber":"183092","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Das complicações citadas abaixo, qual não está relacionada com a Fibrose Cística?","options":{"A":"Atelectasias.","B":"Apendicite.","C":"Refluxo gastroesofágico.","D":"Crises convulsivas."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183097","number":"183097","sourceNumber":"183097","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"São indicações para realização do teste de sódio e cloro no suor, para diagnóstico de\nFibrose Cística, EXCETO:","options":{"A":"Cetoacidose diabética.","B":"Tosse crônica ou recorrente.","C":"Bronquiolite recorrente.","D":"Pancreatite."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183111","number":"183111","sourceNumber":"183111","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à perda de folego pálida do lactente.","options":{"A":"Caracteriza-se por um período de choro prolongado, complicado por hipoventilação e cianose\nprogressiva.","B":"Caracteriza-se por lactente ou pré-escolar que sofre contrariedade ou dano menor,\napresentando um ou dois choros curtos, palidez e perda de consciência.","C":"Gera risco aumentado de parada cardiorrespiratória, convulsões e retardo no desenvolvimento\nneurológico.","D":"É uma das apresentações da síncopereflexa ou situacional, e a sua recuperação tende a ser\nmais demorada (em torno de 10 a 15 minutos)."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183028","number":"183028","sourceNumber":"183028","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Marque a opção CORRETA em relação ao uso de epinefrina no tratamento de crupe\nviral.","options":{"A":"O efeito é rápido nos sintomas do crupe, que diminui o estridor e os sintomas de falência\nrespiratória.","B":"O paciente pode voltar ao estado de desconforto respiratório após o final do efeito do fármaco,\nque dura, em média, 5 horas.","C":"O mecanismo de ação ocorre por meio do estímulo de receptores beta adrenérgicos.","D":"É indicada nos casos de crupe leve e moderado e em casos de crianças em procedimentos de\nVAS."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183031","number":"183031","sourceNumber":"183031","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Aponte a afirmativa CORRETA em relação à traqueíte bacteriana.","options":{"A":"O uso de corticosteroides está indicado somente nos casos graves.","B":"O paciente deve ter a via aérea asseguradae ser admitido em UTI.","C":"O tratamento inicial deve ser com epinefrina inalatória ou intramuscular.","D":"É a causa mais comum de obstrução aguda das VAS em crianças."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183034","number":"183034","sourceNumber":"183034","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A etiologia das infecções retrofaríngeas está associada a causas clínicas, traumáticas e\nidiopáticas. São fatores predisponentes dessas infecções, EXCETO","options":{"A":"otite média.","B":"infecção dentária.","C":"corpo estranho perfurante.","D":"pneumonia com derrame."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-183593","number":"183593","sourceNumber":"183593","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação à obstrução das vias aéreas superiores (VAS), assinale a alternativa\nINCORRETA.","options":{"A":"Algumas partes das VAS podem sofrer colapso com maior facilidade do que outras, motivo pelo\nqual, há diferentes apresentações clínicas das doenças dessas vias.","B":"Estridor a partir de obstrução supraglótica geralmente produz um som ouvido, sobretudo,\ndurante a inspiração.","C":"A crupe viral inicia-se com tosse leve, rinorreia clara, febre baixa e faringite.","D":"A crupe viral geralmente acomete crianças de 4 a 8 anos, com pico de incidência em torno de 6\nanos. Ocorre principalmente no outono e no inverno, sendo extremamente rara em outras épocas\ndo ano"},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-187814","number":"187814","sourceNumber":"187814","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual dentre os achados clínicos NÃO é encontrado nos casos de diarreia aguda que se\nprolonga por intolerância à lactose?","options":{"A":"Assadura na região perianal","B":"Distensão abdominal","C":"Fezes explosivas","D":"Sangue nas fezes"},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-187825","number":"187825","sourceNumber":"187825","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente, sexo masculino, 10 meses de idade, previamente saudável, está há 2 dias\ncom diarreia líquida, sem sangue. Vômitos esporádicos. Febre somente no primeiro dia e diurese\ndiminuída. Ao exame, peso: 8kg, mucosas um pouco ressecadas, turgor e elasticidade da pele\nnormais, fluxo de extremidades de 4 segundos, pulsos cheios, FC: 135bpm. Em relação ao\ntratamento desta criança, assinale a alternativa CORRETA:","options":{"A":"Indicado soroterapia venosa, com solução fisiológica 0,9%.","B":"Iniciar terapia de reidratação oral (TRO).","C":"Iniciar com azitromicina via oral por 5 dias.","D":"Para combater os vômitos está indicado metoclopramida."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-187853","number":"187853","sourceNumber":"187853","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual das alterações na radiografia de tórax sugere etiologia bacteriana para\npneumonia?","options":{"A":"Atelectasia lobar, envolvendo o lobo médio","B":"Espessamento de paredes brônquicas","C":"Infiltrado lobular, bem definido","D":"Infiltrado perihilar"},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-187858","number":"187858","sourceNumber":"187858","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual alternativa está ERRADA em relação à pneumonia por Mycoplasma pneumoniae?","options":{"A":"É causa infecciosa frequente da síndrome torácica aguda em pacientes com anemia falciforme","B":"É comum a infecção entre irmãos que moram juntos","C":"Em adolescentes é a etiologia mais frequente de pneumonia","D":"Os achados radiográficos são inespecíficos, sendo os lobos inferiores os mais comumente\nenvolvidos"},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-182820","number":"182820","sourceNumber":"182820","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A doença de Hirschsprung ocorre em um a cada 5.000 nascidos vivos. É INCORRETO\nafirmar que","options":{"A":"está associada a espasmo muscular do cólon distal e esfincter anal interno, resultando em\nobstrução funcional.","B":"a aglangliose se incia na transição anoretal.","C":"o retossigmoide é afetado em aproximadamente 80% dos casos.","D":"o enema contrastado é o padrão ouro para o diagnóstico."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-181347","number":"181347","sourceNumber":"181347","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Emanuelle, 23 meses de vida, começou a apresentar febre intermitente (39°C), tosse\nseca e inapetência, há cerca de 5 dias.\nSua genitora relatava situação vacinal atualizada e negava\ncontactantes com quadro semelhante. Avaliada em serviço de emergência, notou-se a presença de\nestertores finos em hemitórax direito, frequência respiratória de 60 ipm, sem tiragens, e\nradiografia\nde tórax com hipotransparência em base pulmonar direita. Negou história pregressa de quadro de\ncansaço ou uso de medicamentos domiciliares, sendo descrita como ?saudável? até o\ndesencadeamento do quadro atual. Qual o diagnóstico mais provável e a melhor conduta a ser\ntomada?","options":{"A":"Pneumonia comunitária, devendo iniciar amoxicilina(50mg/kg/dia) e reavaliação clínica em 48\nhoras.","B":"Pneumonia grave, devendo ser realizado internamento e uso de antibioticoterapia com\noxacilina(200mg/kg/dia).","C":"Pneumonia comunitária, devendo iniciar amoxicilina + clavulonato (50mg/kg/dia), com\nreavaliação após 07 dias do início do tratamento.","D":"Pneumonia grave, devendo ser realizado internamento e uso de antibioticoterapia endovenosa\ncom penicilina cristalina (400mg/kg/dia).","E":"Pneumonia muito grave, devendo ser realizado internamento e uso de antibioticoterapia com\nceftriaxon (100mg/kg/dia) associado à oxacilina (200mg/kg/dia)."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-152635","number":"152635","sourceNumber":"152635","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente com quadro de desconforto respiratório de inicio há 12 horas, irritado e\nchoroso, FC:120 bpm e FR:55 IRM , diminuição de\nmurmúrio vesicular e raros sibilos em hemitórax\ndireito. Rx tórax com hipertransparência direita e sem condensação ou atelectasia. Qual hipótese\nmais provável?","options":{"A":"Pneumonia.","B":"Corpo estranho.","C":"Pneumotórax.","D":"Asma.","E":"Bronquiolite."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-152641","number":"152641","sourceNumber":"152641","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Defina a alternativa correta relacionada à pneumonia.","options":{"A":"A imagem radiológica é diagnostica na diferenciação da pneumonia bacteriana e viral.","B":"A Meningite e a Artrite Supurativa são complicações\nfrequentes.","C":"A taquipneia é o sinal clínico mais consistente na Pneumonia.","D":"A contagem de leucócitos periféricos não é útil na\ndiferenciação de bacteriana e viral.","E":"A história clínica e os sintomas como tiragem e batimento de asa do nariz, não são fatores de\ngravidade."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161181","number":"161181","sourceNumber":"161181","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre o diagnóstico e tratamento do derrame pleural parapneumônico complicado na\ncriança, assinale a alternativa CORRETA.","options":{"A":"O tratamento cirúrgico é padrão ouro para o derrame pleural parapneumônico, complicado em\ncrianças.","B":"Para firmar diagnóstico, é necessário somente exame físico e anamnese.","C":"Há indicação de avaliação ecográfica em todas as crianças após diagnóstico.","D":"O tipo de drenagem cirúrgica no manejo do derrame pleural parapneumônico complicado é\núnico, independente do estágio em que se encontra."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161263","number":"161263","sourceNumber":"161263","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em termos de prevenção da Síndrome Hemolítico-Urêmica típico associado a E. coli\nentero-hemorrágica, é INCORRETO afirmar que:","options":{"A":"O manuseio adequado da carne e do preparo dos alimentos, incluindo cozinhar em altas\ntemperaturas, pode reduzir o risco de infecção por E. Coli entero-hemorrágica.","B":"O leite deve ser pasteurizado.","C":"Os casos índices não necessitam ser identificados para prevenir exposição de outros indivíduos.","D":"Devido à correlação com natação em água contaminada, devem existir regras de\nregulamentação para a segurança em piscinas."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158769","number":"158769","sourceNumber":"158769","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paulo, dois anos de vida, começou inicialmente com quadro de coriza, febre baixa e\ntosse leve. Após cerca de 48 horas, evoluiu com tosse ladrante, rouquidão, estridor inspiratório e\ntaquidispneia. Qual a hipótese diagnóstica mais provável e o agente etiológico?","options":{"A":"Epiglotite, causada mais comumente pelo vírus\nParainfluenza I.","B":"Epiglotite, causada mais comumente pelo Haemophilus\ninfluenzae tipo b.","C":"Laringotraqueíte viral aguda, causada mais comumente pelo\nvírus Parainfluenza I.","D":"Laringotraqueíte viral aguda, causada mais comumente pelo\nStreptococcus pneumoniae.","E":"Laringotraqueíte viral aguda, causada mais comumente pelo\nHaemophilus influenzae tipo b."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158778","number":"158778","sourceNumber":"158778","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Patrícia, três anos de idade, começou há seis dias a apresentar febre diária (39 graus),\nseguida de tosse produtiva, taquipneia e inapetência. Levada ao pronto-atendimento, foi realizada\nradiografia de tórax, que evidenciou imagem hipotransparente em base direita, sem desvio do\nmediastino. O médico assistente optou por iniciar esquema terapêutico ambulatorial com\namoxicilina. A conduta, nesse caso, foi:","options":{"A":"Inadequada, por se tratar de pneumonia muito grave, devendo receber suporte em terapia\nintensiva e já iniciar vancomicina.","B":"Adequada, por se tratar de pneumonia adquirida na\ncomunidade e o agente mais comum ser sensível à\namoxicilina.","C":"Inadequada, por se tratar de pneumonia muito grave, devendo ser internada e iniciar esquema\nde antibioticoterapia com\n\noxacilina e amicacina.","D":"Inadequada, por se tratar de pneumonia grave, devendo ser internada e iniciar esquema de\nantibioticoterapia com\n\nampicilina e gentamicina.","E":"Adequada, por se tratar de pneumonia adquirida na\n\ncomunidade; porém, devido à elevada taxa de S. pneumoniae resistente, já deveria usar\ninicialmente amocixilina associada\n\na clavulonato."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161305","number":"161305","sourceNumber":"161305","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 12 anos com diagnóstico de fibrose cística, traqueostomizado, com uso de\noxigênio domiciliar, evolui nas últimas 24 horas com desconforto respiratório progressivo. Ao exame\nclínico, apresenta creptação em bases de ambos hemitórax e o exame radiológico demonstra\ncondensação em base de hemitórax esquerdo. A saturação de oxigênio está em 89%. Assinale a\nalternativa que apresenta a conduta ADEQUADA, frente a esse quadro clínico.","options":{"A":"Instalar ventilação mecânica invasiva com parâmetros ventilatórios fisiológicos e introduzir\nantibióticos.","B":"Instalar ventilação mecânica não invasiva em capacete com parâmetros ventilatórios fisiológicos\ne introduzir antibióticos.","C":"Instalar ventilação mecânica não invasiva em máscara facial com parâmetros ventilatórios\nfisiológicos e introduzir antibióticos.","D":"Manter aporte de oxigênio, introduzir antibióticos e observar evolução."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158770","number":"158770","sourceNumber":"158770","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Dadas as afirmativas quanto à classificação da gravidade clínica de pneumonias em\ncrianças de 2 meses a 5 anos, segundo a Organização Mundial de Saúde (2005), I. A presença de\ncianose central a classifica como pneumonia muito grave.; II. A presença de tiragem subcostal a\nclassifica como pneumonia grave.; III. A presença de estertores pulmonares à ausculta pulmonar a\nclassifica como pneumonia.; IV. A presença de frequência respiratória maior ou igual a 40 incursões\npor minuto em crianças de 1 a 4 anos a classifica como pneumonia.; Verifica-se que está(ão)\ncorreta(s):","options":{"A":"I, apenas.","B":"IV, apenas.","C":"II e III, apenas.","D":"I, II e III, apenas.","E":"I, II, III e IV."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161346","number":"161346","sourceNumber":"161346","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 4 meses chora eventualmente, vomita e se engasga frequentemente\nquando mama, sem que isso prejudique seu estado\ngeral. Cada vez que engasga segue mamando\nnormalmente. Nasceu com 3.200 g e está pesando 6.980 g; apresenta exame físico normal. Sobre\nesse paciente, assinale a alternativa CORRETA:","options":{"A":"Deve ser observado e considerado portador de refluxo fisiológico até que apareça algum sinal de\nalerta.","B":"Deve realizar uma pHmetria, pois esse é o exame mais indicado para avaliação do lactente com\nregurgitações e vômitos, pois não necessita de sedação para sua realização.","C":"Deve realizar uma endoscopia com biópsias de esôfago, pois as alterações histológicas da\nesofagite de refluxo têm alta sensibilidade e especificidade para diagnóstico de doença do refluxo\ngastroesofágico.","D":"Deve ser submetido a um teste empírico terapêutico com inibidor da bomba de prótons para\nmelhorar seus sintomas."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161362","number":"161362","sourceNumber":"161362","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Os agentes etiológicos mais prevalentes na otite média aguda recorrente são os\nseguintes, EXCETO um deles. Aponte-o.","options":{"A":"Streptococcus pneumoniae.","B":"Haemaphilus influenzae.","C":"Moraxella catarrhalis.","D":"Stafilococcus epidermitidis."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161372","number":"161372","sourceNumber":"161372","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto aos exames diagnósticos realizados em\numa criança de 16 meses de idade com Otite Média\nAguda (OMA):","options":{"A":"Na audiometria tonal, se os limiares auditivos não estiverem iguais ou inferiores a 15 dB, houve\numa perda auditiva nas duas orelhas.","B":"A imitanciometria avalia a orelha média, que, para cumprir sua função de amplificar o som,\nprecisa estar cheia de ar, cuja pressão deve ser igual à do meio ambiente.","C":"No exame de imitanciometria normal, o pico da curva terá pressão ao redor de 0 da PA (curva\ntipo A), mas, quando a curva é plana e sem\npico (curva tipo B), pode indicar efusão na orelha\nmédia ou perfuração da membrana timpânica.","D":"Na endoscopia nasal, o achado de adenoides pequenas, ocupando menos do que 40% da luz\ndo cavum, indica otite média externa."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158821","number":"158821","sourceNumber":"158821","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Hugo, oito meses de vida, foi internado na UTI pediátrica devido a quadro de\npneumonia muito grave, Sato 2: 89% em ar\nambiente e respiração irregular. Realizada radiografia\nde tórax foi evidenciado infiltrado intersticial grosseiro em base de hemitórax esquerdo, com\nopacificação de seios costofrênico e cardiofrênico à esquerda, de modo que foi iniciada\nantibioticoterapia com ampicilina. Cerca de quatro dias após o início do tratamento, Hugo começou\na ter febre (39 graus), piora do padrão respiratório, queda do estado geral, além da diminuição do\nmúrmurio vesicular à esquerda. Foi realizada nova radiografia de tórax, com hipotransparência de\ndois terços do hemitórax esquerdo, com desvio do mediastino para a direita. Qual a melhor conduta\nnesse caso?","options":{"A":"Associar gentamicina ao esquema terapêutico e repetir radiografia de tórax com 72 horas.","B":"Realizar drenagem pleural, sendo pH<7,2 ou glicose < 40 mg/dL associar gentamicina.","C":"Realizar drenagem pleural sendo pH<7,2 ou glicose<40mg/dL ou gram/cultura positiva, iniciar\nVancomicina.","D":"Realizar drenagem pleural, se pH >7,2 e glicose > 40mg/dL, iniciar Oxacilina, mesmo se\nbacterioscopia negativa.","E":"Iniciar Oxacilina e aguardar 72 horas. Caso ocorra persistência do quadro clínico e radiológico,\nrealizar drenagem pleural."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158823","number":"158823","sourceNumber":"158823","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paulo tem quatro anos e há cerca de cinco dias começou a apresentar taquipneia,\ntosse produtiva e febre. Ao exame físico, notou-se\naumento do frêmito tóraco-vocal em hemitórax\ndireito. Qual o diagnóstico mais provável e a conduta a ser tomada?","options":{"A":"Bronquiolite viral, devendo ser realizada apenas nebulização hipertônica.","B":"Bronquiolite viral, devendo ser instituída terapêutica com claritromicina e nebulização\nhipertônica.","C":"Pneumonia comunitária, devendo ser instituída antibioticoterapia com claritromicina.","D":"Pneumonia comunitária, devendo ser instituída antibioticoterapia com amoxicilina ou penicilina\nprocaína.","E":"Pneumonia comunitária, devendo ser instituída antibioticoterapia com a associação de ampicilina\ne gentamicina."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161296","number":"161296","sourceNumber":"161296","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A orientação aos pais e o suporte à família são medidas necessárias, principalmente\nnos lactentes que regurgitam, mas que crescem de\nforma adequada, em especial, nos primeiros\nmeses de vida. Preconizadas para todos os portadores de refluxo gastroesofágico e doença do\nrefluxo gastroesofágico, independente da gravidade, as mudanças nos hábitos de vida em pediatria\nincluem, EXCETO,","options":{"A":"Não usar roupas apertadas.","B":"Sugerir a troca de fraldas após as mamadas.","C":"Evitar tabagismo (ativo ou passivo), pois o tabaco induz o relaxamento do esfíncter esofágico\ninferior.","D":"Fornecer orientações dietéticas e de postura antirrefluxo."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-161299","number":"161299","sourceNumber":"161299","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No refluxo gastroesofágico em crianças, é possível AFIRMAR que a","options":{"A":"impedanciometria esofágica intraluminal pode ser útil para detectar episódios de refluxo não\nácido.","B":"presença de refluxo ao exame radiológico contrastado é indicação de tratamento\nmedicamentoso.","C":"ultrassonagrafia abdominal é o exame mais indicado na investigação em crianças por ser menos\ninvasivo.","D":"pHmetria de esôfago é o exame de escolha na investigação de esofagite."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-134047","number":"134047","sourceNumber":"134047","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No calendário de vacinação do Ministério da Saúde do Brasil, aos 12 meses de idade, a\ncriança deve receber a vacina tríplice viral, vacina de vírus vivos atenuados: Sarampo, Caxumba e\nRubéola. Quanto à Caxumba, o objetivo PRINCIPAL é proteger contra","options":{"A":"Artrite.","B":"Meningite.","C":"Surdez.","D":"Ooforite."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-134806","number":"134806","sourceNumber":"134806","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino de 8 anos, que não recebeu imunizações prévias, sofre uma ferida puntiforme\nno pé por material enferrujado. Qual dos\nseguintes esquemas você deve administrar à criança para\nprofilaxia pós-exposição contra tétano?","options":{"A":"Vacina DTaP.","B":"Vacina dT.","C":"Vacina DTaP e Ig tetânica.","D":"Vacina dT e Ig tetânica."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-134881","number":"134881","sourceNumber":"134881","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Garoto 15 anos é mordido na panturrilha por um cão de sua propriedade sadio e\ndomiciliado, quando tentava segurar o animal para receber a 2ª dose de vacina antirrábica. O\nferimento único assustou o garoto que foi levado imediatamente pela sua mãe à UBS para receber\nvacina contra raiva. Qual das condutas abaixo está dentro da Norma de profilaxia da raiva humana\ndo Instituto Pasteur- SP, sabendo que o garoto nunca foi vacinado contra raiva?","options":{"A":"Observar o animal por 10 dias, aplicar o soro e iniciar o esquema de 5 doses, suspendendo o\nesquema se o animal permanecer sadio durante a observação.","B":"Aplicar 3 doses de vacina IM nos dias (0,3,7) e uma dose de soro (40UI\\kg\\peso), sendo\naplicado no local do ferimento.","C":"Observar o animal por 10 dias e, caso o cão permaneça sadio, encerrar o caso.","D":"Não há necessidade do soro antirrábico, embora o ferimento seja considerado grave, apenas\naplicar 5 doses de vacina nos dias (0, 3, 7, 14, 28), sendo dia zero, o dia em que foi aplicado a 1ª\ndose e não o dia do acidente."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-134885","number":"134885","sourceNumber":"134885","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em 13/09/2015, João Pedro, 10 anos chega à UBS Eldorado, município de Serra\nNegra, com sua mãe D. Maria dos Prazeres para\numa consulta médica. Dr. Paulo, clínico geral,\ndurante o atendimento indagou sobre a situação vacinal do garoto. A mãe informou que havia\nperdido a carteira de vacinação durante uma enchente, mas que ele estava com todas as vacinas\nem dia. O médico, então, pede a Joana, auxiliar de enfermagem da sala de vacinas, que procure a\nficha registro de João Pedro, porém, ela não encontra. Qual deverá ser a conduta tomada pelo Dr.\nPaulo em relação às vacinas do garoto?","options":{"A":"Solicitar o encerramento do caso, uma vez que a mãe afirmou que ele já havia tomado todas as\nvacinas.","B":"Reiniciar o calendário vacinal, aplicando as vacinas BCG, Hepatite B, Sabin, Tetravalente,\nTríplice Viral e Febre Amarela.","C":"Verificar a cicatriz da vacina BCG, se não a tiver, vacinar e indicar o seguinte esquema: uma\ndose de Dupla Adulto, dose única de Febre\nAmarela, dose única de Tríplice Viral e esquema da\nvacina contra Hepatite B.","D":"Verificar cicatriz do BCG se tiver presença de cicatriz não vacinar e indicar esquema para as\nvacinas: Duplas Adulto ou DTpa, Febre Amarela, Tríplice Viral, Hepatite B e Sabin."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-134327","number":"134327","sourceNumber":"134327","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Médica com 24 anos de idade, recém-formada em escola do Sudeste brasileiro, foi\nconvocada pelo Exército para servir, durante o próximo ano, na base de Cruzeiro do Sul, cidade do\nAcre, na Região Norte do país. Ela comparece à Unidade Básica de Saúde para se vacinar contra\nfebre amarela. Como o médico deve orientar a paciente?","options":{"A":"Como a viagem irá durar mais de seis meses, não está indicada a vacinação contra febre\namarela, somente a adoção de medidas\n\npreventivas contra picadas de insetos, principalmente durante a noite.","B":"Não existe indicação de vacinação, e sim de quimioprofilaxia para malária, com doxiciclina,\nmefloquina e cloroquina. Iniciar um dia antes da viagem e manter até quatro semanas após o\nretorno.","C":"Indicar a vacinação contra febre amarela pelo menos dez dias antes da viagem. Não é\nnecessário tomar a vacina se já foi vacinada nos últimos dez anos. Orientar sobre a importância\nde portar cartão de vacinação durante a viagem.","D":"Como viverá em área endêmica, deverá receber reforço vacinal a cada cinco anos. Orientar\nsobre a importância de portar cartão\n\nde vacinação durante a viagem."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-109752","number":"109752","sourceNumber":"109752","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 10 meses de vida é levado ao Posto de Saúde devido a quadro de infecção\nde vias aéreas superiores. A avaliação da\ncarteira vacinal revela que, à exceção da BCG e da\nvacina anti-Hepatite B, nenhuma outra vacina foi administrada. Em relação às imunizações, de\nacordo com as recomendações atuais do Ministério da Saúde, a conduta é:","options":{"A":"não aplicar nenhuma vacina, pois a criança já está adoentada.","B":"aplicar as vacinas anti-Hepatite B, anti-Hemófilos B, Tríplice bacteriana e vacina oral\nanti-Poliomelite.","C":"aplicar as vacinas anti-Hepatite B, anti-Hemófilos B, Tríplice-bacteriana, vacina oral\nanti-Poliomelite e anti-Sarampo.","D":"aplicar as vacinas anti-Hepatite B, anti-Hemófilos B, Tríplice bacteriana, vacina oral\nanti-Poliomelite e Tríplice viral."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-109784","number":"109784","sourceNumber":"109784","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança recebeu BCG com 7 dias de vida. Com 6 meses não apresentava cicatriz\nno braço direito e foi revacinada, estando a\nvacina em condições ideais para uso. Novamente não\nse formou cicatriz. Sua conduta é, portanto,","options":{"A":"revacinar com BCG intradérmico.","B":"revacinar com BCG intradérmico após PPD.","C":"revacinar com BCG intradérmico após PPD e RX de tórax.","D":"considerar a criança como imunizada."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-110026","number":"110026","sourceNumber":"110026","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a prevenção de doenças respiratórias em idosos, aponte a alternativa\nCORRETA.","options":{"A":"A vacina contra Influenza é válida por cinco anos, não devendo ser repetida antes desse\nperíodo.","B":"Pacientes com mais de 65 anos devem receber pelo menos uma dose de vacina pneumocócica\ndurante sua vida.","C":"É absolutamente contraindicada mais de uma dose de vacina Pneumocócica, pois esse\nprocedimento pode provocar reações adversas.","D":"A vacina Pneumocócica deve ser repetida anualmente no outono."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-109813","number":"109813","sourceNumber":"109813","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a difteria, é CORRETO afirmar que:","options":{"A":"A imunização ativa pode dar-se através de infecções inaparentes, e depende da maior ou menor\nexposição dos indivíduos.","B":"O toxoide diftérico não é mais utilizado correntemente.","C":"A doença confere imunidade duradoura.","D":"Com os novos antimicrobianos, o uso do soro antidiftérico tornou-se desnecessário."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-110042","number":"110042","sourceNumber":"110042","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mulher com 25 anos de idade engravida e, durante a realização do pré-natal, descobre\nser portadora do antígeno HBs. As medidas\napropriadas para evitar a aquisição da doença pelo\nrecém-nascido são:","options":{"A":"vacina e imunoglobulina humana intravenosa ao nascimento.","B":"imunoglobulina hiperimune intramuscular ao nascimento e vacina com 1 mês de vida.","C":"vacina ao nascimento e imunoglobulina hiperimune intramuscular a cada mês, a partir de 10 dias\nde vida, por 2 meses.","D":"vacina e imunoglobulina hiperimune intramuscular ao nascimento."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158404","number":"158404","sourceNumber":"158404","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A primeira manifestação que pode estar presente na fibrose cística é:","options":{"A":"Desidratação com hipocloremia e hiponatremia com acidose metabólica.","B":"Colestase neonatal.","C":"Cirrose biliar focal.","D":"Desidratação com hipocloremia e hiponatremia com alcalose metabólica.","E":"Íleo meconial."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158409","number":"158409","sourceNumber":"158409","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Com relação a constipação intestinal podemos dizer:","options":{"A":"O óleo mineral pode ser dado na dosagem de 1 a 3 ml/kg/dose.","B":"Óleo mineral não pode ser dado para menores de 3 anos, neuropatas.","C":"O controle esfincteriano se inicia aos 2 anos de idade.","D":"São complicações da constipação intestinal: enurese, anorexia, IVAS de repetição.","E":"Nenhuma acima."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-158435","number":"158435","sourceNumber":"158435","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A causa mais comum de pneumonias de repetição na infância é:","options":{"A":"Asma.","B":"Tuberculose.","C":"Refluxo gastroesôfágico.","D":"Imunodeficiência.","E":"Cardiopatia congênita."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-108608","number":"108608","sourceNumber":"108608","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 1 ano e 4 meses é levado à UBS onde você realiza o internado de medicina\npreventiva, por conta de quadro gripal. Alimentação da criança variada, vacinas realizadas até 1\nano de idade. Ao exame, menor eupneica; hidratada; anictérica; acianótica; afebril; boa interação\ncom o meio; desenvolvimento neuropsicomotor adequado para idade; AP: MV presente\nbilateralmente com roncos de transmissão; AC: BCNF RCR 2T S/Sopro; abdome flácido sem\nmegas ou massas; extremidades sem alterações. Qual das alternativas abaixo é contraindicação\npara realização de vacinas?","options":{"A":"Quadro gripal.","B":"Diarreia.","C":"Uso crônico de corticoide inalatório.","D":"Pneumonia em tratamento.","E":"Eczemas em áreas extensoras."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-108609","number":"108609","sourceNumber":"108609","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 1 ano e 4 meses, vai à UBS onde você realiza o internado de medicina\npreventiva, por conta de quadro gripal.\nAlimentação da criança variada, Vacinas realizadas até 1\nano de idade. Ao exame, menor eupneica, hidratada, anictérica, acianótica, afebril, boa interação\ncom o meio, desenvolvimento neuropsicomotor adequado para idade, AP: MV presente\nbilateralmente com roncos de transmissão, AC: BCNF RCR 2T S/Sopro, Abdome flácido sem\nmegas ou massas, extremidades sem alterações. Quais vacinas deveriam ser administradas na\ncriança em questão?","options":{"A":"Tríplice viral, VOP, DTP.","B":"Tríplice viral, VOP, DTPa.","C":"Tetra viral, VOP, DTP.","D":"Tetra viral, VOP, Tetra bacteriana.","E":"Tetra viral, VIP, DTP."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-362431","number":"362431","sourceNumber":"362431","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de quatro meses de vida é trazida pela mãe À UBS por apresentar estridor\npersistente há 2 meses. Segundo a mãe, a\ncriança melhora quando colocada em posição pronada.\nO diagnóstico mais provável seria:","options":{"A":"Laringocele.","B":"Laringomalácea.","C":"Estenose Subglótica.","D":"Paresia De Prega Vocal."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-362464","number":"362464","sourceNumber":"362464","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Adolescente de 13 anos, é levado a consulta por apresentar febre alta há 10 dias. Ao\nexame físico: Dor de garganta com faringite\nmoderada, petéquias palatais, edema de palpebral,\nadenomegalia cervical anterior e posterior, epitrocleares e hepatoesplenomegalia. Qual o exame\npara confirmação diagnostica a ser solicitado:","options":{"A":"Aspirado de medula.","B":"Sorologia para dengue.","C":"Cultura de secreção faríngea.","D":"Sorologia para Vírus Epstein Barr (EBV)."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-362462","number":"362462","sourceNumber":"362462","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 15 messes, portador de doença multissistêmica hereditária, um traço\ngenético recessivo, comum entre a população\nbranca. frequentemente chega ao setor de\nemergência com tosse crônica e respiração sibilante desde o primeiro mês de vida. Foi internado a\nprimeira vez aos 4 meses de vida com bronquiolite viral aguda grave por 7 dias, necessitando de\nventilação mecânica pulmonar invasiva. Precisou de internação por desidratação grave com\nhiponatremia por duas vezes. Nasceu com APGAR 9/10 e alta com a mãe no terceiro dia de vida.\nConsiderando o acima descrito a hipótese diagnostica mais provável é:","options":{"A":"Asma grave.","B":"Fibrose cística.","C":"Síndrome dos cílios imóveis.","D":"Doença do refluxo gastroesofágico."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-327284","number":"327284","sourceNumber":"327284","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pedro, 6 anos de idade, que desde os 8 meses de idade, apresenta episódios de\nsibilância recorrente. No início da noite fez uso\nde beclometasona inalatória em dose baixa, com\nauxílio de espaçador. Com piora do quadro, procurou o serviço de Emergência Pediátrica. Mãe\nrelata que em todos os episódios anteriores foi necessário o uso de corticoide (PREDNISOLONA)\nvia oral, para resolução do quadro. Podemos considerar características, para prever, se a sibilância\nrecorrente na criança, irá persistir na vida adulta. Assinale a alternativa CORRETA.","options":{"A":"Diagnostico de alergia ao leite de vaca.","B":"Primos de primeiro grau com diagnóstico de asma.","C":"Basofilia sanguínea maior de 3% (na ausência de parasitose).","D":"Diagnostico de eczema em menores de 3 anos e diagnostico de rinite em menores de 3 anos."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-327289","number":"327289","sourceNumber":"327289","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Clara, 8 meses, começou a frequentar a creche no 6° mês de vida, ao termino da\nLicença Maternidade de sua mãe. Há 7 dias, iniciou\num quadro de coriza que inicialmente era\nhialina, evoluindo no 3° dia para esverdeada, tosse, irritabilidade, febre que durou cerca de 3\ndias e\nposteriormente cedeu, persiste ainda tosse, coriza e inapetência. Ao exame, apresenta membrana\ntimpânica direita abaulada e intensa hiperemia. Sem outras alterações. Qual seria a melhor\nconduta:","options":{"A":"Prescrever SULFAMETOXAZOL + TRIMETOPRINA pela facilidade da posologia.","B":"Prescrever PENICILINA BENZATINA devido à melhor aderência ao tratamento.","C":"Encaminhar ao Pronto Socorro para realizar raio x de seios da face.","D":"Prescrever AMOXACILINA imediatamente devido à baixa idade."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-327290","number":"327290","sourceNumber":"327290","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 1 ano, pesando 12 Kg, foi internado com quadro de diarreia e vômito com\n48 horas de evolução. Ao exame, sinais\nclínicos de desidratação grave. Administrado na admissão,\nSoro Fisiológico 20 ml/Kg em 30 minutos. Essa opção terapêutica com Soro Fisiológico é?","options":{"A":"Cloro/por litro da solução em valores próximos ao do plasma.","B":"Osmolaridade/por litro da solução tem valores próximos a do plasma.","C":"Eletrólitos/por litro da solução em valores próximos ao do plasma.","D":"Potássio/por litro da solução em valores próximos ao do plasma."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-327295","number":"327295","sourceNumber":"327295","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 2 anos é levada a um Pronto Socorro por apresentar rouquidão e estridor\nde início súbito, após refeição de\naproximadamente três horas. Ao exame físico: Bom estado geral,\nestridor respiratório, choro rouco, ausência de esforço respiratório e ausculta sibilos. Qual melhor\nconduta?","options":{"A":"Tomografia computadorizada","B":"Ressonância magnética","C":"Endoscopia digestiva","D":"Laringoscopia direta"},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298227","number":"298227","sourceNumber":"298227","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente do sexo feminino, 4 anos, deu entrada no pronto atendimento com quadro de\ntosse produtiva e febre há 3 dias, com piora progressiva do estado geral. A mãe nega\ncomorbidades, internações hospitalares e uso prévio de antibióticos. Estava discretamente\ndispneica e febril, saturando 97% com oxigenação sob cateter nasal. Apresentava crepitação e\nmurmúrio vesicular diminuído em base do hemitórax esquerdo à ausculta torácica. Leucograma:\n\n14.000. A radiografia de tórax evidenciou condensação em terços médio e inferior do pulmão\nesquerdo, associado a derrame pleural que ocupava\ncerca de 1/4 do volume do hemitórax e corria\n1cm na incidência de Laurel. Sobre o caso acima, assinale a alternativa INCORRETA:","options":{"A":"A tomografia de tórax não está indicada neste momento na avaliação da conduta frente ao\nderrame pleural descrito.","B":"A ultrassonografia poderia distinguir o derrame do tipo exsudato do empiema pleural.","C":"A crescente insuficiência respiratória da paciente associada ao derrame pleural descrito indica\ndrenagem fechada de tórax imediata para a paciente.","D":"A toracocentese é opção para análise macroscópica e bioquímica do líquido pleural, porém ela\npode ser dispensável neste momento."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298252","number":"298252","sourceNumber":"298252","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Você é médico da UBS e chega um menino de 13 anos com febre de 38-39ºC há 2 dias\ne dor na garganta. Ao exame, você verifica a presença de exantema maculopapular em tronco,\nadenomegalia cervical e esplenomegalia. Qual é a suspeita diagnóstica inicial?","options":{"A":"Faringoamigdalite bacteriana","B":"Escarlatina","C":"Mononucleose infecciosa","D":"Rubéola"},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298253","number":"298253","sourceNumber":"298253","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"T.R.S. de 3 anos iniciou história há 3 semanas de quadro gripal, com febre e muito\nsecreção nasal. Foi à pediatra que avaliou e\nfez diagnóstico de sinusite e otite, prescrevendo\namoxicilina com clavulanato por 10 dias. No segundo dia, paciente iniciou quadro diarreico intenso\ne mãe optou por suspender antibiótico e trocou por conta própria para sulfametoxazol-trimetoprim,\npois a vizinha disse que esse remédio era bom para diarreia. Fez uso por 5 dias. Após 10 dias do\nfim do antibiótico, mãe percebe edema e eritema palpebral à direita. Enxerga bem, movimenta sem\nproblemas o globo ocular e não tem proptose. A impressão diagnóstica é de:","options":{"A":"Dermatite alérgica","B":"Celulite pré-septal","C":"Glomerulonefrite difusa aguda","D":"Abscesso orbitário"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298265","number":"298265","sourceNumber":"298265","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino de 3 anos de idade está internado em enfermaria para tratamento de\npneumonia. Na radiografia de tórax de entrada\nhá imagem compatível com pneumonia lobar em\nbase direita. Foi prescrita ampicilina endovenosa. Está no quarto dia de internação apresentando\nfebre e sem melhora do estado geral. No exame clínico, regular estado geral, descorado 1+/4+,\nhidratado. Frequência respiratória: 48 ipm, saturação de oxigênio em ar ambiente: 93%. Ausculta\npulmonar com estertores finos em terço médio de hemitórax direito e murmúrios vesiculares\ndiminuídos em base direita. O restante do exame clínico é normal. Qual é a conduta para o caso\nnesse momento?","options":{"A":"Trocar ampicilina por ceftriaxone.","B":"Pesquisar BK no suco gástrico.","C":"Associar claritromicina ao tratamento.","D":"Repetir radiografia de tórax."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298268","number":"298268","sourceNumber":"298268","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino de 3 anos de idade foi levado a consulta médica por queixa de tosse, coriza e\nobstrução nasal há 12 dias, sem melhora. Apresenta secreção nasal esverdeada intensa,\nprincipalmente ao acordar, que vai melhorando ao longo do dia. Queixa-se de cefaleia em região\nfrontal durante todo o período de doença. Não há alterações do exame clínico. Traz radiografia de\nseios da face realizada hoje, com nível hidro-aéreo em seios maxilares. Considerando a principal\nhipótese diagnóstica para o caso, qual das alternativas a seguir justifica a introdução de\nantibioticoterapia.","options":{"A":"Cefaleia em região frontal.","B":"Secreção nasal esverdeada intensa.","C":"Sintomas respiratórios por 12 dias.","D":"Nível hidro-aéreo na radiografia."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-286734","number":"286734","sourceNumber":"286734","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente do sexo masculino, 45 anos, diabético, tabagista, apresenta quadro de dor\ntorácica ventilatório-dependente em terços médio e\ninferior do hemitórax direito, associado a tosse\nprodutiva e febre alta diária, com evolução de 1 semana. Ao exame físico, o paciente se apresenta\nlevemente dispneico, taquicárdico e normotenso, com murmúrio vesicular diminuído em base do\nhemitórax direito associado a estertoração crepitante. Leucograma: 16.000 leucócitos, Proteína C\nReativa: 64mg/dl. À Radiografia de tórax, observamos condensação dos terços médio e inferior do\npulmão direito associado a derrame pleural de volume moderado. Sobre a abordagem propedêutica\ne terapêutica deste paciente, assinale a alternativa CORRETA:","options":{"A":"A Cirurgia Toracoscópica Vídeo-Assistida (VATS) é opção adequada para tratamento do\nempiema pleural nos casos de falha terapêutica com drenagem fechada de tórax.","B":"Já que a radiografia de tórax já documentou a efusão pleural, a ultrassonografia torácica não\ntraria informações extras de relevância para o caso.","C":"Caso a análise do líquido pleural coletado à toracocentese evidenciasse pH > 7.2,\ndesidrogenase lática entre 100 a 190 U/l e glicose > 22mmol/l, fechamos o diagnóstico de\nempiema, estando indicada a drenagem fechada de tórax.","D":"Os dados fornecidos acima nos permitem fechar o diagnóstico de empiema pleural na fase\norganizada, estando indicada a toracotomia urgente."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-286763","number":"286763","sourceNumber":"286763","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"José, 3 anos, deu entrada no pronto-socorro com febre há 2 dias, diarreia sem sangue\nou muco. Ao exame físico encontrava-se com\nolhos fundos, saliva espessa, choro com poucas\nlágrimas e enchimento capilar < 3 segundos. Qual a sua conduta neste momento?","options":{"A":"Plano A do Ministério da Saúde e zinco 10 mg/dia.","B":"Plano A do Ministério da Saúde e zinco 20 mg/dia.","C":"Plano B do Ministério da Saúde e zinco 10 mg/dia.","D":"Plano B do Ministério da Saúde e zinco 20 mg/dia."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-286764","number":"286764","sourceNumber":"286764","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Atualmente há preferência no uso de soro isotônico na hidratação intravenosa de\nmanutenção para crianças, lactentes e\nadolescentes internados. A justificativa para essa escolha é:","options":{"A":"Menor reincidência de desidratação","B":"Prevenção de insuficiência renal aguda","C":"Reversão rápida da acidose lática","D":"Prevenção de hiponatremia"},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-252269","number":"252269","sourceNumber":"252269","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em paciente de 3 anos de idade, previamente hígido, internado por pneumonia com\nderrame pleural, quais exames do líquido obtido de toracocentese são necessários?","options":{"A":"Citológico, pH, bacterioscópico e cultura.","B":"Citológico, bacterioscópico e cultura.","C":"pH, DHL, glicose, bacterioscópico e cultura.","D":"Citológico, glicose, proteínas, bacterioscópico e cultura."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-252278","number":"252278","sourceNumber":"252278","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 20 meses de idade, sexo feminino, é atendido com história de coriza e\nfebre 38ºC há dois dias. Tem história de\notite média aguda diagnosticada e tratada com antibióticos\nhá 8 meses evoluindo com melhora clínica. No exame físico atual, ela está afebril em bom estado\ngeral. Ambas as membranas timpânicas estão com mobilidade reduzida e levemente opacas, não\nhá hiperemia nem abaulamento. Qual é o provável diagnóstico?","options":{"A":"Otite média aguda a esquerda.","B":"Otite média com efusão bilateral.","C":"Otite média crônica supurativa bilateral.","D":"Otite média aguda recorrente."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-252279","number":"252279","sourceNumber":"252279","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 20 meses de idade, sexo feminino, é atendido com história de coriza e\nfebre 38ºC há dois dias. Tem história de\notite média aguda diagnosticada e tratada com antibióticos\nhá 8 meses evoluindo com melhora clínica. No exame físico atual, ela está afebril em bom estado\ngeral. Ambas as membranas timpânicas estão com mobilidade reduzida e levemente opacas, não\nhá hiperemia nem abaulamento. Além do manejo da febre na conduta para a criança, a melhor\nopção é:","options":{"A":"Observação clínica somente ?espera vigilante?","B":"Antibiótico por 10 dias com amoxacilina","C":"Timpanocentese","D":"Antibiótico ?Sulfametazol +trimetoprima"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-208300","number":"208300","sourceNumber":"208300","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Fibrose Cística é:","options":{"A":"Uma doença que não leva a insuficiência pancreática.","B":"Herdada como traço autossômico dominante.","C":"É comum em negros.","D":"Uma doença multissistêmica hereditária que pode se manifesta em crianças e adultos."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-208324","number":"208324","sourceNumber":"208324","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Como faço a avaliação clínica de desidratação leve:","options":{"A":"Perda de peso 5% em lactentes, menor que 3 % em crianças velhas ou adultos, podendo o\npulso está normal ou aumentado e ter diminuição do débito urinário e sede.","B":"Perda de peso 5% a 10% em lactentes; 3% a 6% em crianças maiores ou adultos, taquicardia,\nolhos e fontanelas encovados e muita lágrima.","C":"Perda de peso 10% em lactantes, maior que 6% em crianças maiores ou adultos, pulso rápido e\nfraco, débito urinário zero e sem lágrima.","D":"Perda de peso 5% em lactentes, maior que 6% em crianças maiores ou adultos, pulso piriforme,\nfraco, diurese diminuída, sem lágrima, mucosa\nressecada e enchimento capilar maior que 3."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-208381","number":"208381","sourceNumber":"208381","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Recém-nascido no 14º dia de vida, apresenta secreção ocular unilateral não purulenta,\ncom início há dois dias, nasceu de parto\nvaginal, a termo. Mãe não fez pré-natal relata disúria e\ncorrimento vaginal há 20 dias. O provável diagnóstico para esse recém-nascido é:","options":{"A":"Infecção por adenovírus.","B":"Infecção por Staphylococcus epidermidis.","C":"Infecção por Chlamydia trachomatis.","D":"Reativa ao uso de nitrato de prata."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-208319","number":"208319","sourceNumber":"208319","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Escolar de sete anos procurou a Unidade Básica de Saúde sua mãe referiu início súbito\nde febre e dor abdominal há um dia. Hoje\nrelata estar com dificuldade para engolir. Ao exame físico\napresenta-se febril, temperatura axilar de 39°C, com aumento de linfonodos próximos ao ângulo da\nmandíbula e na oroscopia apresenta petéquias em palato mole junto com exsudato em tonsilas\npalatinas. Assinale a alternativa com a hipótese diagnóstica e a conduta mais adequada:","options":{"A":"Faringotonsilite estreptocócica. Utilizar penicilina benzatina.","B":"Faringotonsilite estreptocócica. Utilizar associação de amoxicilina com clavulanato de potássio.","C":"Faringotonsilite viral. Utilizar medicações sintomáticas.","D":"Abscesso peritonsiliano. Utilizar ceftriaxona e solicitar avaliação especializada."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-208370","number":"208370","sourceNumber":"208370","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Os pais de um recém-nascido prematuro, nascido com 1.000 g, querem saber o motivo\npelo qual o médico recomendou o uso de palivizumabe ao seu filho. O médico orienta que a\nindicação é:","options":{"A":"Controle do processo inflamatório da displasia broncopulmonar.","B":"Prevenção da infecção pelo citomegalovírus.","C":"Prevenção da infecção pelo vírus respiratório sincicial.","D":"Controle do processo inflamatório da retinopatia da prematuridade."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-176022","number":"176022","sourceNumber":"176022","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"São alterações fisiopatológicas encontradas na gastroparesia, EXCETO:","options":{"A":"Alterações do tônus gástrico e da acomodação à distensão do fundo gástrico.","B":"Distúrbio do ritmo elétrico gástrico (disritmias gástricas).","C":"Espasmos pilóricos.","D":"Hipermotilidade antral."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-176111","number":"176111","sourceNumber":"176111","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança do sexo masculino, 1 ano de idade, é trazida ao atendimento médico com\nhistória de constipação crônica desde o\nnascimento, inicialmente leve, com piora progressiva.\nRefere que mesmo com suplementação de fibras e hidratação adequada, passa vários dias sem\ndefecar, com episódios de ida ao pronto-socorro para alívio das fezes com toque retal e enema\nglicerinado. Apresenta-se chorosa, com abdome distendido, doloroso à palpação, sem irritação\nperitoneal. Ao toque retal, palpou-se fecaloma, provocando eliminação explosiva de fezes. Sobre a\ncondução do caso, assinale a alternativa INCORRETA:","options":{"A":"O achado de dilatação proximal de cólon seguido de cone de transição e cólon distal de calibre\nnormal no enema opaco é compatível com o caso.","B":"O tratamento inicial com corticoides é opção para postergar o tratamento cirúrgico.","C":"O diagnóstico definitivo se dá com biópsia seriadas da parede dos segmentos acometidos do\ncólon, que evidenciaria aganglianose.","D":"O tratamento definitivo consiste na ressecção do segmento acometido, geralmente reto e\nsigmoide, com anastomose coloanal."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-176106","number":"176106","sourceNumber":"176106","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Escolar previamente hígido, 9 anos de idade, iniciou há seis dias com febre,\ncefaleia, coriza inicialmente hialina, tosse seca com evolução produtiva e expectoração\namarelada. No exame de raios X de tórax realizado há três dias, evidenciava-se infiltrado\nintersticial em ambos os pulmões, predominando em regiões hilares e em ambas as bases.\n\nOrientado amoxicilina, via oral, e retorno se piora. Como houve piora clínica nos últimos 2 dias,\nmãe retorna ao pronto atendimento. Ao exame\nfísico, apresentava-se com estertores finos em\n1/3 inferiores em ambos os hemitórax, com raros sibilos expiratórios bilaterais. Ao raio X de\ntórax controle, apresentou piora das imagens anteriores. Assinale a alternativa que apresenta o\nprovável diagnóstico:","options":{"A":"Pneumonia por Haemophilus influenzae.","B":"Pneumonia por Mycoplasma pneumoniae.","C":"Pneumonia por Pneumococo.","D":"Pneumonia por Estafilococo."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-176045","number":"176045","sourceNumber":"176045","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pré-escolar procura, acompanhado de sua mãe, unidade de pronto atendimento, devido\nquadro de diarreia aguda. O médico que o atendeu não observou sinais de desidratação grave e\nprescreveu Terapia de Reidratação Oral (TRO) e observação clínica. Após a primeira hora de\nadministração, paciente apresenta vômitos persistentes, com peristalse presente e manutenção dos\nsinais de desidratação. Nesse caso, segundo o Ministério da Saúde, a CONDUTA ADEQUADA é:","options":{"A":"Suspender a TRO e iniciar terapia intravenosa com soro fisiológico.","B":"Introduzir sonda nasogástrica e iniciar a TRO por gastróclise.","C":"Diminuir o volume e aumentar a frequência das doses de TRO.","D":"Prescrever antiemético e reiniciar a TRO após 30 minutos."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-176066","number":"176066","sourceNumber":"176066","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Escolar de seis anos de idade com quadro progressivo de febre, dor de garganta,\nhiperemia intensa de orofaringe, hipertrofia de\namígdalas, com exsudato, linfadenopatia cervical\nanterior e posterior e submandibular bilateral. Na primeira consulta, havia sido prescrita\namoxicilina\npor dez dias. A mãe relata exantema após três dias de tratamento, sem melhora do quadro clínico.\nDiante dessa evolução, deve-se suspeitar de:","options":{"A":"Faringite por micoplasma.","B":"Infecção por enterovírus coxsackie.","C":"Faringite por estreptococo ß-hemolítico do grupo A.","D":"Mononucleose infecciosa pelo vírus Epstein-Barr."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-176096","number":"176096","sourceNumber":"176096","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Escolar, 5 anos, previamente hígido, é levado ao pronto-socorro com relato de febre\n39°C, tosse produtiva 72 horas. Apresentando,\nao exame físico, frequência respiratória = 58 irpm,\nquando solicitado raio X de tórax mostra derrame pleural de pequeno volume e condensação de\nbase direita. A terapia de início de tratamento é:","options":{"A":"Penicilina cristalina.","B":"Eritromicina.","C":"Vancomicina.","D":"Sulfametoxazol ? trimetropina."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-151886","number":"151886","sourceNumber":"151886","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a doença celíaca, podemos afirmar que:","options":{"A":"São fatores de risco para doença celíaca os indivíduos com diabete melito tipo I e II, doença\nautoimune da tireoide, cirrose biliar primária, síndrome de Turner e síndrome de Down.","B":"A amamentação e o tempo de introdução do trigo na dieta podem reduzir o risco ou atrasar o\naparecimento da doença celíaca em crianças sob risco.","C":"O tratamento da doença celíaca previne a progressão da doença, porém não há remissão com\nmelhora do padrão histológico.","D":"O tratamento é realizado com corticoide, seguido de manutenção com azatioprina."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-151863","number":"151863","sourceNumber":"151863","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Na Estenose Hipertrófica do Piloro (EHP) ocorre:","options":{"A":"Ocorre acidose metabólica.","B":"Tem início na 6ª semana de vida.","C":"Vômito não bilioso é o sintoma inicial.","D":"Icterícia com predomínio de bilirrubina direta."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-151941","number":"151941","sourceNumber":"151941","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 5 anos, sexo masculino, evolui há 3 dias com gastroenterite, febre,\nvômitos, dor abdominal, fezes sanguinolentas,\noligúria e hemograma com anemia importante. O\ndiagnóstico provável é:","options":{"A":"Síndrome hemolítica urêmica.","B":"Invaginação intestinal.","C":"Enterite necrotizante.","D":"Septicemia."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-151928","number":"151928","sourceNumber":"151928","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente com 4 meses, apresenta quadro de Infecção de Vias Aéreas Superiores\n(IVAS) leve, espirro, rinorreia\ntransparente, diminuição do apetite, febre de 38,5°, taquipneia (64\nrpm), oximetria de pulso 90%, ausculta pulmonar com estertores finos e sibilância fraca. Radiografia\nde tórax com hiperinsuflação pulmonar. Qual o diagnóstico provável?","options":{"A":"Crise de asma.","B":"Laringomalacia.","C":"Bronquiolite aguda.","D":"Pneumonia por Clamydia trachomatis."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-151987","number":"151987","sourceNumber":"151987","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Escolar de 5 anos, há uma semana apresenta mal-estar, fadiga, febre, cefaleia, dor de\ngarganta, náuseas, dores abdominais e mialgia. Ao exame físico encontramos: linfadenopatia\ngeneralizada, esplenomegalia e fígado levemente aumentado. Na orofaringe observo aumento\nacentuado das tonsilas com exsudato branco, petéquias no palato e exantema. Ausculta pulmonar\nnormal. Qual o diagnostico provável?","options":{"A":"Miocardite.","B":"Endocardite.","C":"Febre reumática.","D":"Mononucleose infecciosa."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-129796","number":"129796","sourceNumber":"129796","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Você é o pediatra da sala de parto de uma movimentada maternidade na cidade de\nManaus. Nasce durante seu plantão, JP, sexo\nmasculino, peso de nascimento 3.500g, apgar 9/10,\nsem intercorrências. Sua mãe relata ter feito pré-natal, 6 consultas e em seu cartão da gestante,\napresenta os seguintes resultados: HIV não reagente, VDRL 1/16, HBsAG positivo, Toxoplasmose\nIgG positivo e IgM negativo e HCV não reagente. A conduta mais adequada nas próximas horas de\nassistência será:","options":{"A":"Indicar vacinação de BCG antes da alta hospitalar e contra indicar a de Hepatite B.","B":"Encaminhar a mãe do recém-nascido para vacinação após alta.","C":"Indicar vacinação de BCG antes da alta hospitalar, de Hepatite B nas primeiras 12h e aplicar\nsimultaneamente imunoglobulina humana hiperimune contra hepatite B.","D":"Contra indicar BCG e indicar vacina de Hepatite B nas primeiras 12h e aplicar simultaneamente\nimunoglobulina humana hiperimune contra hepatite B."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-129753","number":"129753","sourceNumber":"129753","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação à vacina BCG, podemos afirmar que:","options":{"A":"Pode ser feita em qualquer idade, mesmo em crianças HIV-positivas sintomáticas e filhos de\nmães HIV-positivas.","B":"A via de administração é subcutânea e a evolução da reação vacinal ocorre em até 6 meses,\nnão sendo recomendado revacinação na ausência\nde cicatriz após os seis meses.","C":"É uma vacina atenuada do Mycobacterium bovis que destina-se a prevenir as formas graves de\ntuberculose e cuja aplicação deve ser feita ainda na maternidade.","D":"Os contactantes intradomiciliares de portadores de hanseníase devem receber mais duas doses\nda vacina BCG, se menores de um ano de idade,\ne com esquema vacinal comprovadamente\ncompleto."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-103868","number":"103868","sourceNumber":"103868","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A influenza é uma doença respiratória infecciosa de origem viral, e é um problema de\nsaúde pública no Brasil. Esta patologia pode\nlevar a complicações graves e ao óbito, especialmente\nnos grupos de alto risco para as complicações da infecção viral. A vacinação contra este agravo a\nsaúde deve ser feita, de acordo com as orientações do Ministério da Saúde:","options":{"A":"Nas gestantes e puérperas até 45 dias pós-parto;","B":"Na população indígena que esteja, exclusivamente, entre 6 meses e 5 anos;","C":"A partir dos 3 meses de idade na população não-indígena;","D":"Em todo portador de diabetes ou doença crônica transmissível."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-103795","number":"103795","sourceNumber":"103795","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação a vacinação contra influenza, podemos afirmar:","options":{"A":"Que as crianças que já tomaram uma dose de influenzae em campanhas anteriores, devem\nreceber mais duas doses este ano","B":"Que as crianças que ainda não tomaram nenhuma dose da vacina devem receber duas doses\ncom intervalo de 30 dias","C":"Que os adultos também devem tomar duas doses com intervalo de 30 dias entre elas,\nindependente do esquema vacinal anterior","D":"As crianças indígenas devem tomar apenas uma dose, independente da situação vacinal"},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-103823","number":"103823","sourceNumber":"103823","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Portaria 3.318 de Outubro de 2010 do Ministério da Saúde institui, em todo território\nnacional, o calendário básico de vacinação. De acordo com este calendário, as vacinas indicadas\nno pré-natal de baixo risco são:","options":{"A":"Dupla bacteriana e contra hepatite B.","B":"Anti-influenzae e tríplice viral.","C":"Contra hepatite B e tríplice viral.","D":"Contra febre amarela e contra varicela."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-103850","number":"103850","sourceNumber":"103850","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em 2014, o Programa Nacional de Imunizações, ampliou o calendário nacional de\nvacinações e incluiu a vacina contra Hepatite A. Em relação a esta vacina, o Ministério da Saúde\npreconiza que:","options":{"A":"A idade máxima para administração da vacina é de 36 meses","B":"Deve ser feita nas crianças aos 12 meses de vida","C":"A vacina é segura em gestantes e puérperas","D":"O esquema vacinal preconizado é de duas doses"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-103839","number":"103839","sourceNumber":"103839","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No calendário de vacinação do Ministério da Saúde do Brasil, aos 12 meses de idade, a\ncriança deve receber a vacina tríplice viral, vacina de vírus vivos atenuados: sarampo, rubéola e\ncaxumba. Quanto à caxumba, qual a complicação mais frequente?","options":{"A":"Meningite com ou sem encefalite","B":"Artrite","C":"Apendicite","D":"Faringite"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-81090","number":"81090","sourceNumber":"81090","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Ana Paula leva seu filho de 9 meses ao CAIC, relata que teve diarreia há 5 dias e agora\nestá melhor. Na avaliação é constatado que a\ncriança tem no cartão de vacina registro de 1 dose\nde BCG e 2 doses de hepatite B. Qual a melhor conduta:","options":{"A":"Tratar a diarreia e solicitar à mãe que volte em uma semana para atualizar vacinas.","B":"Aplicar uma dose de cada uma das vacinas, hepatite B, tetravalente bacteriana, poliovírus oral,\nrotavírus oral, febre amarela.","C":"Aplicar uma dose de cada uma das vacinas: hepatite B, tetravalente bacteriana,\nantipneumocócica, poliovírus oral e febre amarela.","D":"Aplicar somente vacinas de via parenteral e evitar as formulações orais.","E":"Não aplicar nenhuma vacina."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-80984","number":"80984","sourceNumber":"80984","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Adriana, 29 anos, G2A0P1, IG = 17s, vem para consulta de pré-natal com seu médico\nde família e comunidade, trazendo seu cartão\nde vacina onde se observa três doses de vacina\nantitetânica aplicadas na gestação anterior há sete anos. Em relação à profilaxia do tétano\nneonatal, o médico de família e comunidade deve:","options":{"A":"Reiniciar o esquema vacinal com três doses, devido ao tempo desde a última vacina.","B":"Orientar a necessidade de dose de reforço.","C":"Orientar que a mesma está imunizada, não sendo necessário dose de reforço.","D":"Aplicar reforço após o parto, a fim de proteger a próxima gestação.","E":"Informar que não há necessidade de saber história vacinal anterior."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-81975","number":"81975","sourceNumber":"81975","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um dos instrumentos que contamos no acompanhamento da Saúde dos Adolescentes\né a Caderneta de Saúde do Adolescente dentro\nda qual encontramos informações importantes tais\ncomo:","options":{"A":"Gráficos de peso x idade; altura x idade e índice de massa corporal x idade, além das tabelas de\npressão arterial e maturação sexual.","B":"Os direitos dos adolescentes, de acordo com a Constituição Brasileira e com o Estatuto da\nCriança e do Adolescente, e que determinam que lhes é vetado acompanhante durante\ninternações.","C":"Tabelas de desenvolvimento de Tanner para caracteres sexuais tanto masculinos quanto\nfemininos em todas as cadernetas, independente do sexo.","D":"Gráficos com a medida de pressão arterial por idade e índice de massa corporal.","E":"Orientações sobre saúde, alimentação saudável, prática esportiva e cuidado com a saúde bucal,\nalém do calendário vacinal desta faixa etária."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-82001","number":"82001","sourceNumber":"82001","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação à Caderneta de Saúde da Criança, podemos afirmar que contém dados\nessenciais a sua saúde, EXCETO:","options":{"A":"Caderneta de vacinação das crianças e informações sobre suplementação de Ferro e vitamina\nA.","B":"Tabela para avaliação do desenvolvimento infantil de 0 a 3 anos.","C":"Dados sobre a gravidez, parto e puerpério e dados sobre o recém-nascido.","D":"Gráficos de índice de massa corporal x idade e pressão arterial x idade.","E":"Gráficos de perímetro cefálico x idade; peso x idade; altura x idade."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-294454","number":"294454","sourceNumber":"294454","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional injetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5 g/dl, ferritina: 25 ng/ml,\nvitamina D: 11 ng/dl. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, com relação às alterações\nesperadas para confirmação do diagnóstico mais provável, é CORRETO afirmar:","options":{"A":"As lesões acometem mais o íleo, mas podem ocorrer em todo o tubo digestivo.","B":"Os anticorpos são úteis para o diagnóstico, sendo a biópsia gástrica o padrão-ouro.","C":"A realização de uma colonoscopia é essencial para avaliação, pois as alterações são mais\nfrequentes no cólon.","D":"No anatomopatológico, observa-se redução da relação vilo/cripta e infiltração de linfócitos na\nmucosa."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-294455","number":"294455","sourceNumber":"294455","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional\ninjetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5g/dL, ferritina 25ng/mL,\nvitamina D 11ng/dL. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, Identifique o anticorpo associado\nao diagnóstico mais provável.","options":{"A":"Anticélula parietal.","B":"Antitransglutaminase tecidual.","C":"Anti-Saccharomyces cerevisae (ASCA).","D":"Anticitoplasma de neutrófilo (ANCA)."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-294456","number":"294456","sourceNumber":"294456","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional injetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5g/dL, ferritina 25ng/mL,\nvitamina D 11ng/dL. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, Indique a conduta terapêutica\ninicial mais adequada.","options":{"A":"Suspender o metódo contraceptivo.","B":"Adotar dieta isenta de glúten.","C":"Realizar corticoterapia.","D":"Fazer uso de Imunobiológico."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-294484","number":"294484","sourceNumber":"294484","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Duas meninas, uma de 3 e outra de 8 anos de idade, são atendidas na UPA com\nquadro de náuseas, vômitos, dor abdominal e\ndiarreia há, aproximadamente, 4 horas. As fezes são\nlíquidas, com rajas de sangue e \"incontáveis episódios\". Há relato de que, há 3 dias, haviam\nalmoçado em um bufê e comeram frango assado e salada de maionese. Os pais, que haviam\ncomido frango, mas não a maionese, negam alterações. Ao exame, ambas estavam hipoativas,\ncom salivação reduzida. Temperatura da criança maior: 37,8°C; e da criança menor: 38,2°C. Diante\nda situação descrita, identifique a classificação da diarreia e o agente etiológico mais frequente.","options":{"A":"Diarreia Aquosa - Cryptosporidium.","B":"Diarreia Aquosa - Salmonella.","C":"Disenteria - Shigella.","D":"Disenteria - Ameba."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-294485","number":"294485","sourceNumber":"294485","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Duas meninas, uma de 3 e outra de 8 anos de idade, são atendidas na UPA com\nquadro de náuseas, vômitos, dor abdominal e\ndiarreia há, aproximadamente, 4 horas. As fezes são\nlíquidas, com rajas de sangue e \"incontáveis episódios\". Há relato de que, há 3 dias, haviam\nalmoçado em um bufê e comeram frango assado e salada de maionese. Os pais, que haviam\ncomido frango, mas não a maionese, negam alterações. Ao exame, ambas estavam hipoativas,\ncom salivação reduzida. Temperatura da criança maior: 37,8°C; e da criança menor: 38,2°C.\nIndique a natureza das manifestações extraintestinais que constituem as complicações mais\nfrequentes dessa doença.","options":{"A":"Cirúrgicas.","B":"Neurológicas.","C":"Oftalmológicas.","D":"Reumatológicas."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-284571","number":"284571","sourceNumber":"284571","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mulher, 25 anos de idade, moradora de Salvador, comparece ao ambulatório de clínica\nmédica queixando-se de prurido nasal e em conduto auditivo frequentes. Relata ter quadros\nsemelhantes desde a infância, associados a salvas de espirros, obstrução nasal e coriza hialina.\n\nMudou-se há cerca de dois meses e, desde então, vem tendo queixas praticamente diárias,\nimpedindo o sono e dificultando prestar\natenção as aulas na faculdade. Refere que o seu quarto\npossui tapete e uma coleção de bichos de pelúcia. A cama fica encostada numa parede que separa\no quarto do banheiro. Possui um cágado de estimação. Não possui plantas. Ao exame físico,\nencontra-se em bom estado geral, com sinais vitais estáveis. Ausculta cardiorrespiratória e exame\nabdominal normal. Mucosa nasal pálida, com presença de rinorreia clara e gotejamento pós-nasal\nposterior. Indique o diagnóstico mais provável para a paciente.","options":{"A":"Rinite alérgica intermitente exacerbada.","B":"Rinite alérgica persistente leve.","C":"Rinite alérgica persistente moderada a grave.","D":"Rinossinusite crônica."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-284572","number":"284572","sourceNumber":"284572","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mulher, 25 anos de idade, moradora de Salvador, comparece ao ambulatório de clínica\nmédica queixando-se de prurido nasal e em conduto auditivo frequentes. Relata ter quadros\nsemelhantes desde a infância, associados a salvas de espirros, obstrução nasal e coriza hialina.\n\nMudou-se há cerca de dois meses e, desde então, vem tendo queixas praticamente diárias,\nimpedindo o sono e dificultando prestar\natenção as aulas na faculdade. Refere que o seu quarto\npossui tapete e uma coleção de bichos de pelúcia. A cama fica encostada numa parede que separa\no quarto do banheiro. Possui um cágado de estimação. Não possui plantas. Ao exame físico,\nencontra-se em bom estado geral, com sinais vitais estáveis. Ausculta cardiorrespiratória e exame\nabdominal normal. Mucosa nasal pálida, com presença de rinorreia clara e gotejamento pós-nasal\nposterior. Indique a terapia farmacológica de primeira escolha para essa paciente.","options":{"A":"Mometasona intranasal.","B":"Prednisolona via oral.","C":"Loratadina via oral.","D":"Amoxacilina com ácido clavulânico via oral."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-284573","number":"284573","sourceNumber":"284573","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mulher, 25 anos de idade, moradora de Salvador, comparece ao ambulatório de clínica\nmédica queixando-se de prurido nasal e em conduto auditivo frequentes. Relata ter quadros\nsemelhantes desde a infância, associados a salvas de espirros, obstrução nasal e coriza hialina.\n\nMudou-se há cerca de dois meses e, desde então, vem tendo queixas praticamente diárias,\nimpedindo o sono e dificultando prestar\natenção as aulas na faculdade. Refere que o seu quarto\npossui tapete e uma coleção de bichos de pelúcia. A cama fica encostada numa parede que separa\no quarto do banheiro. Possui um cágado de estimação. Não possui plantas. Ao exame físico,\nencontra-se em bom estado geral, com sinais vitais estáveis. Ausculta cardiorrespiratória e exame\nabdominal normal. Mucosa nasal pálida, com presença de rinorreia clara e gotejamento pós-nasal\nposterior. Identifique as afecções classicamente associadas ao diagnóstico do caso.","options":{"A":"Dermatite atópica e doença de Sjögren.","B":"Otite serosa e fibrose cística.","C":"Ptiriase alba, esofagite eosinofílica.","D":"Asma brônquica e artrite reumatoide."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-284610","number":"284610","sourceNumber":"284610","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina, 8 anos de idade, é trazida ao pronto atendimento com dispneia e dor\nventilatória dependente há 4 dias. Há dois dias vem\ncursando com febre alta (não aferida)\nassociada a calafrios e tosse produtiva. A radiografia de tórax mostra derrame pleural à direita.\nIndique o agente etiológico mais provável, considerando os aspectos clínicos, epidemiológicos e\nradiológicos.","options":{"A":"Moraxella catarrhalis.","B":"Haemophilus influenzae.","C":"Staphylococcus aureus.","D":"Streptococcus pneumoniae."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-358782","number":"358782","sourceNumber":"358782","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Maria, 5 anos, preta chega à Unidade de Saúde da Família do Sucupira, unidade\nreferência, acompanhada da mãe, Josélia, 30 anos,\nque a pegou na creche há 30 minutos. A\ndiretora da creche ligou para os pais, pois Maria estava com o nariz muito entupido, coriza, tosse e\niniciou um quadro de febre hoje logo pela manhã. Apresentou dois episódios de vômito, seguidos\nde tosse. A criança recusou-se a tomar água (oferecido depois do vômito) e o segundo episódio de\nvômito foi após oferta do café da manhã na creche. Ao exame físico: Pulso cheio com frequência\nde 91 batimentos por minuto, Frequência Respiratória: 22 irpm, Temperatura axilar: 37.9°C, pele\ncom turgor normal, mucosas hidratadas, ausculta cardíaca e respiratória sem alterações, abdome\nnormotenso, descompressão brusca negativa. Diante deste caso, a conduta inicial mais correta é:","options":{"A":"Solicitar exames gerais para investigação de pneumonia e gastroenterite infecciosa e prescrever\nanti-pirético e Soro de Reidratação oral.","B":"Tranquilizar o pai, prescreve Soro de Reidratação Oral para ser administrado na própria unidade\nde saúde devido à recusa da criança, até que\na mesma reinicie micção e orienta a fazer lavagem\nnasal com Soro Fisiológico 0,9% para casa.","C":"Tranquilizar o pai, prescreve para casa anti-pirético, orienta repouso e lavagem nasal com soro\nfisiológico 0,9% para desobstrução nasal e que retorne à unidade de saúde em caso de piora ou\npersistência dos sintomas.","D":"Tranquilizar o pai, prescrever para casa anti-pirético, antibioticoterapia oral e Soro de\nReidratação e lavagem nasal com Soro Fisiológico 0,9%.","E":"Encaminhar para Pronto-Socorro de Pediatria mais próximo."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343348","number":"343348","sourceNumber":"343348","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa correta sobre o(s) exame(s) complementar(es) indicado(s) no\ndiagnóstico diferencial da bronquiolite obliterante.","options":{"A":"Tomografia de tórax.","B":"Raio X e ressonância magnética de tórax.","C":"Raio X de tórax, eletrocardiograma e ecocardiograma.","D":"Hemograma, DHL e ácido úrico."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343356","number":"343356","sourceNumber":"343356","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. A principal hipótese diagnóstica é:","options":{"A":"Displasia neuronal do tipo B.","B":"Constipação funcional.","C":"Doença de Hirschsprung.","D":"Enterocolite necrotizante."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343357","number":"343357","sourceNumber":"343357","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente masculino, 3 meses de vida, portador de trissomia do cromossomo 21,\ncardiopata, é trazido pela mãe em consulta\ndevido ao quadro de constipação intestinal. Relata que\ndesde o nascimento necessita de uso de supositório diários para evacuações efetivas. Apresentou\neliminação de mecônio aos 4 dias de vida, após estímulo retal. Já fez uso de inúmeras fórmulas\nlácteas, sem sucesso. Nega febre, perda ponderal. Nega vômitos. Nega queda do estado geral.\n\nNega outras queixas. Ao exame físico: bom estado geral, estável, corado, hidratado. Abdome\nflácido, indolor, sem massas palpáveis, sem\nsinais de irritação peritoneal. Toque retal com saída de\ngrande quantidade de fezes após manipulação. Para a investigação, foi solicitado exame\ncontrastado abaixo, e realizado biopsia retal. Das alternativas abaixo, a conduta mais adequada é:","options":{"A":"Cirurgia de urgência.","B":"Tratamento clínico com ajuste dietéticos e laxativos, apenas.","C":"Dieta zero, sonda gástrica em drenagem e antibioticoterapia.","D":"Colostomia e abaixamento de cólon posteriormente ou manejo de cólon e tratamento cirúrgico\nendoanal sem colostomia."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-314292","number":"314292","sourceNumber":"314292","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a constipação, analise as assertivas e identifique com V as verdadeiras e com F\nas falsas. ( ) Em geral, os laxantes\nosmóticos são razoavelmente seguros, mesmo quando usados\nregularmente. ( ) A constipação é comum entre idosos por causa de uma alimentação com poucas\nfibras, pela falta de exercício, pelas comorbidades e pelo uso de medicamentos anticolinérgicos. ( )\nAbdome distendido, timpânico à percussão, é um achado que afasta a suspeita de constipação\ncrônica. A alternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"V F V","B":"V V F","C":"F V V","D":"F V F","E":"F F V"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-281865","number":"281865","sourceNumber":"281865","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa que apresenta o objetivo no manejo do paciente com Bronquiolite\nViral Aguda.","options":{"A":"Reduzir o processo de evolução da doença para forma grave.","B":"Controlar a evolução da febre.","C":"Reduzir possibilidade de intubação orotraqueal.","D":"Garantir que o paciente aceite a dieta habitual e não tenha sinais de agravo do ponto de vista\nrespiratório."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-281882","number":"281882","sourceNumber":"281882","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A figura abaixo ilustra uma piloromiotomia pela técnica de Fredet-Ramstedt. Tal\nprocedimento é realizado para o tratamento de:","options":{"A":"Doença do refluxo gastroesofágico.","B":"Atresia duodenal.","C":"Atresia antropilórica.","D":"Estenose hipertrófica de piloro."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-249980","number":"249980","sourceNumber":"249980","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação à síndrome dos vômitos cíclicos (SVC), assinale a alternativa correta:","options":{"A":"O diagnostico de SVC deve contar obrigatoriamente com 1 episodio por mês, em 6 meses de\nintensas náuseas e vômitos paroxísticos.","B":"Os episódios são sempre iguais em todos os pacientes.","C":"Os episódios são separados por semanas a meses, com retorno à saúde basal entre os\nepisódios de vômitos.","D":"Os pacientes podem apresentar apenas náuseas, apenas vômitos ou náuseas e vômitos\nassociados."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-249981","number":"249981","sourceNumber":"249981","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa correta sobre regurgitação, vômitos e ruminação:","options":{"A":"Regurgitação, assim como o vômito, envolve o diafragma, o estômago e o intestino.","B":"A regurgitação é um vômito pequeno.","C":"Ruminação é um vômito que é mastigado e engolido novamente.","D":"Vômito envolve o sistema nervoso central com envolvimento de músculos esqueléticos nos\nquais o conteúdo gástrico é expelido pela boca por causa da coordenação de movimentos do\nintestino delgado, do estômago, do esôfago e do diafragma."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-249982","number":"249982","sourceNumber":"249982","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre os critérios diagnósticos de disquezia em lactentes, assinale a alternativa\ncorreta:","options":{"A":"O choro antes de uma evacuação bem ou mal sucedida e, pelo menos, 10 minutos de pressão\nestá presente.","B":"A maioria dos lactantes apresenta outros problemas de saúde.","C":"Os sintomas persistem por mais de 30 minutos.","D":"O choro antes de uma evacuação mal sucedida e, pelo menos, 20 minutos de pressão está\npresente."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-218166","number":"218166","sourceNumber":"218166","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Maria Aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretaria de Saúde do Estado e do Município, Maria fez a mamografia também com resultados\nnormais. Maria Aparecida teve menarca aos 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e\num filho, Carlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida\nmenstrua regularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de\nPaulo há 2 anos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem\nde 30 anos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é\nhipertensa em uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA 140/90 mmHg,\npesa 78 kg, mede 1,60 m de altura (IMC 30,5). Maria Aparecida e Valdomiro retornam para mais\numa consulta do pré-natal. Daiane, como de costume pergunta para ambos como estão. Eles falam\nsobre Mara, seus cuidados, sua vida de casal e relação homem e mulher entre outras questões.\n\nDaiane pergunta sobre a saúde deles, se têm alguma necessidade. Valdomiro indaga se ele pode\nentão usar a consulta para tratar de um\nproblema dele. Ante a confirmação de Daiane, Valdomiro\nconta que tem apresentado dor de cabeça com dor em face há cerca de três dias. Diz que está com\nsecreção nasal e mal-estar geral, e que não teve febre. Ao exame, sua temperatura estava em\n37,1°C; teve dor à palpação dos seios da face; sua orofaringe estava sem sinais de hiperemia ou\nde hipertrofia de amígdalas; apresentou gotejamento nasal posterior; e a ausculta respiratória não\napresentou alterações patológicas. Ele disse que já teve isso outras vezes. A alternativa que\ncontém a condução mais adequada para este caso é:","options":{"A":"Discutir com o paciente a possibilidade de um caso de rinossinusite aguda, considerando a\nopção de se realizar a observação atenta do\nquadro (para caso de piora dos sintomas) e\n\ntratamento sintomático com solução salina nasal, ingestão aumentada de água e analgesia via oral.","B":"Encaminhar para avaliação com otorrinolaringologista com necessidade de tratamento de\nmanutenção para evitar recidivas tendo em vista que, provavelmente, seja um quadro crônico.","C":"Introduzir antibioticoterapia com amoxacilina + clavulonato (500 + 125 mg a cada 8 horas\ndurante 14 dias), lavagem das narinas com solução salina e analgésicos via oral.","D":"Comunicar ao paciente que se trata de um resfriado e não adotar qualquer conduta já que,\nprovavelmente, haverá melhora espontânea do quadro.","E":"Solicitar a tomografia de seios de face, como método padrão ouro, para a confirmação do\ndiagnóstico de rinossinusite e, seu tratamento subsequente."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-215627","number":"215627","sourceNumber":"215627","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à mediastinite necrotizante\ndescendente aguda.","options":{"A":"O foco da infecção mais comum da mediastinite descendente necrotizante são as sinusopatias\nagudas.","B":"Geralmente é uma infecção polimicrobiana, e os agentes mais comuns são: Pseudomonas\naeruginosa, Staphylococcus aureus e Bacteroides fragilis.","C":"A evolução costuma ser rápida e grave, com taxa de mortalidade alcançando 50%, conforme\nalguns autores.","D":"É mais frequente em população de pior condição socioeconômica, pois a falta de acesso a\nserviços especializados dificulta a prevenção e o tratamento precoce de doenças dentárias e da\norofaringe."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-218172","number":"218172","sourceNumber":"218172","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Maria Aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretarias de Saúde do Estado e do Município, Maria fez a mamografia também com resultados\nnormais. Maria Aparecida teve menarca aos 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e\num filho, Carlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida\nmenstrua regularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de\nPaulo há 2 anos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem\nde 30 anos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é\nhipertensa em uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA 140/90 mmHg,\npesa 78 kg, mede 1,60 m de altura (IMC 30,5). Má está agora com três meses de vida, chega nas\nmãos de Maria Aparecida que apresenta grande apreensão mesmo depois da orientação que\nrecebeu no acolhimento. Daiane olha o prontuário e relembra que Mara nasceu a termo, com 3.120\ng e Apgar 9. Maria Aparecida relata que Má têm apresentado vômitos diários após as mamadas e,\nàs vezes, choro para mamar. Daiane interroga se Mara continua com o aleitamento materno\nexclusivo, se está com boa sucção e sono tranquilo. Maria Aparecida confirma que sim. Daiane\npergunta sobre algum outro sintoma digestivo, urinário ou respiratório. Maria Aparecida nega. Ao\nexame físico, Mara apresenta peso, comprimento, perímetro cefálico e marcos de desenvolvimento\nadequados para a idade. Neste caso clínico, a hipótese diagnóstica mais provável é\n\ne a conduta mais adequada é . A\nalternativa que preenche, CORRETA e sequencialmente, as lacunas do trecho acima é:","options":{"A":"Refluxo gastroesofágico / Iniciar medicação procinética, além de orientar medidas gerais.","B":"Uma estenose hipertrófica congênita do piloro/ Encaminhamento para investigação radiológica.","C":"Intolerância à lactose / Realizar o teste terapêutico com fórmula infantil para lactentes à base\nde\nsoja.","D":"Alergia à proteína do leite de vaca / Orientar dieta materna com restrição de leite de vaca e\nseus\nderivados.","E":"Refluxo gastroesofágico fisiológico / Tranquilizar a mãe e orientá-la quanto às medidas gerais, e\nnova revisão deve ser realizada para observar\nevolução do quadro."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-139791","number":"139791","sourceNumber":"139791","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em crianças com doença celíaca, o tratamento dietético está baseado em:","options":{"A":"Evitar ingestão de arroz e milho.","B":"Evitar ingestão de alimentos que contenham cevada, trigo, centeio e aveia.","C":"Suspender o leite de vaca e seus produtos da alimentação habitual da criança.","D":"Evitar ingestão de alimentos que contenham cacau."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-139765","number":"139765","sourceNumber":"139765","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em relação aos Eventos Adversos Pós-Vacinação, marque (V) para as afirmativas\nVerdadeiras ou (F) para as Falsas e, em\nseguida, indique a alternativa contendo a sequência\nCORRETA. ( ) Alguns eventos adversos são observados com frequência relativamente alta, após a\nadministração de algumas vacinas. No entanto, as manifestações que ocorrem são geralmente\nbenignas e transitórias, e todas elas devem ser notificadas compulsoriamente. ( ) A vacina BCG-ID\npode causar eventos adversos locais, regionais ou sistêmicos, que na maioria das vezes, são\ndecorrentes do tipo de cepa utilizada, quantidade de bacilos inativados administrados técnica de\naplicação e da presença de imunodepressão congênita ou adquirida. ( ) O Episódio Hipotônico\nHiporresponsivo, caracteriza-se por instalação súbita, com um quadro de palidez, diminuição ou\ndesaparecimento do tônus muscular e diminuição ou ausência de resposta a estímulos, podendo\nestar presentes cianose depressão respiratória, sono prolongado com despertar difícil, neste caso,\nhaverá a contraindicação da vacina tetravalente ou DTP. ( ) A Tríplice Viral é uma vacina de vírus\natenuado, liofilizada, cultivada em células de embrião de galinha, portanto, indivíduos com história\nde reação alérgica máculo-papular ao ovo não poderão ser vacinados, assim como também é\nsubsequentes em caso de púrpura trombocitopênica.","options":{"A":"V; V; F; F.","B":"F; F; V; F.","C":"V; F; V; V.","D":"F; V; F; V."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-134680","number":"134680","sourceNumber":"134680","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Das vacinas apresentadas, qual delas é contraindicada em indivíduos\nimunodeprimidos?","options":{"A":"Contra Influenza.","B":"BCG.","C":"Injetável contra Poliomielite.","D":"Contra Hepatite B."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-111827","number":"111827","sourceNumber":"111827","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 7 anos e 10 meses vem ao Posto de Saúde para consulta de rotina.\nAvaliando a Carteira de Vacinação,\nobservou-se que o esquema da Vacina Tríplice Bacteriana\nestava incompleto (tomou apenas as doses de quando era bebê e não recebeu os reforços). Qual é\na sua conduta para esse caso?","options":{"A":"Aplicar a dose de reforço que falta.","B":"Aplicar a dose de reforço com tríplice acelular.","C":"Não aplicar nenhuma vacina agora, esperar a criança completar 10 anos.","D":"Aplicar a dupla adulto."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-350883","number":"350883","sourceNumber":"350883","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 45 dias de vida, há 3 dias passou a apresentar quadro de febre alta não\nmedida, tosse cheia frequente, irritação\nalternando com sonolência e recusa do seio materno por 4\nhorários. Ao exame Estado geral comprometido, FR de 65 rpm, saturação de oxigênio de 89 e\ncianose. Ausculta pulmonar: MVU +, estertores crepitantes difusos e tiragem subcostal e respiração\nabdominal. De acordo com a Organização Mundial da Saúde como classificaríamos o quadro e qual\nseria a conduta imediata?","options":{"A":"Pneumonia grave e internação hospitalar.","B":"Febre sem foco definido e internação hospitalar.","C":"Bronquiolite viral aguda grave e internação hospitalar.","D":"Laringotraqueobronquite grave e internação hospitalar."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-350880","number":"350880","sourceNumber":"350880","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente, 2 anos, é atendido na emergência com quadro de febre (38°C), coriza hialina,\ntosse e recusa alimentar há 3 dias. Ao exame, apresenta orofaringe hiperemiada, com úlceras no\npalato mole e lojas amigdalianas. A conduta indicada nesse caso, além da orientação dos pais,\nconsiste na prescrição de:","options":{"A":"Azitromicina.","B":"Sintomáticos.","C":"Amoxicilina.","D":"Aciclovir."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-350879","number":"350879","sourceNumber":"350879","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente, 8 meses, foi levado ao pediatra do posto de saúde por apresentar crises de\nsibilância desde os 3 meses de vida. Mãe relata que criança apresenta tosse crônica desde os 6\nmeses e que ?não ganha peso?. Refere fezes amolecidas, volumosas e brilhosas. Pré-natal\nadequado. Nasceu a termo. Não fez o teste do pezinho. Estatura está abaixo do Z escore -3 e o\nIMC está entre o Z escore -2 e -3. Radiografia de tórax: hiperinsuflação bilateral, aumento da trama\nbroncovascular bilateralmente. Para confirmar a hipótese diagnóstica mais provável, o exame a ser\nsolicitado é:","options":{"A":"Ecocardiograma.","B":"Dosagem de cloro no suor.","C":"Dosagem de imunoglobulinas.","D":"Broncoscopia com lavado broncoalveolar."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-321325","number":"321325","sourceNumber":"321325","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pré-escolar, 4 anos, em tratamento ambulatorial de pneumonia, retorna 48 horas após\ninício da antibioticoterapia com amoxicilina, para reavaliação clínica. Mãe relata alguma melhora do\napetite, porém persiste com febre. Nega comorbidades. Ao exame: hidratado, FC: 120 bpm, FR: 45\nirpm, sem tiragens, SatO?: 96% em ar ambiente, frêmito toracovocal e murmúrio vesicular\ndiminuídos no 1?3 inferior do hemitórax direito. Qual a conduta mais indicada no momento?","options":{"A":"Manter tratamento ambulatorial, completando esquema antibiótico com amoxicilina.","B":"Manter tratamento ambulatorial, substituindo esquema antibiótico por amoxicilina-clavulonato.","C":"Indicar internação hospitalar, solicitar raio X de tórax para avaliar indicação de toracocentese\ne\nprescrever ampicilina.","D":"Indicar internação hospitalar, solicitar raio X de tórax para avaliar indicação de toracentese e\nprescrever ceftriaxona e oxacilina."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-321334","number":"321334","sourceNumber":"321334","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A mãe de uma criança de 12 meses de idade vem ao ambulatório porque sua filha já\nteve quatro crises de sibilância no último semestre. Ela pergunta ao médico qual a gravidade do\nproblema. Quais sinais de alarme devem ser investigados para identificar a presença ou não de\ndoenças subjacentes de maior gravidade?","options":{"A":"Crise que iniciaram após episódio de bronquiolite que necessitou do uso prolongado de oxigênio.","B":"Crises de início tardio, no segundo semestre de vida, após exposição à fumaça de cigarro.","C":"Crises de tosse seca noturna que podem estar relacionadas com asma atópica.","D":"Crises de sibilância recorrente responsiva a broncodilatadores."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-321336","number":"321336","sourceNumber":"321336","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A mãe de um bebê recém-nascido chega aflita ao consultório com preocupações\nacerca do sono de seu filho. Assinale a\nalternativa correta em relação aos cuidados e orientações\nacerca do sono de bebê recém-nascido.","options":{"A":"Pode bem dormir de barriga para baixo.","B":"Pode usar travesseiros e cobertores, para conforto.","C":"Pode dormir no berço ou na rede ao lado da cama dos pais.","D":"Pode dormir em ambiente iluminado com exposição ao barulho normal da casa durante o dia e a\nnoite."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-292842","number":"292842","sourceNumber":"292842","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de três meses de idade, em aleitamento materno exclusivo, apresenta\nhistória de sangramento intestinal de pequena\nmonta e diarreia com muco e sangue, estado geral\nsatisfatório e ganho de peso adequado. De modo intermitente também apresenta cólica intestinal,\nirritabilidade e choro excessivo. Qual a principal hipótese diagnóstica?","options":{"A":"Gastroenteropatia eosinofílica.","B":"Proctite ou proctocolite alérgica.","C":"Enteropatia induzida por proteínas alimentares.","D":"Síndrome da enterocolite induzida por proteína alimentar (FPIES)."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-259736","number":"259736","sourceNumber":"259736","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 18 meses de idade apresenta a seguinte história clínica: iniciou com\nrinorreia clara, faringite, tosse leve e febre baixa. Após 12 a 48 horas, surgiram os sintomas de\nobstrução de vias aéreas superiores, com progressão dos sinais de insuficiência respiratória e\naumento na temperatura corpórea. Evoluiu no terceiro dia com aumento das frequências cardíaca e\nrespiratória, retrações claviculares, esternais e de diafragma, batimento de aletas nasais, cianose,\nagitação psicomotora até sonolência. Qual hipótese diagnóstica mais provável?","options":{"A":"Abscesso retrofaríngeo.","B":"Laringotraqueobronquite.","C":"Supraglotite infecciosa.","D":"Broncopneumonia."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-259737","number":"259737","sourceNumber":"259737","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 1 ano de idade chega ao pronto-socorro com história de vômitos e diarreia\npersistente há 2 dias e febre de 38°C. A diarreia é aquosa, sem sangue ou muco. A mãe relata que\na criança está com diurese reduzida. Ao exame físico: EG comprometido, olhos fundos, obnubilada,\npouco responsiva, sonolenta, hipocorada (2+/4+), mucosas secas, afebril, anictérica FR: 42 ipm;\nFC: 170 bpm; PA: 80 x 40 mmHg AC ? RCR, 2T, BNF, sem sopros AP ? MVU, sem RA ABD ?\ngloboso, algo distendido, sem visceromegalias, RHA + EXT ? perfusão regular, pulsos finos, TEC\n5s. De acordo com o diagnóstico e classificação do quadro clínico, deve ser estabelecida a\nseguinte conduta terapêutica:","options":{"A":"Deve-se estimar e repor as perdas anormais com reposição de 50 ml/kg/dia na forma de soro\nglicosado a 5% e soro fisiológico (NaCl 0,9%) na proporção de 1:1.","B":"Nessas situações, está indicada a administração do SRO por sonda nasogástrica (de 15 a 30\nml/kg/hora, se houver tolerância) ou mesmo iniciar soroterapia venosa.","C":"A terapia de reposição fluídica deve ser feita com infusão rápida de solução salina isotônica, em\nbolo, no volume de 20 ml/kg, até que a perfusão esteja restaurada.","D":"Fazer hidratação com soro para suprir o gasto metabólico de água, glicose e eletrólitos que pode\nser estimado peso calórico em até 10 kg com\n100 kcal × peso em kg."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-259738","number":"259738","sourceNumber":"259738","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança, 3 anos, atendido no Posto com quadro de tosse produtiva, febre elevada e\ndificuldade de aceitação alimentar. Ao exame: Ausculta pulmonar diminuída em base esquerda,\nfrequência respiratória = 55 irpm, presença de tiragem subcostal, saturando 100% em ar ambiente.\nA terapêutica mais indicada nesse caso é:","options":{"A":"Penicilina Cristalina na dose de 200.000UI/kg/dia e internação.","B":"Amoxicilina ? Clavulanato na dose de 50mg/kg/dia e internação.","C":"Amoxicilina na dose de 50mg/kg/dia e reavaliar ambulatorialmente em 48 horas.","D":"Penicilina Procaína na dose de 50 UI/kg/dia e reavaliar ambulatorialmente em 48 a 72 h."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-259739","number":"259739","sourceNumber":"259739","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 3 anos é atendido no ambulatório com quadro de diarreia crônica,\nacompanhada de distensão abdominal, perda de\npeso, inapetência, alteração de humor com\nirritabilidade e vômitos esporádicos. O paciente também se apresentava emagrecido, com\ndiminuição do tecido celular subcutâneo e atrofia da musculatura glútea. Mãe trouxe um\nhemograma que apresentava anemia. Dentre as opções a seguir, a conduta mais adequada para a\nconfirmação diagnóstica dessa criança e o tratamento indicado é:","options":{"A":"A pesquisa de anticorpos IgE específicos para o leite de vaca, teste de puntura ou prick test e\ndieta de exclusão de proteína do leite de vaca.","B":"A pesquisa de anticorpos IgG específicos para o leite de vaca, teste de puntura ou prick test e\ndieta de exclusão de proteína do leite de vaca.","C":"Anticorpo Antitransglutaminase IgA (AAT)/histopatológico da biópsia de intestino delgado, se\nanticorpo ATT positivo, e dieta de exclusão de glúten.","D":"Anticorpo Antigliadina Deaminada (AAGD)/tipagem HLA-DQ2 e DQ8, se anticorpo AAGD\npositivo, e dieta de exclusão de glúten e contaminantes."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-259745","number":"259745","sourceNumber":"259745","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A mãe de uma criança de cinco anos de idade relata que o filho apresentou crises de\nsibilância durante os três primeiros anos de vida e não mais após essa idade; relata também que as\ncrises eram desencadeadas principalmente por vírus e que foi melhorando com o crescimento.\n\nNunca foi hospitalizado e não havia sintomas de eczema nem de rinossinusite. Assinale a\nalternativa que contém a hipótese diagnóstica\nmais provável para o que essa criança apresentou.","options":{"A":"Sibilância transitória da infância.","B":"Displasia broncopulmonar.","C":"Bronquiolopatia pós-viral.","D":"Asma atópica."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-234046","number":"234046","sourceNumber":"234046","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança, 2 anos, é levado à emergência com quadro de febre e tosse há 3 dias. Exame\nfísico: Tax: 37,2ºC, regular estado geral, FR: 58 irpm e tiragem subcostal. Ausculta pulmonar:\ncrepitações em base de hemitórax esquerdo. Radiografia de tórax: infiltrado em lobo inferior\nesquerdo. A conduta mais adequada nesse caso é:","options":{"A":"Internar para antibioticoterapia parenteral com penicilina cristalina.","B":"Tratamento ambulatorial com amoxicilina e retorno em 48 horas para reavaliar.","C":"Tratamento ambulatorial com azitromicina e retorno em 48 horas para reavaliar.","D":"Solicitar hemograma, proteína-C reativa e VHS, internar para antibioticoterapia se algum dos\nexames sugerir infecção bacteriana."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-234050","number":"234050","sourceNumber":"234050","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 15 meses chega à emergência do hospital com quadro de vômitos e diarreia\nintensa há 24 horas. Mãe relata oligúria, está irritado, tem o turgor da pele diminuído, pulsos\nfinos,\nolhos fundos e lágrimas ausentes. Na avaliação da criança, segundo orientação da Organização\nMundial da Saúde (OMS), qual o grau de desidratação e respectiva terapêutica para o caso?","options":{"A":"Desidratação grave ? criança com diarreia e desidratação grave (> 10% de perda) necessita de\nhospitalização e hidratação endovenosa para restabelecer rapidamente a perfusão aos órgãos\nvitais.","B":"Algum grau de desidratação ? criança com diarreia aguda pode ser tratada no domicílio, com\naumento da oferta de líquidos e após cada evacuação oferecer a SRO, de 50 a 100 ml para\nmenores de 2 anos.","C":"Desidratação grave ? criança com vômitos persistentes, deve-se tentar a administração da SRO\npor sonda nasogástrica (via eficaz), 20\nml/kg/h, durante 4 a 6 horas, oferecendo a SRO em\npequenos volumes.","D":"Algum grau de desidratação ? criança com diarreia e desidratação leve a moderada (5 a 10% de\nperda), realiza-se a reposição com 50 a 100 ml/kg em 3 a 4 horas, oferecendo a SRO em pequenos\nvolumes."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-234051","number":"234051","sourceNumber":"234051","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pré-escolar de três anos, muito irritado, é levado para atendimento médico por\napresentar quadro de diarreia crônica com fezes\nque flutuam na superfície do vaso de odor muito\nfétido, com perda de peso e dor abdominal. Tem história perinatal de fezes espessas, com\ndificuldade para evacuar. Ao exame físico, apresenta hepatomegalia. De acordo com a história\nclínica, qual a hipótese e o exame a ser solicitado para confirmação do diagnóstico?","options":{"A":"Fibrose cística ? Dosagem de Sódio e Cloro no suor.","B":"Doença Celíaca ? Dosagem de Anticorpo antitransglutaminase IgA.","C":"Doença de Crohn ? Colonoscopia com biópsia de intestino delgado.","D":"Abetalipoproteinemia ? Análise lipídica em jejum na criança e nos pais."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-234054","number":"234054","sourceNumber":"234054","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um grande número de fatores de risco, modificáveis ou não, já foram correlacionados\ncom Síndrome de Morte Súbita do Lactente, e são\nclassificados em grupos de fatores biológicos,\nfatores maternos e fatores epidemiológicos. Qual a alternativa abaixo representa fatores de risco\nque contemplam esses três grupos?","options":{"A":"Anemia ferropriva, uso de álcool e drogas na gravidez, mães solteiras.","B":"Baixo nível sócio-econômico dos pais, posição de dormir prona e asfixia.","C":"Fumo pré e pós-natal, infecção do trato urinário e anemia ferropriva na gestação.","D":"Deficiência no mecanismo de despertar, mãe fumante e posição de dormir prona."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-234056","number":"234056","sourceNumber":"234056","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino de 15 meses vem ao ambulatório e sua mãe pergunta sobre sintomas de\nalergia alimentar, já que o filho deverá\nreceber, pela primeira vez, outro leite que não o materno. As\nmanifestações clínicas mais frequentes de Alergia Alimentar são as imediatas, mediadas por IgE, e\ncostumam aparecer em menos de duas horas depois da exposição ao alimento. Quais são as\nmanifestações imediatas de alergia alimentar mais frequentes na prática clínica?","options":{"A":"Manifestações sistêmicas: anafilaxia.","B":"Manifestações respiratórias: asma, rinite, conjuntivite.","C":"Manifestações gastrointestinais: síndrome oral alérgica, diarreia.","D":"Manifestações cutâneas: urticária aguda, angioedema, dermatite atópica."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-234058","number":"234058","sourceNumber":"234058","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pré-escolar, 3 anos, é admitido na sala de reanimação da emergência com insuficiência\nrespiratória. Mãe relata que o quadro iniciou há 3 dias com tosse seca e coriza, evoluindo, hoje,\ncom febre alta (39°C), tosse ladrante, rouquidão e dispneia. Ao exame: estado geral comprometido,\npálido, letárgico. Ausculta pulmonar: murmúrio vesicular reduzido bilateralmente, estridor\ninspiratório e expiratório, FR = 60 irpm, tiragem subcostal e de fúrcula, SatO? = 95%. Prescrita\nnebulização com adrenalina e dose parenteral de corticoide na emergência, porém não houve\nmelhora dos sintomas. Diante do quadro clínico apresentado, a principal hipótese diagnóstica é?","options":{"A":"Crupe viral.","B":"Supraglotite.","C":"Laringotraqueíte bacteriana.","D":"Aspiração de corpo estranho."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-199645","number":"199645","sourceNumber":"199645","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança com 12 meses de idade é levada ao ambulatório com quadro de tosse, febre e\ndificuldade para respirar. No exame físico, estava febril (39ºC) e com tiragem subcostal. Ausculta\npulmonar com murmúrio vesicular diminuído no hemitórax esquerdo e frequência respiratória de 54\nirpm. Qual a melhor conduta nesse caso?","options":{"A":"Tratamento ambulatorial com amoxicilina.","B":"Tratamento hospitalar com penicilina cristalina.","C":"Tratamento ambulatorial com penicilina procaína.","D":"Tratamento hospitalar com ceftriaxona e oxacilina."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-199705","number":"199705","sourceNumber":"199705","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 3 meses de idade, em aleitamento materno exclusivo, apresenta rajas\nde sangue nas fezes, estado geral satisfatório e ganho de peso adequado; ocasionalmente cólica,\nirritabilidade e choro excessivo. Qual a recomendação inicial mais adequada?","options":{"A":"Orientar a manutenção do aleitamento e recomendar uma dieta de restrição para a mãe nutriz.","B":"Recomendar a utilização da proteína hidrolisada de arroz ou de proteína isolada de soja.","C":"Prescrever fórmulas sem a proteína intacta do leite de vaca, extensamente hidrolisadas.","D":"Suspender amamentação por 15 dias; prescrever leite com baixos teores de proteínas."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-199643","number":"199643","sourceNumber":"199643","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 3 meses apresenta episódios frequentes de regurgitação e os pais\npreocupados solicitam a prescrição de medicamentos que os inibam. Durante o exame físico, o\nprofissional constata adequado ganho de peso e desenvolvimento neuropsicomotor. Qual a\norientação adequada a este caso?","options":{"A":"Medidas conservadoras e prescrição de procinético.","B":"Medidas conservadoras, orientação de dieta e posição.","C":"Medidas conservadoras e prescrição de inibidor de bomba de prótons.","D":"Solicitação de radiografia contrastada de esôfago, estômago e duodeno."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-199797","number":"199797","sourceNumber":"199797","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Mãe leva criança de 2 anos à unidade básica de saúde por apresentar fezes aquosas\nvárias vezes ao dia há 4 dias, sem muco ou\nsangue. Refere episódio febril autolimitado no primeiro\ndia e episódios de vômitos quando tenta alimentar a criança. Ao exame, encontra-se afebril,\nfrequência respiratória = 20 irpm, irritada e chorosa (sem lágrimas), a prega cutânea abdominal\nretorna em 1 segundo. Peso da criança 10 kg. Qual a melhor conduta para o caso?","options":{"A":"Aumento da oferta de líquidos e manter alimentação em domicílio.","B":"Sais de reidratação oral, 750 ml em 4 horas sob observação na unidade.","C":"Sais de reidratação oral, 500 ml/dia e antibioticoterapia para o domicílio.","D":"Sais de reidratação oral, 100 ml a cada evacuação diarreica e dieta branda."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-173020","number":"173020","sourceNumber":"173020","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No ambulatório, os pais de uma criança de 2 anos e seis meses de idade relatam que a\nmesma apresentou episódio de apneia e perda da consciência após queda de velocípede. Em\nseguida, apresentou hipotonia, tremores e letargia posterior. Não ocorreu cianose. Abordagem\ndiagnóstica. Qual o diagnóstico clínico mais provável?","options":{"A":"Síncope.","B":"Mioclonias benignas.","C":"Crises de perda do fôlego.","D":"Crise não-epiléptica psicogênica."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-173029","number":"173029","sourceNumber":"173029","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Chega ao ambulatório uma criança de 3 anos e 6 meses de idade, previamente\nsaudável, apresentando quadro agudo de febre, tosse\ne taquidispneia. Na avaliação clínica, o\nmédico detecta: frequência respiratória de 52 respirações por minuto, tiragem subcostal, recusa de\ntomar líquidos, sonolência excessiva, batimento de asa do nariz. Segundo critérios da Organização\nMundial da Saúde, qual a principal hipótese diagnóstica?","options":{"A":"Pneumonia muito grave.","B":"Crise aguda grave de asma.","C":"Bronquiolite viral aguda grave","D":"Laringotraqueobronquite bacteriana"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-172993","number":"172993","sourceNumber":"172993","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 5 meses, em aleitamento materno exclusivo, curva de crescimento normal\ne aspectos do desenvolvimento global sem\nalterações, vem a consulta de rotina e sua mãe relata\nque o menino continua a apresentar episódios de regurgitações de pequena a moderada\nquantidade, principalmente após o término da mamada, cerca de 2 a 3 vezes por dia, desde o\nsegundo mês de vida. Nega episódios de pneumonia, apneia ou sibilância. Qual a melhor conduta\npara esta criança?","options":{"A":"Investigação para alergia à proteína do leite de vaca.","B":"Investigação para doença do refluxo gastroesofágico.","C":"Iniciar tratamento para doença do refluxo gastroesofágico.","D":"Tranquilizar a mãe e orientar sobre os sinais e sintomas de alarme."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-150839","number":"150839","sourceNumber":"150839","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No atendimento de uma criança de 3 anos de idade, gravemente enferma, o médico\nresidente tem dificuldade em definir o grau de instabilidade nos sistemas vitais da criança e o\nrisco\niminente de morte. Qual a alternativa abaixo que menciona tais sinais?","options":{"A":"Alteração do nível de consciência.","B":"Saturação de oxigênio menor do que 95%.","C":"Frequência cardíaca maior do que 160 batimentos por minuto.","D":"Frequência respiratória maior do que 50 respirações por minuto."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-126973","number":"126973","sourceNumber":"126973","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No centro de saúde, uma criança de 11 meses de idade, recém-chegada de\nSanta Catarina, saudável, procura consulta de puericultura. Ao analisar a caderneta de saúde, o\nmédico avalia que todas as vacinas correspondentes à idade foram aplicadas, levando em\nconsideração o Calendário Nacional de Vacinação do Ministério da Saúde. Qual das\nalternativas contém as vacinas que foram aplicadas na criança?","options":{"A":"BCG (1 dose); contra hepatite B (3 doses); contra difteria, tétano, coqueluche, Haemophilus\ninfluenzae (3 doses); antipólio (3 doses); antipneumocócica (2 doses); antirrotavírus (2 doses);\nantimeningocócica C (3 doses).","B":"BCG (1 dose); contra hepatite B (3 doses); contra difteria, tétano, coqueluche, Haemophilus\ninfluenzae (3 doses); antipólio (3 doses); antipneumocócica (3 doses); antirrotavírus (2 doses);\nantimeningocócica C (2 doses).","C":"BCG (1 dose); contra hepatite B (2 doses); contra difteria, tétano, coqueluche, Haemophilus\ninfluenzae (2 doses); antipólio (3 doses); antipneumocócica (4 doses); antirrotavírus (2 doses);\nantimeningocócica C (2 doses).","D":"BCG (1 dose); contra hepatite B (3 doses); contra difteria, tétano, coqueluche, Haemophilus\ninfluenzae (3 doses); antipólio (3 doses); antipneumocócica (2 doses); antirrotavírus (3 doses);\nantimeningocócica C (3 doses)."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-102090","number":"102090","sourceNumber":"102090","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A mãe de uma criança de 17 meses de idade apresenta o cartão de vacinas totalmente\nadequado para a idade de seu filho. Qual a alternativa que contém as vacinas aplicadas nos\núltimos três meses?","options":{"A":"dTpa + Hib + pólio + vacina contra hepatite A + tetra viral.","B":"DTPa + Hib + pólio + vacina contra hepatite A + tetra viral + influenza.","C":"DTPa + pólio + antipneumocócica + vacina contra hepatite A + tetra viral.","D":"DTPa + Hib + pólio + antipneumocócica + vacina contra hepatite A + tetra viral."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-81235","number":"81235","sourceNumber":"81235","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 12 meses de idade chega ao centro de saúde para uma consulta de rotina.\nA caderneta de Saúde da Criança mostra que\nsomente foram realizadas as vacinas da criança até\nos seis meses de idade. Considerando o atual calendário de vacinas do Ministério da Saúde, quais\nvacinas devem ser dadas a essa criança?","options":{"A":"Pneumocócica 10-valente + tríplice viral.","B":"Pneumocócica 10-valente + meningocócica C.","C":"Pneumocócica 10-valente + vacina tetra viral.","D":"Pneumocócica 10-valente + pólio oral."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-81250","number":"81250","sourceNumber":"81250","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente com seis meses de idade é levado para atendimento no centro de saúde com\nquadro de diarreia há três dias associada a vômitos e febre. As fezes são aquosas, sem muco ou\nsangue. O exame físico revela criança letárgica, com dificuldade para ingerir líquidos, olhos muito\nfundos, sem lágrimas e tempo de enchimento capilar maior que 5 segundos. Considerando o\nquadro acima, qual a melhor conduta terapêutica?","options":{"A":"Sais de reidratação oral por sonda gástrica.","B":"Sais de reidratação oral via oral.","C":"Hidratação via intraóssea.","D":"Hidratação venosa."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-81286","number":"81286","sourceNumber":"81286","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de cinco meses de idade, com história de febre e vômitos há dois dias,\nassociados à irritabilidade e recusa\nalimentar. O exame físico mostra fontanela anterior abaulada e\nsinais de irritação meníngea. O liquor foi compatível com meningite e a bacterioscopia revelou\nHaemophilus influenzae. Foi iniciado ceftriaxona para tratamento. A criança mora com os pais e\numa irmã de 17 meses de idade, que possui na caderneta da criança três doses da vacina\npentavalente (2, 4 e 6 meses). A conduta mais indicada para a proteção dos contactantes nesse\ncaso é:","options":{"A":"Quimioprofilaxia com rifampicina para os pais e irmã.","B":"Quimioprofilaxia com rifampicina para o caso e para a irmã.","C":"Quimioprofilaxia com rifampicina somente para os pais.","D":"Quimioprofilaxia com rifampicina para o caso, os pais e a irmã."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-365654","number":"365654","sourceNumber":"365654","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A fibrose cística, que já foi considerada uma doença da infância, é agora também uma\ndoença do adulto. O aumento da longevidade\nresultou em mais problemas médicos relacionados\ncom a idade e com a própria doença. O crescente número de adultos com fibrose cística resultou\nem aumento da necessidade de cuidados médicos. (DALCIN, Paulo de Tarso Roth; ABREU e\nSILVA, Fernando Antônio de. Fibrose cística no adulto: aspectos diagnósticos e terapêuticos. Jornal\nBrasileiro de pneumologia 34 (2008)). O método indicado para o diagnóstico da fibrose cística e o\ntratamento são, respectivamente,","options":{"A":"teste do cloro no suor e azitromicina.","B":"espirometria e uso de formoterol.","C":"tomografia de tórax e uso de prednisona via oral.","D":"broncoscopia e N-acetilcisteína."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-349758","number":"349758","sourceNumber":"349758","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Intolerância à Lactose (IL) e a Alergia à Proteína do Leite de Vaca (APLV) possuem\nsinais e sintomas semelhantes, por isso a\nimportância de avaliar a diferença em sua origem, sinais\ne sintomas. Sobre esse assunto, assinale a alternativa correta.","options":{"A":"Na sua grande maioria, os casos de IL são associados a uma condição genética de pessoas de\norigem asiática.","B":"Urticária, inchaço e vômito podem ser consequência da APLV.","C":"A APLV é uma condição benigna que afeta apenas crianças e desaparece na adolescência.","D":"Na IL, não são recomendados testes de tolerância à lactose e de hidrogênio no ar expirado,\ndevido ao risco de insuficiência respiratória.","E":"Na APLV, a conduta será prescrever medicamentos antialérgicos ou anti-inflamatórios."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-365642","number":"365642","sourceNumber":"365642","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 15 meses de vida foi levado ao pronto atendimento pela segunda vez\nem cinco dias. Na primeira visita,\napresentava febre (máx. = 38 ºC), tosse e rinorreia. Foi atendido e\nliberado com orientação de limpeza nasal e antitérmico. No quinto dia, a mãe retornou com o filho,\nreferindo que a criança está há 24 horas afebril, porém observou piora da tosse e dispneia. Ao\nexame físico, o paciente encontra-se em regular estado geral, desidratado 1+/4+, com Tax = 36,8\nºC, FR = 50 irpm, SatO2 = 89% em a.a., sibilos expiratórios, discreta tiragem intercostal e ausência\nde cianose. Realizou testes rápidos para Sars-CoV-2 e influenza A, os quais foram negativos.\n\nQuanto à provável etiologia nesse caso clínico, assinale a alternativa correta.","options":{"A":"Vírus sincicial respiratório","B":"Pneumococo","C":"Staphylococcus aureus","D":"Adenovírus"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-349757","number":"349757","sourceNumber":"349757","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de dois anos tem uma pneumonia, com derrame pleural extenso, causada\npor estafilococo. Ele encontra-se acordado com\nsinais moderados de desconforto respiratório e\ncom cateter nasal de oxigênio a 3L/min. Em decorrência do quadro, há necessidade de drenagem\ntorácica e, ao preparar o material, o cirurgião passa orientações ao residente. Assinale a\nalternativa\nque apresenta a orientação correta repassada pelo cirurgião ao residente.","options":{"A":"Não há necessidade de anestesia local, pois a ferida não permite ação do analgésico.","B":"Quanto menor o calibre do dreno, melhor será a recuperação do paciente.","C":"Em geral, a melhor conduta é apenas a punção de alívio.","D":"As imagens de ultrassom podem guiar melhor a posição do dreno e, assim, alcançar áreas com\nabscessos fechados.","E":"O paciente deve estar sob intubação mecânica para a drenagem."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-365641","number":"365641","sourceNumber":"365641","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 15 meses de vida foi levado ao pronto atendimento pela segunda vez\nem cinco dias. Na primeira visita,\napresentava febre (máx. = 38 ºC), tosse e rinorreia. Foi atendido e\nliberado com orientação de limpeza nasal e antitérmico. No quinto dia, a mãe retornou com o filho,\nreferindo que a criança está há 24 horas afebril, porém observou piora da tosse e dispneia. Ao\nexame físico, o paciente encontra-se em regular estado geral, desidratado 1+/4+, com Tax = 36,8\nºC, FR = 50 irpm, SatO2 = 89% em a.a., sibilos expiratórios, discreta tiragem intercostal e ausência\nde cianose. Realizou testes rápidos para Sars-CoV-2 e influenza A, os quais foram negativos. Em\nrelação ao caso mencionado, assinale a alternativa que apresenta a conduta adequada.","options":{"A":"Salbutamol, metilprednisolona IV e oferta de O2 por cateter de alto fluxo.","B":"Salbutamol, prednisolona VO e oferta de O2 por cateter nasal.","C":"Ampicilina IV, prednisolona VO e oxigenioterapia por cateter de alto fluxo.","D":"Oxigenioterapia por cateter nasal, hidratação venosa e aspiração nasal, se necessário."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-349754","number":"349754","sourceNumber":"349754","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de dois anos de idade teve, há 10 dias, um quadro diarreico. Foi internado\nhá 48h, apresentando plaquetopenia, queda do\nhematócrito e insuficiência renal. Nesse caso, o\ndiagnóstico é","options":{"A":"síndrome hemolítica urêmica.","B":"glomerulonefrite pós-estreptocócica.","C":"refluxo vesicoureteral.","D":"síndrome nefrótica.","E":"pielonefrite aguda."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-365638","number":"365638","sourceNumber":"365638","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A síndrome da morte súbita do lactente (SMSL) foi originalmente definida em 1969 e\nreferia-se à morte súbita de lactentes sem uma causa identificada. Atualmente, está contida em um\ndiagnóstico mais amplo denominado morte súbita infantil inesperada, termo usado para descrever\nqualquer morte súbita e inesperada que ocorra durante o primeiro ano de vida, seja explicada ou\nnão. Assinale a alternativa que indica um fator de risco para a ocorrência da SMSL.","options":{"A":"Dormir em posição supina (\"\"barriga para cima\"\").","B":"Recém-nascido grande para a idade gestacional (GIG).","C":"Uso de chupetas para dormir.","D":"Tabagismo materno na gestação."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-349727","number":"349727","sourceNumber":"349727","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de seis meses apresenta sintomas que incluem tosse, chiado, dificuldade\npara respirar e taquipneia, sem cianose.\nConsiderando que a bronquiolite é a principal causa de\ninsuficiência respiratória aguda em crianças menores de 5 anos, especialmente nos meses de\ninverno, em que consiste o tratamento a ser prescrito nesse caso?","options":{"A":"Uso de antibióticos por via venosa.","B":"Oxigenoterapia, hidratação e medidas de suporte.","C":"Iniciar com antiviral via oral e aguardar a evolução.","D":"Intubação traqueal imediata.","E":"Aspiração de vias aéreas superiores e lavagem nasal."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-365609","number":"365609","sourceNumber":"365609","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 4 anos de idade foi levada à emergência por quadro de náusea, vômito\ne diarreia há quatro dias. Apresentou febre\nbaixa nos dois primeiros dias, evoluindo afebril desde\nentão. Na avaliação inicial, encontrava-se desidratada. Após hidratação venosa, aceitou bem soro\nde reidratação oral (SRO), estava ativa, brincando, com FC, FR e enchimento capilar normais. Com\nbase nas diretrizes do Ministério da Saúde (2023), no momento da alta, além do SRO, está\nindicada prescrição de","options":{"A":"zinco.","B":"probiótico Saccharomyces boulardii.","C":"nitazoxanida.","D":"racecadotrila."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-365579","number":"365579","sourceNumber":"365579","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 8 anos de idade iniciou febre alta e dor de garganta há dois dias. Nega\ncoriza, tosse e espirros. Ao exame físico, observa-se orofaringe hiperemiada, com placa purulenta\nna amígdala esquerda, úvula em posição anatômica. Foi solicitado teste rápido que mostrou\npositividade para S. pyogenes. A mãe refere que a criança fez uso de amoxicilina em três ocasiões\nnos últimos seis meses para infecções de vias aéreas. Nesse caso, a primeira opção de antibiótico\né","options":{"A":"amoxicilina.","B":"macrolídeo.","C":"Amoxicilina + clavulanato.","D":"cefalosporina de segunda geração."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-349692","number":"349692","sourceNumber":"349692","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a atuação do zinco nas diarreias agudas, assinale alternativa correta","options":{"A":"O zinco é um micronutriente essencial para o funcionamento adequado do sistema imunológico,\nporém não deve ser prescrito antes dos doze\nmeses de idade.","B":"Esse íon pode interferir na adesão, na invasão e na produção de toxinas por alguns agentes\npatogênicos causadores de diarreia.","C":"Na diarreia aguda, o zinco pode aumentar a duração, a gravidade e a frequência das\nevacuações.","D":"O mecanismo de ação do zinco na diarreia aguda não envolve a modulação da resposta\ninflamatória.","E":"O zinco aumenta a secreção de água e eletrólitos pelo intestino e a redução da absorção de\nsódio e água pelas células epiteliais."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-349719","number":"349719","sourceNumber":"349719","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma menina de 8 anos é levada pela mãe à Unidade Básica de Saúde, apresentando\nfebre, odinofagia e hiporexia. Ao exame clínico,\nsão constatados exsudato orofaríngeo e\nlinfadenopatia cervical palpável, e a médica responsável pelo atendimento determina que se trata\nde uma amigdalite bacteriana. Considerando o agente mais comum causador da amigdalite\nbacteriana, qual fármaco deve ser prescrito para o tratamento e qual é o principal objetivo do seu\nuso?","options":{"A":"Amoxicilina / O principal objetivo é reduzir o risco de abscesso periamigdaliano.","B":"Amoxicilina / O principal objetivo é reduzir a duração dos sintomas.","C":"Azitromicina / O principal objetivo é evitar a febre reumática.","D":"Amoxicilina / O principal objetivo é evitar a febre reumática.","E":"Azitromicina / O principal objetivo é reduzir o risco de abscesso periamigdaliano."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-322168","number":"322168","sourceNumber":"322168","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança em idade escolar está em antibioticoterapia, há 48 horas, por pneumonia\nbacteriana. Ela é levada ao hospital para reavaliação, pois não teve melhora da curva térmica, está\nprostrada e com perda de apetite. Ao exame físico, apresenta diminuição do murmúrio vesicular em\nbase esquerda e tem bom padrão respiratório, apesar de manter uma posição antálgica em\nescoliose. Qual, entre as seguintes, é a conduta mais indicada no momento?","options":{"A":"Realizar radiografia de tórax.","B":"Trocar antibiótico e reavaliar em 48 a 72 horas.","C":"Manter antibiótico e aguardar completar 72 horas de tratamento para uma reavaliação mais\nadequada.","D":"Realizar tomografia de tórax com contraste.","E":"Associar um segundo antibiótico ao esquema inicial, para cobertura de germes atípicos, e\nreavaliar em 48 horas."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-322177","number":"322177","sourceNumber":"322177","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre otite média aguda (OMA).","options":{"A":"O tabagismo passivo é um fator de risco de reconhecida importância, e o aleitamento materno é\num fator de proteção.","B":"Síndrome de Down é um fator de proteção pelas diferenças de anatomia das vias aéreas\nsuperiores.","C":"As creches e os berçários representam um fator de risco considerável no desenvolvimento da\nOMA.","D":"A ocorrência do primeiro episódio antes dos 6 meses é um fator de risco importante para a\nrecorrência das OMAs.","E":"A tuba auditiva ventila a orelha média, sua luz é virtual, e na criança, é mais curta e mais\nhorizontalizada, o que facilita a progressão de microrganismos da rinofaringe para a orelha média."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-322178","number":"322178","sourceNumber":"322178","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 1 ano é levada para avaliação, por ter apresentado cianose, que\nocorreu após período de choro prolongado, sem\nperda de consciência e com resolução\nespontânea. Após avaliação neurológica detalhada, o quadro é definido como perda de fôlego\ncianótica. Qual é sua postura perante os pais quanto a esse diagnóstico?","options":{"A":"Orienta que o paciente deve fazer uso de medicações anticonvulsivantes.","B":"Esclarece as dúvidas dos pais, enfatizando a alta probabilidade de o paciente ter quadros\nconvulsivos subsequentes.","C":"Conversa sobre desenvolvimento infantil e encaminha a família para centro multidisciplinar, dado\nque o retardo no desenvolvimento\nneurológico faz parte da maioria dos casos.","D":"Tranquiliza os pais, deixando claro que o episódio é benigno e autolimitado.","E":"Explica que o paciente apresenta maior risco de parada cardiorrespiratória."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-322183","number":"322183","sourceNumber":"322183","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um bebê de 6 meses é levado ao hospital por tosse, cansaço para respirar e respiração\nmais \"rápida\". Nega ter tido febre, mas teve,\nlogo antes do quadro atual, coriza leve e um pouco de\nobstrução nasal. Ao exame físico, o paciente apresenta taquipneia, retrações subcostais discretas e\nsibilos difusos à ausculta. Com base no diagnóstico provável de Bronquiolite Viral Aguda (BVA),\ninforme se é Verdadeiro (V) ou Falso (F) o que se afirma a seguir e assinale a alternativa com a\nsequência CORRETA. ( ) A ausência de febre não é compatível com o diagnóstico de BVA. ( ) O\naumento da frequência respiratória é um sinal importante e traduz a resposta do organismo ao\nacometimento pulmonar pelo agente infeccioso, em uma tentativa de compensar os mecanismos\ngeradores de prejuízo na mecânica pulmonar e na troca gasosa. ( ) Crepitações inspiratórias\ndisseminadas por todos os campos pulmonares não ocorrem na BVA e, se presentes, indicam\ndiagnóstico alternativo. ( ) A radiografia de tórax pode ser útil nos casos graves, e os principais\nachados são hiperinsuflação torácica difusa, hipertransparência, retificação do diafragma e até\nbroncograma aéreo com um infiltrado de padrão intersticial. ( ) Na grande maioria dos pacientes, a\nevolução é benigna, e o processo evolui para a cura sem a necessidade de intervenção.","options":{"A":"F - V - V - V - V.","B":"V - V - V - F - V.","C":"F - F - F - F - F.","D":"F - V - F - V - V.","E":"V - F - V - V - F."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337549","number":"337549","sourceNumber":"337549","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 4 anos é atendido no ambulatório com queixa de diarreia há seis meses.\nApresenta de 4 a 6 evacuações por dia,\nfezes que variam de aquosas para semilíquidas com algum\nconteúdo de muco e, às vezes, restos alimentares. O paciente não apresenta outros sintomas\nassociados e tem boa aceitação alimentar. Chegou a ser tratado como verminose, mas o\nparasitológico de fezes foi negativo. Há três meses, a mãe foi orientada a trocar o leite para o sem\nlactose, mas não houve mudanças. A criança está com peso, estatura e velocidade de crescimento\nadequados para a idade e exame físico normal. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. Presença de restos alimentares nas\nevacuações é uma característica comum na diarreia funcional e dá uma falsa impressão de\ndeficiência absortiva.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337551","number":"337551","sourceNumber":"337551","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 4 anos é atendido no ambulatório com queixa de diarreia há seis meses.\nApresenta de 4 a 6 evacuações por dia,\nfezes que variam de aquosas para semilíquidas com algum\nconteúdo de muco e, às vezes, restos alimentares. O paciente não apresenta outros sintomas\nassociados e tem boa aceitação alimentar. Chegou a ser tratado como verminose, mas o\nparasitológico de fezes foi negativo. Há três meses, a mãe foi orientada a trocar o leite para o sem\nlactose, mas não houve mudanças. A criança está com peso, estatura e velocidade de crescimento\nadequados para a idade e exame físico normal. Em relação ao caso clínico descrito e aos\nconhecimentos médicos relacionados, julgue o item a seguir. Na diarreia crônica de caráter\nfuncional, deve-se retirar toda a gordura da dieta e deve-se estimular o consumo de sucos ricos em\nsorbitol.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337559","number":"337559","sourceNumber":"337559","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 1 mês e 15 dias é levado à emergência com quadro de febre, coriza e\ntosse há cinco dias. Hoje, apresentou cianose e desconforto respiratório. Está com frequência\nrespiratória de 70 irpm, saturação arterial de oxigênio de 90% em ar ambiente, tiragem intercostal e\nsubcostal leve e ausculta pulmonar com estertores bolhosos difusos, com tempo de expiração\nlevemente prolongado, tendo sido iniciado tratamento para pneumonia. Em relação ao caso clínico\ndescrito e aos conhecimentos médicos relacionados, julgue o item a seguir. O vírus influenza é o\nresponsável por mais da metade dos casos de pneumonia viral nos primeiros 2 anos de idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337560","number":"337560","sourceNumber":"337560","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 1 mês e 15 dias é levado à emergência com quadro de febre, coriza e\ntosse há cinco dias. Hoje, apresentou cianose e desconforto respiratório. Está com frequência\nrespiratória de 70 irpm, saturação arterial de oxigênio de 90% em ar ambiente, tiragem intercostal e\nsubcostal leve e ausculta pulmonar com estertores bolhosos difusos, com tempo de expiração\nlevemente prolongado, tendo sido iniciado tratamento para pneumonia. Em relação ao caso clínico\ndescrito e aos conhecimentos médicos relacionados, julgue o item a seguir. Em relação às\npneumonias comunitárias na infância, não há recomendação de realizar raio-x de tórax em crianças\nque estejam bem o suficiente para serem tratadas ambulatorialmente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337561","number":"337561","sourceNumber":"337561","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 1 mês e 15 dias é levado à emergência com quadro de febre, coriza e\ntosse há cinco dias. Hoje, apresentou cianose e desconforto respiratório. Está com frequência\nrespiratória de 70 irpm, saturação arterial de oxigênio de 90% em ar ambiente, tiragem intercostal e\nsubcostal leve e ausculta pulmonar com estertores bolhosos difusos, com tempo de expiração\nlevemente prolongado, tendo sido iniciado tratamento para pneumonia. Em relação ao caso clínico\ndescrito e aos conhecimentos médicos relacionados, julgue o item a seguir. São consideradas\ncomplicações de pneumonias: derrame pleural, pneumotórax, pneumatoceles e abscesso\npulmonar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337562","number":"337562","sourceNumber":"337562","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 1 mês e 15 dias é levado à emergência com quadro de febre, coriza e\ntosse há cinco dias. Hoje, apresentou cianose e desconforto respiratório. Está com frequência\nrespiratória de 70 irpm, saturação arterial de oxigênio de 90% em ar ambiente, tiragem intercostal e\nsubcostal leve e ausculta pulmonar com estertores bolhosos difusos, com tempo de expiração\nlevemente prolongado, tendo sido iniciado tratamento para pneumonia. Em relação ao caso clínico\ndescrito e aos conhecimentos médicos relacionados, julgue o item a seguir. Derrames\nparapneumônicos são coleções pleurais associadas, principalmente, às pneumonias agudas, sendo\nsempre transudatos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337563","number":"337563","sourceNumber":"337563","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 1 mês e 15 dias é levado à emergência com quadro de febre, coriza e\ntosse há cinco dias. Hoje, apresentou cianose e desconforto respiratório. Está com frequência\nrespiratória de 70 irpm, saturação arterial de oxigênio de 90% em ar ambiente, tiragem intercostal e\nsubcostal leve e ausculta pulmonar com estertores bolhosos difusos, com tempo de expiração\nlevemente prolongado, tendo sido iniciado tratamento para pneumonia. Em relação ao caso clínico\ndescrito e aos conhecimentos médicos relacionados, julgue o item a seguir. A pneumonia\nnecrosante é uma complicação leve das pneumonias adquiridas na comunidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337564","number":"337564","sourceNumber":"337564","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 1 mês e 15 dias é levado à emergência com quadro de febre, coriza e\ntosse há cinco dias. Hoje, apresentou cianose e desconforto respiratório. Está com frequência\nrespiratória de 70 irpm, saturação arterial de oxigênio de 90% em ar ambiente, tiragem intercostal e\nsubcostal leve e ausculta pulmonar com estertores bolhosos difusos, com tempo de expiração\nlevemente prolongado, tendo sido iniciado tratamento para pneumonia. Em relação ao caso clínico\ndescrito e aos conhecimentos médicos relacionados, julgue o item a seguir. Quando há suspeita de\npneumonite afebril do lactente, deve-se prescrever um antibiótico macrolídio.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-305317","number":"305317","sourceNumber":"305317","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A fisiopatologia da fibrose cística está diretamente relacionada à proteína CFTR (Cystic\nFibrosis Transmembrane Regulator). Sobre o assunto, é correto afirmar que","options":{"A":"é uma doença poligênica autossômica dominante com penetração variável.","B":"é decorrente da ausência e/ou do defeito qualitativo e/ou quantitativo da proteína CFTR.","C":"o acometimento da CFTR, nos pulmões, causa alterações no líquido da superfície das vias\naéreas, com retenção de sódio e água no interstício e hiperidratação das camadas gel e sol das\nvias aéreas.","D":"A proteína CFTR funciona, principalmente, na regulação da permeabilidade do sódio e do\npotássio em células epiteliais.","E":"a reologia do muco das vias aéreas é alterada por impactação das secreções por aumento de\nprodução, a despeito da função ciliar que é, via de regra, normal."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-305320","number":"305320","sourceNumber":"305320","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina de 2 anos é levada à emergência com tosse intensa e ladrante, rouquidão e\nestridor inspiratório discreto. Nos dias\nprecedentes à piora da tosse, tinha rinorreia clara, febre\nbaixa e tosse leve. Não apresenta sinais de desconforto respiratório no momento. Qual, das opções\na seguir, é a conduta mais adequada para essa paciente?","options":{"A":"Iniciar antibioticoterapia com amoxicilina.","B":"Internar para tratamento e observação, por se tratar de quadro moderado com potencial risco de\nprogressão da obstrução.","C":"Solicitar radiografia cervical lateral.","D":"Oxigênio suplementar para conforto.","E":"Prescrever corticosteroide oral ou parenteral."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298890","number":"298890","sourceNumber":"298890","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma paciente de 4 anos de idade foi levada pela mãe ao pronto atendimento e relatou\nque a filha refere intensa dor abdominal e\nestá há sete dias sem evacuar. A filha começou a\ndemonstrar dificuldades para evacuar logo que iniciou a introdução alimentar e, desde então,\napresenta fezes em \"bolinhas\". Em relação à dieta, disse que a menina come frutas, porém em\npouca variedade, gosta muito de banana e de maçã, não gosta de verduras e ingere pouca\nquantidade de água. Ao exame físico, verificaram-se FC = 100 bpm, FR = 22 irpm, SatO2 = 98%\nem AA, bem como abdome globoso com ruídos hidroaéreos positivos, dor difusa à palpação e, em\nquadrante inferior esquerdo, palpa-se massa (sugestivo de fezes). Considerando esse caso clínico\ne com base nos conhecimentos médicos correlatos, julgue o item a seguir. Sempre que uma\ncriança relatar dor abdominal, é importante questionar a respeito dos hábitos intestinais, da\nconsistência das fezes e do número de evacuações (dia/semana). A constipação funcional é um\ndiagnóstico clínico feito de acordo com os critérios de Roma IV.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-305322","number":"305322","sourceNumber":"305322","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 8 anos é levado para primeira consulta. Ele morava em outra cidade e\nera acompanhado pelo seu pediatra por quadro de síndrome do intestino irritável. Ao revisar sua\nsintomatologia, suspeita-se de que o paciente pode, na verdade, ter patologia orgânica, e não\nfuncional. Qual dos seguintes sintomas levanta essa suspeita?","options":{"A":"A dor abdominal é desencadeada pela ingesta de determinados alimentos.","B":"A dor abdominal melhora com a evacuação.","C":"A dor abdominal tem início associado com mudança da frequência das evacuações.","D":"A dor abdominal tem início associado com mudança na aparência das fezes.","E":"Presença de muco nas fezes."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298891","number":"298891","sourceNumber":"298891","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma paciente de 4 anos de idade foi levada pela mãe ao pronto atendimento e relatou\nque a filha refere intensa dor abdominal e\nestá há sete dias sem evacuar. A filha começou a\ndemonstrar dificuldades para evacuar logo que iniciou a introdução alimentar e, desde então,\napresenta fezes em \"bolinhas\". Em relação à dieta, disse que a menina come frutas, porém em\npouca variedade, gosta muito de banana e de maçã, não gosta de verduras e ingere pouca\nquantidade de água. Ao exame físico, verificaram-se FC = 100 bpm, FR = 22 irpm, SatO2 = 98%\nem AA, bem como abdome globoso com ruídos hidroaéreos positivos, dor difusa à palpação e, em\nquadrante inferior esquerdo, palpa-se massa (sugestivo de fezes). Considerando esse caso clínico\ne com base nos conhecimentos médicos correlatos, julgue o item a seguir. Na investigação de\nconstipação, é importante solicitar exames como TSH e T4 livre, a fim de descartar hipotireoidismo,\nque tem, entre as suas manifestações, a constipação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-305324","number":"305324","sourceNumber":"305324","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Você está atendendo, na emergência, um paciente de 2 anos. A queixa é de tosse, dor\nabdominal e febre. A febre iniciou há 36 horas, cessa com antitérmicos, mas volta após 4 a 6 horas,\ncom pico máximo de 38,5ºC. O paciente teve 4 episódios de vômitos, está inapetente, mas\naceitando bem líquidos via oral. Ao exame físico, tem alguns estertores em bases pulmonares,\ntiragem subcostal e taquipneia. Após o diagnóstico de pneumonia, é indicada a internação\nhospitalar. Qual dos dados clínicos do paciente indica a internação?","options":{"A":"A curva térmica.","B":"A tiragem subcostal.","C":"A presença de dor abdominal.","D":"A inapetência e os vômitos.","E":"A presença dos estertores em bases pulmonares."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298900","number":"298900","sourceNumber":"298900","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 9 meses de idade foi levado à emergência por seus pais, os quais\nrelataram que, há uma semana, o filho iniciou\ncom quadro de coriza nasal e tosse. Porém, na última\nnoite, iniciou com febre de 38°C e parecia estar cansado, com a respiração ofegante; inclusive, não\nestá conseguindo mamar. Faz acompanhamento com pediatra e tem todas as vacinas em dia. O\npaciente tem um irmão de 6 anos de idade, que é asmático, e o pai também tem asma. Ao exame\nfísico, verificaram-se FC = 150 bpm, FR = 80 irpm, SatO? = 89% em AA e temperatura = 36,5 °C.\nObservaram-se oroscopia sem petéquias, sem placas, sem lesões e otoscopia, com membrana\ntimpânica translúcida, sem abaulamento, sem secreção. Ausculta cardíaca BNF, RR, 2t, sem sopro,\ne ausculta pulmonar MVUD, com sibilos difusos bilateralmente, apresentando tiragem sub e\nintercostal. Constatou-se também abdome RHA+, depressível, sem megalias, sem fáscies de dor à\npalpação. A respeito desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. Trata-se de um caso de asma, com necessidade de iniciar o tratamento com\nbeta 2 de curta duração.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298902","number":"298902","sourceNumber":"298902","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 9 meses de idade foi levado à emergência por seus pais, os quais\nrelataram que, há uma semana, o filho iniciou\ncom quadro de coriza nasal e tosse. Porém, na última\nnoite, iniciou com febre de 38°C e parecia estar cansado, com a respiração ofegante; inclusive, não\nestá conseguindo mamar. Faz acompanhamento com pediatra e tem todas as vacinas em dia. O\npaciente tem um irmão de 6 anos de idade, que é asmático, e o pai também tem asma. Ao exame\nfísico, verificaram-se FC = 150 bpm, FR = 80 irpm, SatO? = 89% em AA e temperatura = 36,5 °C.\nObservaram-se oroscopia sem petéquias, sem placas, sem lesões e otoscopia, com membrana\ntimpânica translúcida, sem abaulamento, sem secreção. Ausculta cardíaca BNF, RR, 2t, sem sopro,\ne ausculta pulmonar MVUD, com sibilos difusos bilateralmente, apresentando tiragem sub e\nintercostal. Constatou-se também abdome RHA+, depressível, sem megalias, sem fáscies de dor à\npalpação. A respeito desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. Esse é um caso de bronquiolite, e o principal agente é o vírus sincicial\nrespiratório.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298903","number":"298903","sourceNumber":"298903","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 9 meses de idade foi levado à emergência por seus pais, os quais\nrelataram que, há uma semana, o filho iniciou\ncom quadro de coriza nasal e tosse. Porém, na última\nnoite, iniciou com febre de 38°C e parecia estar cansado, com a respiração ofegante; inclusive, não\nestá conseguindo mamar. Faz acompanhamento com pediatra e tem todas as vacinas em dia. O\npaciente tem um irmão de 6 anos de idade, que é asmático, e o pai também tem asma. Ao exame\nfísico, verificaram-se FC = 150 bpm, FR = 80 irpm, SatO? = 89% em AA e temperatura = 36,5 °C.\nObservaram-se oroscopia sem petéquias, sem placas, sem lesões e otoscopia, com membrana\ntimpânica translúcida, sem abaulamento, sem secreção. Ausculta cardíaca BNF, RR, 2t, sem sopro,\ne ausculta pulmonar MVUD, com sibilos difusos bilateralmente, apresentando tiragem sub e\nintercostal. Constatou-se também abdome RHA+, depressível, sem megalias, sem fáscies de dor à\npalpação. A respeito desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. No tratamento da bronquiolite, deve-se prescrever prednisolona na dose de\n1 mg/kg/dia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298905","number":"298905","sourceNumber":"298905","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 9 meses de idade foi levado à emergência por seus pais, os quais\nrelataram que, há uma semana, o filho iniciou\ncom quadro de coriza nasal e tosse. Porém, na última\nnoite, iniciou com febre de 38°C e parecia estar cansado, com a respiração ofegante; inclusive, não\nestá conseguindo mamar. Faz acompanhamento com pediatra e tem todas as vacinas em dia. O\npaciente tem um irmão de 6 anos de idade, que é asmático, e o pai também tem asma. Ao exame\nfísico, verificaram-se FC = 150 bpm, FR = 80 irpm, SatO? = 89% em AA e temperatura = 36,5 °C.\nObservaram-se oroscopia sem petéquias, sem placas, sem lesões e otoscopia, com membrana\ntimpânica translúcida, sem abaulamento, sem secreção. Ausculta cardíaca BNF, RR, 2t, sem sopro,\ne ausculta pulmonar MVUD, com sibilos difusos bilateralmente, apresentando tiragem sub e\nintercostal. Constatou-se também abdome RHA+, depressível, sem megalias, sem fáscies de dor à\npalpação. A respeito desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\njulgue o item a seguir. A investigação de cansaço/dispneia é uma causa frequente de\nencaminhamento ao cardiologista.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-298930","number":"298930","sourceNumber":"298930","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um bebê de 6 meses de vida foi levado pela mãe à equipe de Saúde da Família (eSF)\npara consulta de rotina de puericultura. A mãe\nrelata que está preocupada, pois a criança\n\nmostra-se mais chorosa, apresentando irritabilidade, dificuldade para dormir e pico febril de 39ºC\nna\nnoite anterior. A criança está previamente hígida, em aleitamento materno exclusivo, fez uso de\nparacetamol há duas horas e sua temperatura é de 37,5ºC no momento. A mãe nega que a criança\ntenha alergias medicamentosas. Ao exame físico, verificam-se auscultas pulmonar e cardíaca sem\nalterações, abdome sem particularidades, otoscopia direita com presença de membrana timpânica\nabaulada e hiperemiada, sem presença de otorreia. A criança é capaz de firmar a cabeça e\napanhar objetos, e as medidas antropométricas estão próximas ao percentil 50. Carteira de\nvacinação atualizada. Com base nesse caso clínico e nos conhecimentos médicos correlatos,\njulgue o item a seguir. Trata-se de um caso de Otite Média Aguda (OMA). O tratamento deve ser\nfeito com analgésicos, antipiréticos e, se a criança for candidata ao uso de antimicrobianos, a\namoxicilina será o antibiótico de escolha.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-274376","number":"274376","sourceNumber":"274376","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre as rinites, é correto afirmar que","options":{"A":"a forma intermitente se caracteriza por sintomas presentes em menos de 1 dia por semana.","B":"a forma persistente se caracteriza por sintomas diários, sem prejuízo das atividades diárias.","C":"a doença não faz alteração do sono e, quando isso ocorre, deve-se buscar diagnósticos\ndiferenciais.","D":"o diagnóstico é feito na concordância entre história típica de sintomas e exames\ncomplementares que comprovem a participação da IgA no processo.","E":"o tratamento de escolha para a forma intermitente moderada/grave e todas as formas\npersistentes é com corticosteroides intranasais."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-274386","number":"274386","sourceNumber":"274386","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma das opções terapêuticas para obstrução respiratória por crupe viral é o uso de\nepinefrina inalatória. Assinale a alternativa CORRETA sobre seu uso.","options":{"A":"Seu mecanismo de ação é por meio de estímulo aos receptores dopaminérgicos, com\nconsequente dilatação de capilares arteriolares.","B":"Diminui os sintomas de falência respiratória e o estridor após 1 a 2 horas de seu uso.","C":"Como o efeito da medicação é breve, o paciente pode voltar ao estado de desconforto\nrespiratório inicial após o final da ação dessa droga.","D":"As indicações incluem crupe leve, moderado ou grave, o mais precocemente possível.","E":"O uso de nebulização com solução fisiológica tem eficácia comprovada, devendo ser usada em\npacientes com quadro leve a moderado, mesmo que haja agitação e choro pela sua utilização."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-274388","number":"274388","sourceNumber":"274388","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Qual é a principal causa de desidratação aguda no nosso meio?","options":{"A":"Baixa ingesta hídrica.","B":"Diabete tipo 1.","C":"Diarreia aguda.","D":"Parasitoses.","E":"Síndromes inflamatórias intestinais."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-274396","number":"274396","sourceNumber":"274396","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Considerando as medidas terapêuticas da constipação intestinal funcional, assinale a\nalternativa INCORRETA.","options":{"A":"Educação e orientação sobre a necessidade de atender o desejo de evacuar, evitando atitudes\nprotelatórias, aproveitando o reflexo gastrocólico e tentando evacuar uma vez ao dia, após uma das\nrefeições principais.","B":"Para a manutenção, quando indicada, deve ser utilizado um laxante por via oral, diariamente, na\ndose individualizada para obter regularização do\nhábito intestinal. Para lactentes, uma opção\nsegura é o óleo mineral.","C":"Incontinência fecal por retenção, massa fecal palpável e reto preenchido com fezes são\nmanifestações clínicas indicativas de\nimpactação fecal. Nesses casos, o esvaziamento constitui a\nprimeira e imprescindível etapa.","D":"A desimpactação pode ser realizada com enemas por via retal ou por via oral, e são\nnecessários, em geral, 3 a 5 dias para se obter plena desimpactação.","E":"Em geral, os enemas são realizados com solução fosfatada a partir dos 2 anos de idade. Em\nlactentes, podem ser usados minienemas com sorbitol. No ambiente hospitalar, a solução de\nglicerina constitui uma alternativa para o enema fosfatado."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261264","number":"261264","sourceNumber":"261264","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 12 anos de idade foi encaminhado a consulta por apresentar febre há\ndois dias, recebendo tratamento com amoxicilina para infecção na garganta, conforme relatou um\nfamiliar. Após 96 horas do uso do medicamento, o paciente evoluiu com exantema maculopapular,\npruriginoso e dor abdominal de forte intensidade. Manifesta adenomegalias occiptais bilaterais,\npequenas, fibroelásticas e móveis. Auscultas cardíaca e respiratória sem alterações. Ao exame\nfísico abdominal, verifica-se hepatoesplenomegalia. Constatam-se FC = 85 bpm; FR = 17 irpm; e\nSatO2 = 98%. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Alguns tipos de linfomas podem ter\nassociação com o agente etiológico causador dessa comorbidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261265","number":"261265","sourceNumber":"261265","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 12 anos de idade foi encaminhado a consulta por apresentar febre há\ndois dias, recebendo tratamento com amoxicilina para infecção na garganta, conforme relatou um\nfamiliar. Após 96 horas do uso do medicamento, o paciente evoluiu com exantema maculopapular,\npruriginoso e dor abdominal de forte intensidade. Manifesta adenomegalias occiptais bilaterais,\npequenas, fibroelásticas e móveis. Auscultas cardíaca e respiratória sem alterações. Ao exame\nfísico abdominal, verifica-se hepatoesplenomegalia. Constatam-se FC = 85 bpm; FR = 17 irpm; e\nSatO2 = 98%. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Hepatomegalia não faz parte da\napresentação típica da doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261266","number":"261266","sourceNumber":"261266","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 12 anos de idade foi encaminhado a consulta por apresentar febre há\ndois dias, recebendo tratamento com amoxicilina para infecção na garganta, conforme relatou um\nfamiliar. Após 96 horas do uso do medicamento, o paciente evoluiu com exantema maculopapular,\npruriginoso e dor abdominal de forte intensidade. Manifesta adenomegalias occiptais bilaterais,\npequenas, fibroelásticas e móveis. Auscultas cardíaca e respiratória sem alterações. Ao exame\nfísico abdominal, verifica-se hepatoesplenomegalia. Constatam-se FC = 85 bpm; FR = 17 irpm; e\nSatO2 = 98%. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Indica-se manter o uso do antibiótico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261267","number":"261267","sourceNumber":"261267","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 12 anos de idade foi encaminhado a consulta por apresentar febre há\ndois dias, recebendo tratamento com amoxicilina para infecção na garganta, conforme relatou um\nfamiliar. Após 96 horas do uso do medicamento, o paciente evoluiu com exantema maculopapular,\npruriginoso e dor abdominal de forte intensidade. Manifesta adenomegalias occiptais bilaterais,\npequenas, fibroelásticas e móveis. Auscultas cardíaca e respiratória sem alterações. Ao exame\nfísico abdominal, verifica-se hepatoesplenomegalia. Constatam-se FC = 85 bpm; FR = 17 irpm; e\nSatO2 = 98%. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Deve-se vigiar o sensório do paciente,\npois a doença pode ter complicações neurológicas, como encefalite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261268","number":"261268","sourceNumber":"261268","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 12 anos de idade foi encaminhado a consulta por apresentar febre há\ndois dias, recebendo tratamento com amoxicilina para infecção na garganta, conforme relatou um\nfamiliar. Após 96 horas do uso do medicamento, o paciente evoluiu com exantema maculopapular,\npruriginoso e dor abdominal de forte intensidade. Manifesta adenomegalias occipitais bilaterais,\npequenas, fibroelásticas e móveis. Auscultas cardíaca e respiratória sem alterações. Ao exame\nfísico abdominal, verifica-se hepatoesplenomegalia. Constatam-se FC = 85 bpm; FR = 17 irpm; e\nSatO2 = 98%. Descartou-se infecção por coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Para evitar possíveis traumas, indica-se\nrepouso.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261269","number":"261269","sourceNumber":"261269","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 12 anos de idade foi encaminhado a consulta por apresentar febre há\ndois dias, recebendo tratamento com amoxicilina para infecção na garganta, conforme relatou um\nfamiliar. Após 96 horas do uso do medicamento, o paciente evoluiu com exantema maculopapular,\npruriginoso e dor abdominal de forte intensidade. Manifesta adenomegalias occiptais bilaterais,\npequenas, fibroelásticas e móveis. Auscultas cardíaca e respiratória sem alterações. Ao exame\nfísico abdominal, verifica-se hepatoesplenomegalia. Constatam-se FC = 85 bpm; FR = 17 irpm; e\nSatO2 = 98%. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Ainda que a ausculta cardíaca esteja\ninicialmente normal, o paciente pode apresentar miocardite como complicação cardiovascular da\ndoença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261270","number":"261270","sourceNumber":"261270","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 6 meses de vida é encaminhado ao atendimento médico por apresentar\ncoriza hialina e tosse, com três dias de\nevolução, piorando nas últimas 24 horas. Na chegada,\nencontra-se afebril, letárgico, com importantes retrações intercostais e subcostais e sibilos na\nausculta pulmonar, sem outros ruídos adventícios. Constatam-se FC = 120 bpm; FR = 75 irpm; e\nSatO2 = 85% em ar ambiente. A radiografia torácica mostra-se normal. É o primeiro episódio de\nsibilância do paciente. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. O diagnóstico da patologia é realizado\npor meio de espirometria.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261271","number":"261271","sourceNumber":"261271","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 6 meses de vida é encaminhado ao atendimento médico por apresentar\ncoriza hialina e tosse, com três dias de\nevolução, piorando nas últimas 24 horas. Na chegada,\nencontra-se afebril, letárgico, com importantes retrações intercostais e subcostais e sibilos na\nausculta pulmonar, sem outros ruídos adventícios. Constatam-se FC = 120 bpm; FR = 75 irpm; e\nSatO2 = 85% em ar ambiente. A radiografia torácica mostra-se normal. É o primeiro episódio de\nsibilância do paciente. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Diante do exposto, considera-se a\nhipótese diagnóstica de bronquiolite viral aguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261272","number":"261272","sourceNumber":"261272","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 6 meses de vida é encaminhado ao atendimento médico por apresentar\ncoriza hialina e tosse, com três dias de\nevolução, piorando nas últimas 24 horas. Na chegada,\nencontra-se afebril, letárgico, com importantes retrações intercostais e subcostais e sibilos na\nausculta pulmonar, sem outros ruídos adventícios. Constatam-se FC = 120 bpm; FR = 75 irpm; e\nSatO2 = 85% em ar ambiente. A radiografia torácica mostra-se normal. É o primeiro episódio de\nsibilância do paciente. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. A transmissão do agente etiológico\nocorre por contato direto ou próximo de secreções contaminadas geralmente de um membro da\nfamília ou de outra criança de convívio próximo, como em creche, que apresente sintomatologia\nrespiratória.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261273","number":"261273","sourceNumber":"261273","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 6 meses de vida é encaminhado ao atendimento médico por apresentar\ncoriza hialina e tosse, com três dias de\nevolução, piorando nas últimas 24 horas. Na chegada,\nencontra-se afebril, letárgico, com importantes retrações intercostais e subcostais e sibilos na\nausculta pulmonar, sem outros ruídos adventícios. Constatam-se FC = 120 bpm; FR = 75 irpm; e\nSatO2 = 85% em ar ambiente. A radiografia torácica mostra-se normal. É o primeiro episódio de\nsibilância do paciente. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. Manter o aporte hídrico adequado é\nfundamental ao tratamento, estabelecendo-se controle da diurese como critério de avaliação da\nhidratação do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261274","number":"261274","sourceNumber":"261274","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 6 meses de vida é encaminhado ao atendimento médico por apresentar\ncoriza hialina e tosse, com três dias de\nevolução, piorando nas últimas 24 horas. Na chegada,\nencontra-se afebril, letárgico, com importantes retrações intercostais e subcostais e sibilos na\nausculta pulmonar, sem outros ruídos adventícios. Constatam-se FC = 120 bpm; FR = 75 irpm; e\nSatO2 = 85% em ar ambiente. A radiografia torácica mostra-se normal. É o primeiro episódio de\nsibilância do paciente. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. A ausência de febre não exclui o\ndiagnóstico dessa comorbidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-261275","number":"261275","sourceNumber":"261275","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 6 meses de vida é encaminhado ao atendimento médico por apresentar\ncoriza hialina e tosse, com três dias de\nevolução, piorando nas últimas 24 horas. Na chegada,\nencontra-se afebril, letárgico, com importantes retrações intercostais e subcostais e sibilos na\nausculta pulmonar, sem outros ruídos adventícios. Constatam-se FC = 120 bpm; FR = 75 irpm; e\nSatO2 = 85% em ar ambiente. A radiografia torácica mostra-se normal. É o primeiro episódio de\nsibilância do paciente. Descartou-se infecção por Coronavírus. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. No caso descrito, o quadro respiratório é\nconsiderado grave.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-250108","number":"250108","sourceNumber":"250108","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Julgue o item a seguir quanto à conduta nas diarreias na infância. Na diarreia aguda, a\nalimentação deve ser mantida, desde que seja com fórmulas sem lactose ou preparação láctea\ndiluída.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-250109","number":"250109","sourceNumber":"250109","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Julgue o item a seguir quanto à conduta nas diarreias na infância. O zinco deve ser\niniciado a partir do momento da caracterização da diarreia, de dez a catorze dias, para reduzir sua\nduração e diminuir a probabilidade de a diarreia persistir por mais de sete dias e de ocorrerem\nnovos episódios nos três meses subsequentes.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-250110","number":"250110","sourceNumber":"250110","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Julgue o item a seguir quanto à conduta nas diarreias na infância. Antibióticos são\nrecomendados estritamente para pacientes com diarreia que necessitem de terapia de hidratação\nparenteral ou que evoluam com quadro de suspeita de sepse.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-250111","number":"250111","sourceNumber":"250111","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Julgue o item a seguir quanto à conduta nas diarreias na infância. A racecadotrila é um\ninibidor da encefalinase, enzima responsável pela degradação das encefalinas produzidas pelo\nsistema nervoso entérico, que pode ser utilizado como coadjuvante no tratamento da diarreia aguda\npor reduzir as perdas diarreicas e diminuir sua duração.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-250116","number":"250116","sourceNumber":"250116","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Acerca das patologias na infância, julgue o item a seguir. Suponha-se que uma criança\ncom três anos de idade tenha diagnóstico de\nrinite de repetição, episódios de sibilância sem\nresfriado (virose), último hemograma que revelou eosinofilia e antecedente familiar de asma. Nesse\ncaso, há grande probabilidade de que a sibilância persista na vida adulta.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-239298","number":"239298","sourceNumber":"239298","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 5 anos de idade é levado ao pronto atendimento com queixas de\nodinofagia e febre não aferida de início\nhá três dias. Ao exame físico, constatou-se FC = 101 bpm,\nFR = 18 irpm, saturação de oxigênio = 100%, ausculta pulmonar normal, otoscopia normal\nbilateralmente, oroscopia com presença de exsudato amigdaliano branco-amarelo. O pediatra de\nplantão realiza o diagnóstico de amigdalite bacteriana. Quanto ao caso clínico apresentado e tendo\nem vista os conhecimentos médicos correlatos, julgue o item a seguir. A ausência do exsudato\namigdaliano excluiria definitivamente esse diagnóstico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-239299","number":"239299","sourceNumber":"239299","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 5 anos de idade é levado ao pronto atendimento com queixas de\nodinofagia e febre não aferida de início\nhá três dias. Ao exame físico, constatou-se FC = 101 bpm,\nFR = 18 irpm, saturação de oxigênio = 100%, ausculta pulmonar normal, otoscopia normal\nbilateralmente, oroscopia com presença de exsudato amigdaliano branco-amarelo. O pediatra de\nplantão realiza o diagnóstico de amigdalite bacteriana. Quanto ao caso clínico apresentado e tendo\nem vista os conhecimentos médicos correlatos, julgue o item a seguir. A identificação de\nestreptococo beta-hemolítico, em teste rápido de amostra de orofaringe, confirmaria o diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-239300","number":"239300","sourceNumber":"239300","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 5 anos de idade é levado ao pronto atendimento com queixas de\nodinofagia e febre não aferida de início\nhá três dias. Ao exame físico, constatou-se FC = 101 bpm,\nFR = 18 irpm, saturação de oxigênio = 100%, ausculta pulmonar normal, otoscopia normal\nbilateralmente, oroscopia com presença de exsudato amigdaliano branco-amarelo. O pediatra de\nplantão realiza o diagnóstico de amigdalite bacteriana. Quanto ao caso clínico apresentado e tendo\nem vista os conhecimentos médicos correlatos, julgue o item a seguir. O início imediato do\ntratamento é capaz de prevenir a glomerulonefrite pós-estreptocócica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-239301","number":"239301","sourceNumber":"239301","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 5 anos de idade é levado ao pronto atendimento com queixas de\nodinofagia e febre não aferida de início\nhá três dias. Ao exame físico, constatou-se FC = 101 bpm,\nFR = 18 irpm, saturação de oxigênio = 100%, ausculta pulmonar normal, otoscopia normal\nbilateralmente, oroscopia com presença de exsudato amigdaliano branco-amarelo. O pediatra de\nplantão realiza o diagnóstico de amigdalite bacteriana. Quanto ao caso clínico apresentado e tendo\nem vista os conhecimentos médicos correlatos, julgue o item a seguir. A penicilina G benzatina, em\ndose única, é um tratamento aceitável.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-239302","number":"239302","sourceNumber":"239302","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 5 anos de idade é levado ao pronto atendimento com queixas de\nodinofagia e febre não aferida de início há\ntrês dias. Ao exame físico, constatou-se FC = 101 bpm,\nFR = 18 irpm, saturação de oxigênio = 100%, ausculta pulmonar normal, otoscopia normal\nbilateralmente, oroscopia com presença de exsudato amigdaliano branco-amarelo. O pediatra de\nplantão realiza o diagnóstico de amigdalite bacteriana. Quanto ao caso clínico apresentado e tendo\nem vista os conhecimentos médicos correlatos, julgue o item a seguir. A presença de dor abdominal\ne vômitos contrariaria fortemente o diagnóstico firmado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-255721","number":"255721","sourceNumber":"255721","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 11 anos de idade apresenta linfonodomegalia cervical, dor de garganta,\nfebre, esplenomegalia e perda de peso. O médico\nentão solicita exames que demonstram\nlinfocitose linfócitos atípicos. Com base nesse caso e nos conhecimentos médicos correlatos, julgue\no item a seguir. Corticoide pode ser administrado, dependendo da intensidade dos sintomas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-212011","number":"212011","sourceNumber":"212011","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 5 meses de vida iniciou febre alta, tosse seca e dificuldade respiratória\nhá dois dias, sendo atendido na emergência. A\nmãe refere que o quadro atual foi precedido por\nsintomas gripais por três dias. História pregressa e gestacional: nascido a termo sem\nintercorrências, com peso = 3,5 kg e E = 50 cm, porém vem apresentando impetigo de repetição.\nAo exame físico: paciente irritado, desnutrido e hipocorado (2+/4+), com lesões bolhosas\npurulentas em tronco e pernas. Aparelho respiratório: esforço respiratório intenso, tiragens\nintercostais e subcostal, macicez no terço inferior no hemitórax esquerdo e MV abolido ipsilateral,\nalém de crepitações difusas, FR = 69 irpm e SatO? = 92%. Aparelho cardiovascular: enchimento\ncapilar lentificado, à ausculta, bulhas normofonéticas, sem sopros, e FC = 160 bpm. Abdome:\ntimpânico e sem visceromegalias. TAx = 39°C. Acerca desse caso clínico, assinale a alternativa\nCORRETA.","options":{"A":"Esse é um quadro de bronquiolite viral aguda, cujo tratamento é expectante.","B":"Os sinais e sintomas conduzem à suspeita diagnóstica de miocardite viral aguda.","C":"O teste do pezinho deve ser verificado em razão da suspeita de síndrome torácica aguda da\ndoença falciforme.","D":"O quadro clínico associado ao impetigo bolhoso e à desnutrição leva à suspeita de pneumonia\nestafilocócica grave com derrame pleural.","E":"A laringotraqueobronquite viral é um diagnóstico compatível com esse caso."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-211943","number":"211943","sourceNumber":"211943","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 4 meses de vida foi levado à emergência por apresentar tosse seca e\ncansaço há cinco dias, com dificuldade para\nmamar. A mãe nega febre ou quadro semelhante\nanteriormente. Ao exame físico, a criança estava taquidispneica, corada, afebril e hidratada, além\nde paciente sibilância à ausculta pulmonar e SaO2 = 90%. Quanto a esse caso clínico, assinale a\nalternativa que corresponde ao diagnóstico desse paciente.","options":{"A":"Pneumonia adquirida na comunidade.","B":"Coqueluche.","C":"Bronquiolite viral aguda.","D":"Laringite viral.","E":"Crise de asma."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-212007","number":"212007","sourceNumber":"212007","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 10 meses de vida que iniciou quadro diarreico há um dia, acompanhado\nde vômitos, é levado para consulta, pois está\nmuito desanimado e com recusa alimentar\n(aleitamento materno). A mãe informa que o peso dele era 9,2 kg na consulta há 15 dias. Ao exame\nfísico, está sedento, irritado e com olhos ligeiramente fundos, sinal da prega > 2 segundos, boca\nseca, pouca lágrima e diurese diminuída, além de pesar 8,6 kg. A respeito desses caso clínico,\nassinale a alternativa que indica o diagnóstico e o tratamento apropriado para este paciente.","options":{"A":"Desidratação leve, devendo ser prescrita a terapia de reidratação oral (TRO) de livre demanda\npara ser feita em casa, acrescida de zinco\nvia oral - 10 mg por dia.","B":"Desidratação moderada, estando indicada a TRO, 50-100 ml/kg de peso corporal durante 3-4\nhoras em ambiente hospitalar, acrescida de zinco via oral - 20 mg por dia.","C":"Desidratação grave, sendo necessária a prescrição de hidratação venosa rápida: 100 ml/kg de\nsoro glicosado a 5% em ambiente hospitalar, e repetir até a melhora do quadro.","D":"Quadro diarreico sem desidratação, não havendo a necessidade de TRO, devendo-se aumentar\na ingesta de água e suco e de frutas.","E":"Desidratação aguda, sendo indicada a hidratação venosa rápida com Ringer lactato - 80 ml/kg\nem ambiente hospitalar, de hora em hora, até que o paciente apresente diurese."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-211922","number":"211922","sourceNumber":"211922","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma menina de 1 ano e 9 meses de idade foi levada à emergência pela mãe por\napresentar rosto inchado e avermelhado, além\nde febre alta. Ao exame físico, o plantonista\nobservou febre e intenso edema, hiperemia e calor de região infra e supraocular direita. No que se\nrefere a esse caso clínico, quanto ao diagnóstico e à conduta adequados para essa paciente,\nassinale a alternativa correta.","options":{"A":"Celulite periorbitária; prescrever antibioticoterapia parenteral sob internação.","B":"Erisipela; fazer compressa quente e administrar antitérmico em casa.","C":"Furunculose; prescrever penicilina benzatina e internar.","D":"Abscesso de face; prescrever amoxacilina oral e liberar para casa.","E":"Impetigo crostoso; prescrever mupirocina em pomada e liberar para casa."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-214491","number":"214491","sourceNumber":"214491","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Certo paciente de 12 meses de vida é levado ao pronto atendimento por histórico de\nsete dias de tosse e secreção nasal, com\nfebre que se iniciou há 48 horas. Ao exame físico,\nobservam-se amígdalas hiperemiadas e com secreção exsudativa bilateralmente, além de\nlinfonodomegalia cervical e baço palpável. Ao exame físico, verificam-se FC de 90 bpm, FR de 16\nirpm e saturação de oxigênio de 99%. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatados, julgue o item a seguir. A presença de exsudato amigdaliano exclui o diagnóstico de\ndoença viral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196712","number":"196712","sourceNumber":"196712","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 4 anos de idade, pesando 15 kg, manifestou gastroenterite aguda, com\nevacuações sanguinolentas e purulentas. Não\nurinava há cerca de 10 horas. No momento em que\nchegou ao hospital, encontrava-se em desidratação grave. Evoluiu com convulsão generalizada,\ntônico-clônica, de difícil controle, com duração de 20 minutos. Ao exame físico, estava em mau\nestado geral, pálido, com saturação de oxigênio de 97% em ar ambiente, afebril, com frequência\nrespiratória em 45 irpm e frequência cardíaca em 135 bpm. Estava ictérico, com petéquias em\ntórax, abdome e membros inferiores. Apresentava hepatomegalia. O hemograma mostrou\nleucócitos na faixa da normalidade, sem formas jovens, e revelou anemia, com aumento de\nreticulócitos e eritrócitos fragmentados, e teste de Coombs direto negativo. Apresentou exame de\nurina com hematúria e proteinúria, creatinina sérica elevada e provas de coagulação normais. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir.\n\nConsiderando-se o quadro clínico do paciente, espera-se que as plaquetas estejam baixas ou no\nlimite inferior da normalidade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196707","number":"196707","sourceNumber":"196707","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 4 anos de idade, pesando 15 kg, manifestou gastroenterite aguda, com\nevacuações sanguinolentas e purulentas. Não\nurinava há cerca de 10 horas. No momento em que\nchegou ao hospital, encontrava-se em desidratação grave. Evoluiu com convulsão generalizada,\ntônico-clônica, de difícil controle, com duração de 20 minutos. Ao exame físico, estava em mau\nestado geral, pálido, com saturação de oxigênio de 97% em ar ambiente, afebril, com frequência\nrespiratória em 45 irpm e frequência cardíaca em 135 bpm. Estava ictérico, com petéquias em\ntórax, abdome e membros inferiores. Apresentava hepatomegalia. O hemograma mostrou\nleucócitos na faixa da normalidade, sem formas jovens, e revelou anemia, com aumento de\nreticulócitos e eritrócitos fragmentados, e teste de Coombs direto negativo. Apresentou exame de\nurina com hematúria e proteinúria, creatinina sérica elevada e provas de coagulação normais. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente apresentou quadro convulsivo possivelmente secundário a estado de uremia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196709","number":"196709","sourceNumber":"196709","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 4 anos de idade, pesando 15 kg, manifestou gastroenterite aguda, com\nevacuações sanguinolentas e purulentas. Não\nurinava há cerca de 10 horas. No momento em que\nchegou ao hospital, encontrava-se em desidratação grave. Evoluiu com convulsão generalizada,\ntônico-clônica, de difícil controle, com duração de 20 minutos. Ao exame físico, estava em mau\nestado geral, pálido, com saturação de oxigênio de 97% em ar ambiente, afebril, com frequência\nrespiratória em 45 irpm e frequência cardíaca em 135 bpm. Estava ictérico, com petéquias em\ntórax, abdome e membros inferiores. Apresentava hepatomegalia. O hemograma mostrou\nleucócitos na faixa da normalidade, sem formas jovens, e revelou anemia, com aumento de\nreticulócitos e eritrócitos fragmentados, e teste de Coombs direto negativo. Apresentou exame de\nurina com hematúria e proteinúria, creatinina sérica elevada e provas de coagulação normais. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Pela\napresentação clínica e laboratorial do caso, a biópsia medular está formalmente indicada para\ndescartar neoplasias.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196708","number":"196708","sourceNumber":"196708","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 4 anos de idade, pesando 15 kg, manifestou gastroenterite aguda, com\nevacuações sanguinolentas e purulentas. Não\nurinava há cerca de 10 horas. No momento em que\nchegou ao hospital, encontrava-se em desidratação grave. Evoluiu com convulsão generalizada,\ntônico-clônica, de difícil controle, com duração de 20 minutos. Ao exame físico, estava em mau\nestado geral, pálido, com saturação de oxigênio de 97% em ar ambiente, afebril, com frequência\nrespiratória em 45 irpm e frequência cardíaca em 135 bpm. Estava ictérico, com petéquias em\ntórax, abdome e membros inferiores. Apresentava hepatomegalia. O hemograma mostrou\nleucócitos na faixa da normalidade, sem formas jovens, e revelou anemia, com aumento de\nreticulócitos e eritrócitos fragmentados, e teste de Coombs direto negativo. Apresentou exame de\nurina com hematúria e proteinúria, creatinina sérica elevada e provas de coagulação normais. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Trata-se\nde um caso de gastroenterite aguda, possivelmente de etiologia bacteriana.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196710","number":"196710","sourceNumber":"196710","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 4 anos de idade, pesando 15 kg, manifestou gastroenterite aguda, com\nevacuações sanguinolentas e purulentas. Não\nurinava há cerca de 10 horas. No momento em que\nchegou ao hospital, encontrava-se em desidratação grave. Evoluiu com convulsão generalizada,\ntônico-clônica, de difícil controle, com duração de 20 minutos. Ao exame físico, estava em mau\nestado geral, pálido, com saturação de oxigênio de 97% em ar ambiente, afebril, com frequência\nrespiratória em 45 irpm e frequência cardíaca em 135 bpm. Estava ictérico, com petéquias em\ntórax, abdome e membros inferiores. Apresentava hepatomegalia. O hemograma mostrou\nleucócitos na faixa da normalidade, sem formas jovens, e revelou anemia, com aumento de\nreticulócitos e eritrócitos fragmentados, e teste de Coombs direto negativo. Apresentou exame de\nurina com hematúria e proteinúria, creatinina sérica elevada e provas de coagulação normais. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir.\n\nConsiderando-se a taquipneia, é fundamental descartar pneumonia adquirida na comunidade, uma\nvez que a infecção por Streptococcus\npneumoniae está associada a quadros atípicos dessa\nsíndrome.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196713","number":"196713","sourceNumber":"196713","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 4 anos de idade, pesando 15 kg, manifestou gastroenterite aguda, com\nevacuações sanguinolentas e purulentas. Não\nurinava há cerca de 10 horas. No momento em que\nchegou ao hospital, encontrava-se em desidratação grave. Evoluiu com convulsão generalizada,\ntônico-clônica, de difícil controle, com duração de 20 minutos. Ao exame físico, estava em mau\nestado geral, pálido, com saturação de oxigênio de 97% em ar ambiente, afebril, com frequência\nrespiratória em 45 irpm e frequência cardíaca em 135 bpm. Estava ictérico, com petéquias em\ntórax, abdome e membros inferiores. Apresentava hepatomegalia. O hemograma mostrou\nleucócitos na faixa da normalidade, sem formas jovens, e revelou anemia, com aumento de\nreticulócitos e eritrócitos fragmentados, e teste de Coombs direto negativo. Apresentou exame de\nurina com hematúria e proteinúria, creatinina sérica elevada e provas de coagulação normais. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Para a\nfase rápida inicial da expansão volumétrica no manejo do choque hipovolêmico, sugere-se o uso de\ncoloides ou cristaloides na dose de 100 mL por quilograma de peso corporal, via endovenosa em\ninfusão lenta.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196602","number":"196602","sourceNumber":"196602","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma menina de 10 anos de idade recebeu diagnóstico de pneumonia bacteriana\nadquirida na comunidade, em unidade básica\nde saúde. Foi então iniciado tratamento com\namoxicilina, na dose de 50 mg/kg/dia, mas, após três dias de tratamento, a paciente apresentou\npiora clínica de quadro. Evoluiu com piora da tosse, associada a taquipneia, persistência da febre e\ndor abdominal, principalmente em hipocôndrio e flanco à direita. Com relação a esse caso clínico e\ncom base nos conhecimentos médicos correlatos, julgue o item a seguir. O manejo inicial deve\nincluir a avaliação de um cirurgião pediátrico, para que seja descartado abdome agudo cirúrgico,\nincluindo apendicite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196611","number":"196611","sourceNumber":"196611","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma menina de 10 anos de idade recebeu diagnóstico de pneumonia bacteriana\nadquirida na comunidade, em unidade básica\nde saúde. Foi então iniciado tratamento com\namoxicilina, na dose de 50 mg/kg/dia, mas, após três dias de tratamento, a paciente apresentou\npiora clínica de quadro. Evoluiu com piora da tosse, associada a taquipneia, persistência da febre e\ndor abdominal, principalmente em hipocôndrio e flanco à direita. Com relação a esse caso clínico e\ncom base nos conhecimentos médicos correlatos, julgue o item a seguir. Em razão da idade da\npaciente, deve-se considerar cobertura antimicrobiana para germes atípicos, como o Mycoplasma\npneumoniae.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-196617","number":"196617","sourceNumber":"196617","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma menina de 10 anos de idade recebeu diagnóstico de pneumonia bacteriana\nadquirida na comunidade, em unidade básica\nde saúde. Foi então iniciado tratamento com\namoxicilina, na dose de 50 mg/kg/dia, mas, após três dias de tratamento, a paciente apresentou\npiora clínica de quadro. Evoluiu com piora da tosse, associada a taquipneia, persistência da febre e\ndor abdominal, principalmente em hipocôndrio e flanco à direita. Com relação a esse caso clínico e\ncom base nos conhecimentos médicos correlatos, julgue o item a seguir. Os sinais com maior\nsensibilidade na pneumonia são a tosse e a permanência da febre.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-214345","number":"214345","sourceNumber":"214345","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente R. A. L., 26 anos de idade, com histórico de vacinação antitetânica completa\nna infância, mas omissão do reforço aos 15\nanos e 25 anos de idade, cortou propositalmente\nambos os pulsos com tesoura, gerando ferimento cortocontuso com exposição da derme, mas sem\nexposição dos planos musculares. Refere que realizou o ato como tentativa de autoextermínio por\nouvir, há vários meses, vozes de comando que o orientavam a se ferir e a ferir outras pessoas. No\natendimento, mostra importante agitação, estado hipervigil e hipotenacidade. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A vacinação antitetânica\nestá indicada para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-179171","number":"179171","sourceNumber":"179171","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa que apresenta a síndrome infecciosa que pode ser assintomática\nou apresentar-se com febre alta, odinofagia, tosse,\nartralgias, adenopatia cervical posterior\nsimétrica (que pode se generalizar), esplenomegalia, hepatomegalia discreta (raramente com\nicterícia), erupção cutânea e comprometimento da orofaringe, sob a forma de faringoamigdalite\nexsudativa.","options":{"A":"Difteria.","B":"Parotidite infecciosa.","C":"Psitacose.","D":"Mononucleose infecciosa.","E":"Angina de Plaut Vicent."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-179212","number":"179212","sourceNumber":"179212","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Doença genética autossômica recessiva que ocorre devido a mutações de um gene\nlocalizado no braço longo do cromossomo 7. Acomete vários órgãos e sistemas, principalmente o\nsistema respiratório e o aparelho digestivo, sendo o acometimento pulmonar responsável pela\nmaior morbimortalidade dos pacientes. O acúmulo de muco espesso nas vias aéreas inferiores é\numa das características-chave da fisiopatogenia da doença pulmonar, assim como a presença de\nreação inflamatória predominantemente neutrofílica. Na evolução, o pulmão torna-se cronicamente\ninfectado por bactérias e o ciclo de infecção, inflamação e remodelamento brônquico acelera-se,\ncontribuindo para o desenvolvimento da doença pulmonar obstrutiva crônica e irreversível. O\ndiagnóstico da doença descrita e a bactéria mais prevalente nas infecções pulmonares são,\nrespectivamente,","options":{"A":"doença de Wilson e pneumococo.","B":"amiloidose e Staphylococcus aureus.","C":"mucopolissacaridose e Klebsiella sp.","D":"histiocitose e E.coli.","E":"fiberose cística e Pseudomonas aeruginosa."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-179210","number":"179210","sourceNumber":"179210","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa que apresenta o fator de prognóstico a ser considerado para\nverificar se a sibilância asmática da criança será prolongada ou persistirá na vida adulta.","options":{"A":"falha da prevenção primária por meio do controle de fatores ambientais","B":"falha da prevenção secundária por meio do uso de corticoides inalatórios","C":"presença de quadros de sibilância associados a episódios de resfriados (viroses de vias aéreas)","D":"diagnóstico de rinite nos três primeiros anos de vida","E":"eosinofilia sanguínea superior a 3%, independentemente de outras patologias"},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177618","number":"177618","sourceNumber":"177618","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"R.G.R., uma criança de 7 meses de idade, foi levada pelos pais a um pronto\natendimento infantil com quadro de tosse e\nsecreção nasal há cerca de 10 dias, com o\ndesenvolvimento de febre, nos últimos 2 dias, e respiração rápida. Ao exame físico, foram\nobservados uma orofaringe com hiperemia discreta, linfodonos cervicais normais, otoscopia normal\nbilateral, ausculta pulmonar com estertores crepitantes à esquerda, palpação abdominal normal,\nausência de sinais de irritação meníngea e inexistência de alterações dermatológicas. A frequência\nrespiratória foi de 52 incursões por minuto. Não havia presença de tiragem subcostal, nem de\ninsuficiência ventilatória, nem de cianose. A paciente consegue alimentar-se ao seio materno com\npouca dificuldade. A saturação periférica de oxigênio é de 96%. A radiografia de tórax demonstra\nárea de consolidação em lobo inferior esquerdo e derrame pleural de cerca de 1,5 cm.\n\nConsiderando quadro clínico, julgue o item a seguir. A presença de taquipneia é sinal de gravidade\ne indica a internação da criança.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177621","number":"177621","sourceNumber":"177621","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"RR.G.R., uma criança de 7 meses de idade, foi levada pelos pais a um pronto\natendimento infantil com quadro de tosse e\nsecreção nasal há cerca de 10 dias, com o\ndesenvolvimento de febre, nos últimos 2 dias, e respiração rápida. Ao exame físico, foram\nobservados uma orofaringe com hiperemia discreta, linfodonos cervicais normais, otoscopia normal\nbilateral, ausculta pulmonar com estertores crepitantes à esquerda, palpação abdominal normal,\nausência de sinais de irritação meníngea e inexistência de alterações dermatológicas. A frequência\nrespiratória foi de 52 incursões por minuto. Não havia presença de tiragem subcostal, nem de\ninsuficiência ventilatória, nem de cianose. A paciente consegue alimentar-se ao seio materno com\npouca dificuldade. A saturação periférica de oxigênio é de 96%. A radiografia de tórax demonstra\nárea de consolidação em lobo inferior esquerdo e derrame pleural de cerca de 1,5 cm.\n\nConsiderando quadro clínico, julgue o item a seguir. Considerando-se a ausência de sinais de\ngravidade, a conduta mais adequada é a liberação ambulatorial da criança para antibioticoterapia\ndomiciliar, não havendo necessidade de internação ou de investigações adicionais.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177624","number":"177624","sourceNumber":"177624","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"R.G.R., uma criança de 7 meses de idade, foi levada pelos pais a um pronto\natendimento infantil com quadro de tosse e\nsecreção nasal há cerca de 10 dias, com o\ndesenvolvimento de febre, nos últimos 2 dias, e respiração rápida. Ao exame físico, foram\nobservados uma orofaringe com hiperemia discreta, linfodonos cervicais normais, otoscopia normal\nbilateral, ausculta pulmonar com estertores crepitantes à esquerda, palpação abdominal normal,\nausência de sinais de irritação meníngea e inexistência de alterações dermatológicas. A frequência\nrespiratória foi de 52 incursões por minuto. Não havia presença de tiragem subcostal, nem de\ninsuficiência ventilatória, nem de cianose. A paciente consegue alimentar-se ao seio materno com\npouca dificuldade. A saturação periférica de oxigênio é de 96%. A radiografia de tórax demonstra\nárea de consolidação em lobo inferior esquerdo e derrame pleural de cerca de 1,5 cm.\n\nConsiderando quadro clínico, julgue o item a seguir. Na referida faixa etária, o Streptococcus\npneurmoniae é a etiologia bacteriana mais frequente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177630","number":"177630","sourceNumber":"177630","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"R.G.R., uma criança de 7 meses de idade, foi levada pelos pais a um pronto\natendimento infantil com quadro de tosse e\nsecreção nasal há cerca de 10 dias, com o\ndesenvolvimento de febre, nos últimos 2 dias, e respiração rápida. Ao exame físico, foram\nobservados uma orofaringe com hiperemia discreta, linfodonos cervicais normais, otoscopia normal\nbilateral, ausculta pulmonar com estertores crepitantes à esquerda, palpação abdominal normal,\nausência de sinais de irritação meníngea e inexistência de alterações dermatológicas. A frequência\nrespiratória foi de 52 incursões por minuto. Não havia presença de tiragem subcostal, nem de\ninsuficiência ventilatória, nem de cianose. A paciente consegue alimentar-se ao seio materno com\npouca dificuldade. A saturação periférica de oxigênio é de 96%. A radiografia de tórax demonstra\nárea de consolidação em lobo inferior esquerdo e derrame pleural de cerca de 1,5 cm.\n\nConsiderando quadro clínico, julgue o item a seguir. O uso de amoxicilina na dose de 25 mg/kg/dia\né a primeira opção de tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177557","number":"177557","sourceNumber":"177557","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de\nodinofagia, tosse discreta e febre de até 39°C há 2 dias. Ao\nexame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta pulmonar\nnormal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. A presença do exsudato\nesbranquiçado é sinal confirmatório da etiologia bacteriana.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177560","number":"177560","sourceNumber":"177560","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de odinofagia,\ntosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. Se disponível, o teste\nrápido para antígeno estreptocócico é uma alternativa para confirmar a etiologia bacteriana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177566","number":"177566","sourceNumber":"177566","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 5 anos de idade é levado por sua mãe a um serviço de pronto\natendimento pediátrico com queixas de\nodinofagia, tosse discreta e febre de até 39 °C, há 2 dias.\nAo exame físico, observam-se alguns linfonodos cervicais aumentados e dolorosos, ausculta\npulmonar normal, ausência de secreção nasal e orofaringe hiperemiada, com presença de placas\nesbranquiçadas na amígdala esquerda. Com base no hipotético caso citado e considerando os\nprincipais diagnósticos e as possíveis complicações, julgue o item a seguir. A palpação abdominal,\na qual não foi realizada pelo médico que conduziu o atendimento, poderia revelar sinais capazes de\nalterar a suspeita etiológica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-177646","number":"177646","sourceNumber":"177646","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"I.F.S., menino de 3 anos de idade em acompanhamento em serviço de referência por\ndiagnóstico de nefroblastoma, aguardando tratamento cirúrgico, é levado ao pronto atendimento,\npor sua mãe, devido a queixas de diarreia há um dia, com cinco episódios de evacuação líquidas\nsem produtos patológicos, diminuição da ingestão alimentar e discreta diminuição do volume\nurinário. Não refere vômitos ou febre. As mucosas estão úmidas e coradas. A criança está alerta\nbrincando pelo consultório. O exame abdominal revela discreto desconforto difuso, sem\nperitonismo, além da massa abdominal palpável. Aproveitando a oportunidade da consulta médica,\na mãe do paciente resolve tirar algumas dúvidas sobre o transporte dele no carro. Com base nas\ninformações apresentadas no caso clínico e conhecimentos correlatos, julgue o item a seguir.\n\nApesar da ausência de outros sinais, o relato de diminuição do débito urinário classifica a\ndesidratação de Iago como leve.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-154345","number":"154345","sourceNumber":"154345","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente, 2 meses de idade, é atendido em um hospital universitário com quadro de\ndesidratação secundária a vômitos volumosos em repetição e perda de peso. A mãe refere que os\nvômitos surgiram há um mês e sempre são de conteúdo alimentar e após alimentação, sem outras\nqueixas. Ao exame físico, observa-se que o paciente está desidratado de hipoativo e apresenta\npequena massa palpável (oliva) no epigástrio. A respeito desse quadro, a hipótese diagnóstica\nmais provável é de:","options":{"A":"Estenose Hipertrófica do Piloro (EHP).","B":"Pâncreas anular.","C":"Refluxo Gastroesofágico (RGE) Fisiológico.","D":"Atresia duodenal.","E":"Gastroenterite infecciosa."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-154326","number":"154326","sourceNumber":"154326","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Considere que um lactente com quadro agudo de anemia hemolítica, insuficiência renal\ne trombocitopenia, que apareceram posteriormente a\num quadro de diarreia com sangue, recebeu o\ndiagnóstico final de Síndrome Hemolítico-Urêmica (SHU). Embora a ocorrência dessa síndrome\nesteja relacionada a diversos determinantes, como formas hereditárias da doença, administração\nde medicamentos e patógenos variados, a respectiva causa principal é a infecção por:","options":{"A":"Salmonella.","B":"Escherichia Coli, produtora de Shiga toxina (STEC).","C":"Campylobacter.","D":"Rotavírus.","E":"Neisseria meningitidis."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-154328","number":"154328","sourceNumber":"154328","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um casal chegou ao pronto atendimento com o filho de 4 meses de idade, referindo\nque eles, há uma semana, estiveram expostos\na um quadro respiratório leve. Há dois dias, o filho\ncomeçou a apresentar espirros, coriza hialina e diminuição do apetite, febre de 38°C e dificuldade\nrespiratória com tosse e irritabilidade. Ao exame físico, é evidente a presença de sibilância,\nmarcado esforço respiratório, com batimentos de asas do nariz e tiragem subcostal. Os raios X de\ntórax mostraram pulmões hiperinsuflados. Hemograma sem alterações significativas. Considerando\no caso apresentado, assinale a alternativa que corresponde à principal hipótese diagnóstica para\nesse paciente.","options":{"A":"Asma brônquica.","B":"Sinusite.","C":"Corpo estranho na traqueia.","D":"Insuficiência cardíaca congestiva.","E":"Bronquiolite."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-152146","number":"152146","sourceNumber":"152146","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente feminina, de três anos de idade, foi atendida em consulta na unidade básica\nde saúde com histórico de tosse há 48 horas e\nfebre de 38,8 °C. Ao exame físico, apresentou\nausculta pulmonar com discretos estertores crepitantes na base do hemitórax direito, FR = 44 irpm\ne SO2 = 96%. Considerando essa hipótese clínica, julgue o item a seguir. A realização de raios X\nde tórax é necessária para a confirmação do diagnóstico e início do tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-152060","number":"152060","sourceNumber":"152060","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente feminina, de 3 anos de idade, foi atendida em consulta na unidade básica de\nsaúde com histórico de tosse há 48 horas e\nfebre de 38,8°C. Ao exame físico, apresentou ausculta\npulmonar com discretos estertores crepitantes na base do hemitórax direito, FR = 44 irpm e SO2 =\n96%. Considerando essa hipótese clínica, julgue o item a seguir: a internação hospitalar e o\ntratamento com antimicrobianos endovenosos são a escolha mais adequada para essa paciente,\nconsiderando o diagnóstico como pneumonia comunitária.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-152068","number":"152068","sourceNumber":"152068","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente feminina, de 3 anos de idade, foi atendida em consulta na unidade básica de\nsaúde com histórico de tosse há 48 horas e\nfebre de 38,8 °C. Ao exame físico, apresentou ausculta\npulmonar com discretos estertores crepitantes na base do hemitórax direito, FR = 44 irpm e SO2 =\n96%. Considerando essa hipótese clínica, julgue o item a seguir: os agentes mais comumente\ncausadores da pneumonia comunitária, nessa faixa estária, são: Streptococcus pneumoniae,\nHaemophilus influenzae tipo b e Staphylococcus aureus.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-152102","number":"152102","sourceNumber":"152102","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 7 meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: nota-se que a otite média\naguda em lactentes, adquirida na comunidade, é causada majoritariamente por agentes\nbacterianos, principalmente S. pneumoniae, H. influenzae.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-152110","number":"152110","sourceNumber":"152110","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 7 meses de idade foi levado ao pronto atendimento, pois, após três dias de\nsintomas gripais, apresentou crise convulsiva tônico-clônica generalizada que durou alguns\nminutos. A mãe nega episódios anteriores e casos de epilepsia na família. Ao exame físico,\nobserva-se paciente febril (temperatura axilar 38,5°C). hipoativo, porém responsivo (Glasgow\n15/15), pupilas isocóricas e fotorreagentes. Otoscopia evidencia abaulamento da membrana\ntimpânica à direita. Com base nesse caso clínico, julgue o item a seguir: usa-se a amoxicilina,\nantibiótico de primeira escolha na otite média aguda adquirida na comunidade, salvo algumas\nexceções.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-135053","number":"135053","sourceNumber":"135053","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Acerca da Bronquiolite Viral Aguda (BVA), julgue o item que se segue. Estudos\nrecentes mostram que a fisioterapia não combate\nos sintomas da BVA, tampouco propicia evolução\nnos parâmetros respiratórios ou na necessidade de oxigênio dos pacientes acometidos por essa\npatologia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-135062","number":"135062","sourceNumber":"135062","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Julgue o próximo item, referente às políticas de saúde no Brasil: A vacina contra a febre\namarela é obrigatória para trabalhadores e moradores de áreas de risco. Ela deve ser aplicada em\ntodos os indivíduos, entre os quais gestantes e puérperas em qualquer fase de amamentação.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-105578","number":"105578","sourceNumber":"105578","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Ao ser indagado pelos pais acerca da profilaxia da hepatite B, o pediatra deve afirmar\nque a vacina deve ser dada:","options":{"A":"Logo ao nascimento, mas apresenta baixa proteção caso a mãe tenha contraído a doença na\ngestação. Na adolescência, são três doses, a depender da situação vacinal. O melhor indicador de\nproteção é a dosagem do marcador viral: o anticorpo contra o antígeno de superfície do vírus.","B":"No segundo mês de vida, pois não apresenta proteção no período neonatal, caso a mãe tenha\ncontraído a doença, sendo indicada nesse caso a aplicação de imunoglobulina específica em dose\núnica até 72 horas de vida. O reforço é administrado na adolescência, dependendo da situação\nvacinal. O melhor indicador de proteção é a dosagem do anti-HBc.","C":"Logo ao nascimento, pois apresenta alta proteção mesmo que a mãe tenha contraído a doença\nna gestação. O reforço é dado com a vacina\npentavalente. O melhor indicador de proteção é a\ndosagem do marcador viral anti-HBsAg.","D":"Em até doze horas de vida, pois apresenta alta proteção, mesmo que a mãe tenha contraído a\ndoença. Não é necessário reforço. Na adolescência são duas doses, a depender da situação\nvacinal. O melhor indicador de proteção é a dosagem do anti-HBsAg.","E":"Logo ao nascimento caso a sorologia materna do pré-natal seja positiva, pois apresenta alta\nproteção. Caso contrário, deve-se aplicá-la\nno segundo mês de vida com reforço na adolescência a\ndepender da situação vacinal. O melhor indicador de proteção é a dosagem do marcador viral de\nsuperfície."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-108230","number":"108230","sourceNumber":"108230","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Julgue o item que se segue, relativo as doenças infecciosas na infância e na\nadolescência. Caso uma gestante com\ntuberculose pulmonar e baciloscopia positiva inicie o\ntratamento específico dez dias antes do trabalho de parto, o médico que assistir ao recém-nascido\ndeverá vacinar o bebê com BCG imediatamente, mantê-lo junto à mãe e recomendar o aleitamento\nem livre demanda.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-108236","number":"108236","sourceNumber":"108236","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No item abaixo é apresentado um caso clínico relacionado a gestão da política de\nsaúde no Brasil, seguido de uma assertiva a\nser julgada. Um lactente de seis meses de idade foi\npela primeira vez a um centro de saúde so Sistema Único de Saúde (SUS), e o médico observou\nque ele ainda não recebera nenhuma vacina. Nesse caso, o médico deve recomendar a aplicação,\nde uma só vez, das seguintes vacinas: BCG, a primeira dose da vacina pentavalente (DPT +\nhemófilos+ hepátite B) ou estas isoladamente, a primeira dose da vacina antipoliomelite injetável, a\nprimeira dose da vacina antirrotavírus e a primeira dose da vacina antipoetamocócica decavalente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-108206","number":"108206","sourceNumber":"108206","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de setenta e dois anos de idade, com antecedente de hipertensão arterial\nhá vários anos, compareceu ao ambulatório\nrelatando dispneia decorrente de esforços maiores que\nos habituais, como subir escadas ou andar apressadamente. O paciente relatou, ainda, o uso\nirregular de um anti-hipertensivo prescrito (clortalidona). No exame físico, o idoso apresentou-se\nnormocorado, com extremidades quentes, frequência cardíaca de 108 bpm, pressão arterial de 154\nmmHg x 72 mmHg, turgência jugular a 30°, ausculta pulmonar normal, ictus cordis propulsivo no 6º\nespaço intercostal esquerdo da linha axilar anterior, ritmo cardíaco em galope (terceira bulha) e\nsem sopros. Adicionalmente, notou-se refluxo hepatojugular e edema perimaleolar bilateral. Os\nexames laboratoriais revelaram sódio de 144 mEq/L; potássio de 5,4 mEq/L; creatinina de 3,2\nmg/dL; hemoglobina de 10,4 g/dL; e hematócrito de 31%. Os demais exames bioquímicos e a\nfunção tireoidiana estavam normais. O ecocardiograma revelou fração de ejeção de 36%. Com\nreferência ao caso clínico acima apresentado, julgue o item que se segue. De acordo com o\nMinistério da Saúde, a vacina anti-influenza é indicada para o paciente em questão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-79685","number":"79685","sourceNumber":"79685","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa que apresenta a vacina que ainda não deve ter sido tomada por\num lactente aos 2 meses de idade.","options":{"A":"Hepatite B.","B":"Meningocócica.","C":"DTP.","D":"Hib.","E":"Pneumocócica."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-88656","number":"88656","sourceNumber":"88656","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"No que concerne à imunização contra a influenza sazonal disponibilizada pelo Sistema\nÚnico de Saúde (SUS), julgue o próximo item. Entre os grupos de pessoas que devem ser\nimunizados contra influenza sazonal constam os lactentes com idade entre seis e vinte e três\nmeses, gestantes, indivíduos com mais de sessenta anos de idade, indivíduos com doenças\ncrônicas (pneumopatas, diabéticos, cardiopatas e doentes renais crônicos) e profissionais de\nsaúde.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-366244","number":"366244","sourceNumber":"366244","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. A\nprincipal hipótese diagnóstica é de Leucemia Linfocita Aguda pelo achado de linfócito com alta\nrelação núcleo-citoplasma","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-366243","number":"366243","sourceNumber":"366243","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. O\naumento do volume abdominal provavelmente é devido à esplenomegalia que acontece em\nquantidade razoável do quadro principalmente em crianças pequenas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-366242","number":"366242","sourceNumber":"366242","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 8 anos foi conduzida pelo pai ao pronto-socorro devido a histórico de\nfebre súbita, registrando até 38,8 °C nas\núltimas duas semanas, que parcialmente cede ao uso de\nantipiréticos, mas retorna. Inicialmente, apresentou tosse, odinofagia, rinorreia e faringite\n(Figura I).\nApós atendimento inicial com prescrição de antitérmicos e observação, a criança desenvolveu\nfadiga intensa, prostração, aumento do volume abdominal e notou-se \"\"caroços no pescoço\"\"\n(Figura II). Diante desses novos sintomas, foi trazida para reavaliação. O hemograma solicitado\nrevelou uma anemia leve normocítica e normocrômica, enquanto o leucograma quantitativo estava\ndentro dos parâmetros normais, sem achados relevantes, exceto pela observação em lâmina\nperiférica de um linfócito (FIgura III). A partir do quadro clínico exposto, bem como achado de\nexame complementar e os assunto correlatos que ele suscita, julgue o item que se segue. O\ndiagnóstico em questão tem tropismo por células B do epitélio tonsilar e seu período de incubação\ndura entre 4 a 6 semanas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343412","number":"343412","sourceNumber":"343412","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre a Bronquiolite, é CORRETO afirmar:","options":{"A":"É frequentemente causada por agentes não virais nas crianças acima de dois anos de idade.","B":"As principais infecções bacterianas envolvidas nas complicações da bronquiolite são otite média\naguda e pneumonia.","C":"Cerca de 10% dos casos exigem internação hospitalar e, desses, cerca de 30% necessitam de\ninternação em terapia intensiva.","D":"É causada predominantemente pelo rinovírus nos períodos epidêmicos, ou seja, no outono, e\npelo adenovírus nas situações não epidêmicas."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-334892","number":"334892","sourceNumber":"334892","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um pré-escolar de 3 anos de idade comparece, com os pais dele, à consulta\nambulatorial. Eles relatam que a criança\napresenta sintomas recorrentes de tosse persistente, muito\nbaixo ganho de peso e aumento da frequência das evacuações com fezes gordurosas. Na história\npatológica pregressa, observa-se o quadro a seguir. No quinto dia de vida: íleo meconial; aos 12\nmeses: internação por bronquiolite grave e, posteriormente, várias internações por sibilância\nrecorrente; e aos 15 meses: bronquiectasias. Na história familiar, sabe-se que o avô faleceu por\ndoença respiratória crônica, que os pais não souberam especificar. Qual é o diagnóstico mais\nprovável desse caso hipotético?","options":{"A":"Asma crônica grave","B":"Coqueluche","C":"Fibrose cística","D":"Cirrose","E":"Alergia a leite de vaca"},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343415","number":"343415","sourceNumber":"343415","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A otite média aguda trata-se da inflamação do ouvido médio e de seus anexos,\nassociada à presença de líquido na orelha\nmédia, com sinais e sintomas de início agudo, como dor\ne febre. NÃO é agente bacteriano frequentemente encontrados na otite média aguda:","options":{"A":"Streptococcus Pneumoniae.","B":"Escherichia Coli.","C":"Haemophilus Influenzae não tipável.","D":"Moraxella Catarrhalis."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343416","number":"343416","sourceNumber":"343416","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Com relação à Coqueluche, é INCORRETO afirmar:","options":{"A":"É uma doença de notificação compulsória.","B":"A transmissão é pelo contato direto com gotículas do trato respiratório de pessoas infectadas.","C":"Seu agente etiológico é um Cocobacilo Gram positivo.","D":"A principal complicação é a pneumonia. A convulsão é uma complicação neurológica frequente,\nsobretudo, nos menores de 1 ano."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343417","number":"343417","sourceNumber":"343417","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Levando em conta a saúde da criança, considera-se frequência respiratória normal,\nsegundo a Organização Mundial da Saúde (OMS), para criança acima de 8 anos:","options":{"A":"Até 60 mrm.","B":"Até 40 mrm.","C":"Até 30 mrm.","D":"Até 20 mrm."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-343422","number":"343422","sourceNumber":"343422","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente feminino em idade escolar, dá entrada no hospital com história de febre há 3\ndias, cansaço, tosse seca, dor de garganta e dores articulares no início dos sintomas. Ao exame\nfísico, encontra-se em bom estado geral, acianótica, afebril e eupneica. Apresenta rash cutâneo\ndifuso. A ausculta pulmonar revela sibilos difusos bilateralmente. Diante do quadro, o pediatra\nsuspeita de infecção por Mycoplasma Pneumoniae. Foi realizado radiografia de tórax, que\nevidencia consolidação pulmonar predominando em lobo inferior direito e mínimo derrame pleural.\nCom relação a este caso, é CORRETO afirmar:","options":{"A":"Os achados radiológicos descartam suspeita de infecção por M. Pneumoniae.","B":"Os dados clínicos não frequentes encontrados na infecção por M. Pneumoniae.","C":"O rash cutâneo é uma manifestação extra pulmonar comum dessa infecção.","D":"A dosagem das crioaglutininas é indicado para realização nessa fase da doença."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307114","number":"307114","sourceNumber":"307114","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um pré-escolar de 4 anos de idade foi levado à consulta ambulatorial por sua mãe, com\nqueixa de rinorreia fétida, mucopurulenta unilateral há quatro dias. Não existem outras queixas e\n(ou) sintomas associados. A mãe nega trauma e refere ser o primeiro episódio desse tipo. Nesse\ncaso clínico, o melhor diagnóstico é Alternativas:","options":{"A":"sífilis terciária.","B":"atresia de coana bilateral.","C":"traumatismo craniano.","D":"corpo estranho nasal.","E":"meningite."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-307115","number":"307115","sourceNumber":"307115","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente de 5 anos de idade iniciou quadro de febre há dois dias, com rápida\nprogressão para odinofagia intensa,\nprostração, estridor inspiratório, desconforto respiratório\nimportante e cianose. No exame de raios X da coluna cervical, observou-se o ?sinal do polegar?.\nAssinale a alternativa que apresenta, respectivamente, o diagnóstico e a conduta mais adequados\npara esse caso clínico. Alternativas:","options":{"A":"Epiglotite ? Antibioticoterapia","B":"Laringite diftérica ? Penicilina","C":"Corpo estranho brônquico ? Cirurgia","D":"Estenose subglótica adquirida ? Corticoide","E":"Laringomalácia ? Observação"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-273314","number":"273314","sourceNumber":"273314","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 1 ano e 2 meses de idade com história de tosse e febre há 5 dias. A mãe\nrefere que a criança só está piorando, está\ncansada há 2 dias e não aceita alimentação. Ao exame\nfísico: toxemiada, FR = 54 mrpm, FC = 130 bpm, T = 38,5° C. Murmúrio vesicular presente, com\nbroncofonia aumentada em ápice D e presença de tiragem subcostal e intercostal discretas. Foi\nsolicitado Rx de tórax, que mostrou velamento homogêneo em lobo superior direito, com\nbroncogramas aéreos. A conduta terapêutica mais adequada para este caso é:","options":{"A":"Tratamento ambulatorial com Amoxicilina + Clavulanato.","B":"Internação hospitalar, ofertar oxigênio por meio de cateter nasal e entrar com Penicilina\nCristalina ou Ampicilina IV.","C":"Internação hospitalar, drenagem pleural e entrar com Ceftriaxone + Oxacilina.","D":"Internação hospitalar, ofertar oxigênio por meio de cateter nasal e entrar com Cefalotina IV."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-273315","number":"273315","sourceNumber":"273315","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Criança de 9 meses com história de diarréia há 2 dias, acompanhada de vômitos\nesporádicos. A mãe refere que as fezes estão\nlíquidas, sem muco ou sangue e que a criança está\napresentando de 6 a 8 episódios/dia, fezes volumosas e fétidas. Ao exame físico: REG, irritada,\nsedenta, com pulsos periféricos finos e pulsos centrais normopalpáveis, enchimento capilar de 2\nsegundos. Olhos encovados e mucosas secas. FC = 160 bpm, FR = 50 mrpm, T = 38°C, PA = 85 x\n40 mmHg. A conduta inicial mais adequada é:","options":{"A":"Gastróclise; 20 a 30 ml/Kg/h em 4 horas.","B":"NaCl 0,9% + SG 5% em partes iguais; 100 ml/Kg IV em 2 horas.","C":"NaCl 0,9%; 20 ml/Kg IV rapidamente.","D":"TRO; 50 a 100 ml/Kg de SRO em 4 horas."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-263344","number":"263344","sourceNumber":"263344","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança com 6 anos de idade é levada para atendimento em Unidade Básica de\nSaúde devido à constipação intestinal. O\nquadro teve início há 1 mês e vem piorando\ngradativamente, com postura retentiva e incontinência urinária associados. Atualmente, a criança\napresenta apenas uma evacuação a cada 3 dias, com fezes em síbalos. Ao exame físico,\n\nmostra-se em bom estado geral, corada e hidratada. Abdome globoso, distendido, sem\nvisceromegalias, com fezes palpáveis em fossa\nilíaca esquerda. O toque retal evidencia esfíncteres\nanal interno relaxado e externo contraído, além de fezes na ampola retal. A provável causa da\nconstipação intestinal é:","options":{"A":"Aganglionose congênita.","B":"Constipação funcional.","C":"Alergia alimentar.","D":"Hipotireoidismo."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-273317","number":"273317","sourceNumber":"273317","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 7 meses, previamente hígido, iniciou quadro de febre baixa, tosse e coriza\nhá 3 dias, evoluindo com dificuldade\nrespiratória e sibilância. Foi feito o diagnóstico clínico de\nbronquiolite viral aguda e iniciado tratamento com Fenoterol inalatório de 2/2 h e Prednisolona VO.\nQuanto ao diagnóstico e conduta você:","options":{"A":"Concorda com o diagnóstico e discorda do tratamento.","B":"Discorda do diagnóstico e do tratamento.","C":"Concorda com o diagnóstico e com o tratamento.","D":"Discorda do diagnóstico, mas concorda com o tratamento."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291473","number":"291473","sourceNumber":"291473","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente, 2 anos, sexo masculino, chega ao pronto atendimento de um hospital\npúblico com relato de ter iniciado há 5 dias\ncoriza serosa e tosse seca irritativa. Evoluiu hoje com\nfebre elevada, secreção nasal mais espessa e tosse produtiva e com boa aceitação alimentar. Ao\nexame físico do aparelho respiratório, evidenciou-se saturação 96%, FR = 50 irpm, murmúrio\nvesicular diminuído em base do hemitórax direito, frêmito toracovocal com macicez e crepitações\ngrosseiras audíveis no mesmo local. Encontrava-se hidratado, tolerando os medicamentos por via\noral. Foi testado para COVID-19 no dia anterior, cujo resultado foi negativo. A terapêutica\nantibiótica a ser instituída nesse caso é.","options":{"A":"Amoxicilina.","B":"Azitromicina.","C":"Claritromicina.","D":"Ceftriaxona."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-268903","number":"268903","sourceNumber":"268903","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 9 anos de idade foi levada à emergência com quadro de odinofagia,\nfebre alta (39 ºC), calafrios e anorexia há\ncinco dias. Ao exame físico, a orofaringe está eritematosa\ne as amígdalas estão hipertrofiadas bilateralmente, com petéquias no palato e adenopatia cervical\ndolorosa. Esses sintomas não evoluíram em gravidade. O estado geral é bom, apesar da\nodinofagia. Verificam-se FC = 90 bpm, FR = 28 irpm e SatO2 = 99%. O restante do exame físico\nmostra-se sem alterações. Nesse caso clínico, o principal diagnóstico é","options":{"A":"dengue.","B":"pneumonia estafilocócica.","C":"doença por herpesvírus tipo 8.","D":"difteria.","E":"amigdalite estreptocócica."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-268907","number":"268907","sourceNumber":"268907","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Certo paciente de 6 meses de idade é levado, às pressas, ao setor de emergência mais\npróximo de seu domicílio, por causa de vômitos e diarreia. A mãe refere que ele começou o quadro\ndiarreico no dia anterior, mas, no dia da consulta, apresentou muitos episódios aquosos, sem\nsangue, muco ou pus. Ao exame, a criança encontra-se com os olhos fundos, a boca seca,\nbebendo com muita sede o líquido oferecido e irritadiça. Constatam-se FR = 40 irpm, FC = 120 bpm\ne SatO2 = 97%. Com base nesse caso clínico e nos conhecimentos médicos correlatos, é correto\nafirmar que os prováveis diagnóstico e tratamento para o mencionado paciente são,\nrespectivamente,","options":{"A":"diarreia aguda com desidratação; plano B de hidratação.","B":"diarreia crônica, desidratação grave; plano de hidratação parenteral.","C":"diarreia crônica moderada; plano A de hidratação.","D":"quadro de desnutrição aguda grave; sais de hidratação oral.","E":"gastroenterite crônica, sem desidratação; aumento da ingesta proteica."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-263372","number":"263372","sourceNumber":"263372","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma adolescente com 13 anos de idade é atendida no pronto-socorro por apresentar\n\"perda de força nas pernas\". Segundo a mãe,\na adolescente está doente há mais de um mês na\nprimeira semana da doença, teve febre alta que durou 5 dias, dor de garganta, dores no corpo e\ncansaço extremo. Ela informa, ainda, que a filha foi diagnosticada com amigdalite, recebeu\namoxicilina por 7 dias e que, durante esse tratamento, apresentou manchas vermelhas levemente\npruriginosas pelo corpo. A mãe relata também que, após desaparecimento da febre, a adolescente\npersistiu com desânimo por cerca de 3 semanas e, quando parecia estar se recuperando, começou\na queixar-se de dor e formigamento nos pés e pernas, com dificuldade progressiva para caminhar e\nque, hoje, não havia conseguido levantar-se da cama. Ao exame físico, a paciente apresenta\nparaparesia simétrica e diminuição de força muscular em membros superiores, reflexos\nosteotendinosos diminuídos em membros superiores e abolidos nos membros inferiores. Em\nrelação a esse quadro clínico, quais são as principais hipóteses diagnósticas?","options":{"A":"Dengue; meningite asséptica.","B":"Dengue; síndrome de Guillain-Barré.","C":"Mononucleose infecciosa; meningite asséptica.","D":"Mononucleose infecciosa; síndrome de Guillain-Barré."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-274624","number":"274624","sourceNumber":"274624","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A alternativa que melhor conceitua a gastroenterite aguda é:","options":{"A":"Quadro clínico resultante da inflamação aguda das mucosas do estômago e rins, que se traduz\npor vômito e diarreia, por vezes acompanhado\nde dor abdominal e febre.","B":"Quadro clínico resultante da inflamação aguda das mucosas do estômago e intestino, que se\ntraduz por vômito e diarreia, sem estar acompanhado de dor abdominal ou febre.","C":"Quadro clínico resultante da inflamação aguda das mucosas do estômago, comumente\nassintomático.","D":"Quadro clínico resultante da inflamação aguda das mucosas do estômago e intestino, que se\ntraduz por vômito e diarreia, por vezes acompanhado de dor abdominal e febre."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-274625","number":"274625","sourceNumber":"274625","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menina gemelar, 6 meses, encontrada sem respiração por seus pais em seu berço pela\nmanhã. Ausência de braquicardia e cianose. Causa morte indeterminável. Diagnóstico mais\nprovável de morte súbita. Nesse caso deverá ser feita anamnese, autópsia e:","options":{"A":"Exame da apneia da prematuridade.","B":"Gasometria arterial.","C":"Gasometria venosa.","D":"Investigação do local do óbito."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291527","number":"291527","sourceNumber":"291527","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente masculino, com 5 semanas de vida, chegou no pronto-socorro com história\nde vômitos em jatos (sem bile) logo após as\nmamadas. A mãe relata que não está entendendo\nporque ele não está engordando. Nasceu com 3 500 g. Apesar dos vômitos, que tiveram início\npouco depois do nascimento, ele demonstrava muita fome e sugava \"com vontade\" o leite materno,\nmas desde ontem está hipoativo, quase não urina e a boca está seca. O exame apresentou os\nseguintes resultados: P = 3 600 g, sinal de prega presente, mucosa oral seca, hipoativo, perfusão\ncapilar em 4 segundos, massa semelhante a uma azeitona, discreta, firme, móvel, de 2 a 3 cm,\npalpável no fundo do lado direito do epigástrico. Sem outras anormalidades. Considerando os\ndiagnósticos do lactente, qual conduta médica deve ser adotada?","options":{"A":"Hidratação venosa e fazer US abdominal para esclarecer a suspeita diagnóstica de base que\nocasionou o quadro.","B":"Hidratar o paciente no domicílio e solicitar acompanhamento ambulatorial com pediatra.","C":"Usar antiemético, fazer hidratação venosa do paciente e encaminhar para acompanhamento\nambulatorial.","D":"Prescrever associação de fórmula para complementar o leite materno e fazer hidratação oral,\nplano B."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-274662","number":"274662","sourceNumber":"274662","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A gravidez traz modificações na anatomia e na fisiologia respiratórias, o que influencia\na\nfunção respiratória, causando dispneia ou afetando o curso de doenças pulmonares. Dentre as\ndoenças que acometem mulheres gestantes se encontra a fibrose cística, a qual, por sua vez, pode\nser diagnosticada durante a gravidez obtendo o material genético do feto com a amniocentese.\n\nDiante do enunciado, a alternativa que corresponde à correlação da fibrose cística e ao período\ngravídico da gestante é:","options":{"A":"Se houver um aumento significativo no teor de sódio, o aleitamento é contraindicado nos 3\nprimeiros meses.","B":"A gravidez compromete a sobrevida a longo prazo na fibrose cística.","C":"Os testes de função pulmonar devem ser realizados trimestralmente durante toda a gestação.","D":"As pacientes afetadas podem ter insuficiência pancreática."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-263412","number":"263412","sourceNumber":"263412","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente com 2 meses de idade é atendido na emergência, acompanhado pela mãe,\nque relata vômitos pós-grandiais desde os 15 dias de vida, com piora progressiva em frequência e\nintensidade. Ela conta que, após tais episódios eméticos, o lactente chora e parece ter fome.\n\nInforma, ainda, que seu filho nasceu a termo, com peso de 3 000 g e 49 cm de comprimento e que\nos testes de triagem neonatal foram normais.\nEla nega a ocorrência de doenças gestacionais e\nperinatais. Ao exame físico, o lactente apresenta-se emagrecido (peso = 3 200 g), ativo, acianótico,\nantictérico, desidratado (1+/4+) e corado, com abdome distendido, especialmente na região\nepigástrica, notando-se ausência de hepatoesplenomegalia e presença de ondas de Kussmaul\nobservadas após a alimentação. Os exames laboratoriais iniciais revelam pH = 7,5 (valor de\nreferência: 7,35 a 7,45); HCO? = 27 mEq/L (valor de referência: 23 a 28 mEq/L); Na = 135 mmol/L\n(valor de referência: 136 a 145 mmol/L); Cl = 95 mmol/L (valor de referência : 98 a 106 mmol/L) e K\n\n= 4,5 mmol/L (valor de referência: 3,5 a 5,5 mmol/L). Nesse caso, a conduta médica adequada é","options":{"A":"solicitar endoscopia digestiva alta e elevação da cabeceira do berço.","B":"solicitar ultrassonografia de abdome e piloromiotomia à Fredet-Ramstedt.","C":"investigar doenças metabólicas e administrar dieta hipoproteica e hipercalórica.","D":"prescrever expansão com soro fisiológico 0,9% e infusão de hidrocortisona 50 mg/m²\nsubcutânea/dia."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291535","number":"291535","sourceNumber":"291535","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um escolar de 7 anos de idade apresenta queixa de dificuldade para evacuar desde a\nretirada das fraldas aos 2 anos e meio. Apresenta evacuação a cada 4 ou 5 dias, com eliminação\nde fezes endurecidas, de grande calibre, com presença de dor e esforço evacuatório. Relata que,\nao menos 3 vezes por semana, observa a presença de fezes perdidas na roupa. Por vezes, nota a\npresença de sangue em pequena quantidade no papel em que se higienizou. Nega antecedentes\nneonatais ou outras comorbidades relevantes; desmame aos 4 meses de idade; não faz uso de\nmedicação de rotina. Alimenta-se quantitativamente bem com preferência pelo consumo de leite (4\nporções diárias), carboidratos, carne e alimentos ultraprocessados; de forma bem infrequente,\nbatata, cenoura, tomate, banana e maçã compõem a sua dieta. Está alfabetizado e é o melhor\naluno de sua sala. Nesta consulta, seu peso encontra-se no Z-score entre +2 e +3 da curva de\níndice de massa corpórea da OMS e sua altura encontra-se no Z-score entre +1 e +2 da curva de\naltura para idade da OMS. Ao exame abdominal, apresenta fezes endurecidas palpáveis em fossa\nilíaca esquerda em moderada quantidade. O exame clínico não apresenta outras alterações.\n\nConsiderando o caso descrito, assinale a alternativa que contém o diagnóstico mais provável e a\nconduta adequada:","options":{"A":"Doença de Hirschsprung, devendo ser submetido ao toque retal para constatação de ampola\nretal vazia.","B":"Hipotireoidismo, devendo ser coletado TSH, T4 livre e anticorpos antireoglobulina e\nantitireoperoxidase.","C":"Alergia à proteína do leite de vaca, devendo fazer teste de exclusão da dieta durante 2 a 4\nsemanas.","D":"Constipação intestinal funcional, devendo fazer desimpactação fecal com polietilenoglicol ou\nenema."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291547","number":"291547","sourceNumber":"291547","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente masculino, de 2 meses, é levado à emergência com história de vômitos\nnão biliosos que iniciaram com três semanas de\nvida e progressivamente pioraram. Há 2 dias,\npassou a vomitar após as mamadas e hoje o vômito está em jato. Ao exame físico, apresenta-se\nirritado, faminto, muito emagrecido; no epigástrio, foi observado onda peristáltica se deslocando da\nesquerda para direita e, após a criança vomitar, palpada à direita, também no epigástrio, massa\nfirme e móvel com cerca de 2 cm de diâmetro. Com base na principal hipótese diagnóstica, o\ndistúrbio ácido-básico que se espera encontrar nesse lactente é","options":{"A":"alcalose metabólica hipoclorêmica.","B":"acidose metabólica hiperclorêmica.","C":"acidose metabólica hipoclorêmica.","D":"alcalose metabólica hiperclorêmica."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-230566","number":"230566","sourceNumber":"230566","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"São sinônimos de traqueíte bacteriana todos os abaixo, EXCETO:","options":{"A":"Crupe membranoso.","B":"Difteria.","C":"Crupe pseudomembranoso.","D":"Laringotraqueobronquite membranosa."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-230567","number":"230567","sourceNumber":"230567","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação às orientações que devem ser feitas\npara as famílias de crianças com diagnóstico de Dor Abdominal Recorrente Funcional (DARF):","options":{"A":"As famílias das crianças com DARF devem ser orientadas sobre a benignidade do quadro; além\ndisso, devem identificar e neutralizar fatores de tensão e estresse.","B":"Os ganhos secundários à dor, como mimos, privilégios e maior atenção familiar, devem ser\nsuspensos.","C":"A família deve ser orientada quanto à gravidade da doença e ao risco de evolução na maioria\ndos casos com complicações e hospitalizações.","D":"As atividades das crianças só devem ser evitadas no momento da crise, ou seja, elas podem ter\nretorno imediato após essa fase."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-244487","number":"244487","sourceNumber":"244487","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente de 42 dias de vida é levado ao pediatra com relato de três episódios, nesta\nsemana, de rajas de sangue nas fezes. Em aleitamento materno exclusivo, não se verificam febre,\ndiarreia, alteração do estado geral ou outro sintoma. Ao exame, constata-se bom ganho ponderal,\nsem qualquer alteração digna de nota. O lactente encontra-se ativo e mama avidamente. Em\nrelação a esse caso clínico, assinale a alternativa que apresenta a principal hipótese diagnóstica e\na conduta inicial.","options":{"A":"Reação vacinal a rotavírus; conduta expectante.","B":"Gastroenterite aguda infecciosa tipo disenteria; antibioticoterapia com metronidazol.","C":"Proctocolite alérgica; exclusão de leite de vaca da dieta materna, seguido de programação de\nprovocação oral via materna.","D":"Intussuscepção intestinal; internação hospitalar.","E":"Giardíase; albendazol oral."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-227401","number":"227401","sourceNumber":"227401","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada a dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. Nos casos de diarreia crônica, a pesquisa de doença\ncelíaca mediante pesquisa de antigliadina com resultado positivo confirma o diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-203163","number":"203163","sourceNumber":"203163","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança de 3 anos de idade é encaminhada ao pronto-socorro com histórico de\nvômitos e diarreia iniciados há sete\ndias, acompanhados de febre no início do quadro. A mãe relata\nque, há quatro dias, observou a presença de muco e rajas de sangue nas fezes. Hoje apresenta\nmelhora da diarreia, porém refere que a diurese está reduzida nas últimas 24 horas. Ao exame, a\ncriança está hemodinamicamente estável, ictérica com palidez mucocutânea e com petéquias em\nmembros e em região perianal. Quanto a esse caso clínico, considerando o diagnóstico clínico mais\nprovável, seria esperado encontrar as seguintes alterações laboratoriais:","options":{"A":"Anemia, elevação de bilirrubina direta e elevação de ureia/creatinina.","B":"Anemia, elevação de bilirrubina indireta e Coombs direto positivo.","C":"Anemia, trombocitopenia e elevação de ureia/creatinina.","D":"Trombocitopenia, elevação de bilirrubina direta e Coombs direto positivo.","E":"Trombocitopenia, elevação de bilirrubina direta e elevação de ureia/creatinina."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-206108","number":"206108","sourceNumber":"206108","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 1 ano de idade com quadro de febre há 2 dias, além de tosse produtiva e\ncansaço. Apresenta-se em REG, FR = 55 irpm, FC = 115 bpm, temperatura axilar 37,8 ?C;\nsaturação de oxigênio 98%; murmúrio vesicular presente bilateralmente com estertores em\nhemitórax direito, sem dispneia e pulsos cheios. Radiografia de tórax: velamento lobo médio direito.\nA conduta a ser adotada no momento seria:","options":{"A":"Internação, solicitar hemograma para iniciar antibioticoterapia.","B":"Iniciar amoxicilina 50-80 mg/kg/dia e reavaliar em 48 horas.","C":"Internação, iniciar penicilina cristalina.","D":"Iniciar cefuroxima e reavaliar em 48 horas."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-212116","number":"212116","sourceNumber":"212116","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Em uma emergência, um pediatra de plantão atendeu um menino de 2 meses e meio\nde idade, que apresentava gemência, retração\ntorácica, FR= 70 irpm, e saturação < 92% em ar\nambiente. Considerando esse caso clínico, julgue o item subsecutivo. Em caso de internação, está\nindicada a prescrição de corticoide sistêmico e nebulização com adrenalina a cada 4 horas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-157978","number":"157978","sourceNumber":"157978","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente escolar 7 anos de idade, sexo masculino, durante o curso de uma otite média\naguda, começa com vertigem, nistagmo, náuseas, vômitos e acúfenos. Nesse caso clínico, o\ndiagnóstico mais provável é:","options":{"A":"Ataxia cerebelar.","B":"Mascoidite.","C":"Petrosite.","D":"Labirintite.","E":"Colesteatoma."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-157995","number":"157995","sourceNumber":"157995","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 8 meses de idade, previamente hígido, apresenta, há três dias, quadro de\ntosse, coriza e febrícula. No dia de hoje, amanheceu com dificuldade respiratória importante e, na\nausculta pulmonar, são percebidos abundantes sibilos. Acerca do caso clínico apresentado, quanto\nao agente etiológico mais frequente que se relaciona com esse quadro, assinale a alternativa\nCORRETA.","options":{"A":"Coxsackie.","B":"Vírus sincicial respiratório.","C":"Parainfluenza.","D":"Adenovírus.","E":"Mycoplasma."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-168483","number":"168483","sourceNumber":"168483","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente com 2 anos de idade encontra-se em atendimento no ambulatório de\nPediatria por estar apresentando, há dois\ndias, dor à manipulação do ouvido direito e febre (38°C).\nA mãe relata que a criança frequenta creche desde os 4 meses de idade, quando deixou de ser\namamentado e teve o primeiro episódio de otite média aguda. Este é o quinto episódio em um ano\ne o último ocorreu há pouco mais de um mês. Entre os episódios agudos não se observou efusão.\nAs vacinas do paciente estão em dia. Ao exame físico, apresenta membrana timpânica amarelada e\nopacificada, com efusão em ouvido médio direito. De acordo com o quadro clínico descrito, a\nprincipal hipótese diagnóstica é","options":{"A":"otite média aguda com resistência bacteriana.","B":"otite média crônica colesteatomatosa.","C":"otite média aguda recorrente.","D":"otite média crônica serosa."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-154485","number":"154485","sourceNumber":"154485","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 5 meses, em aleitamento materno exclusivo é atendido em consulta\nambulatorial de puericultura com quadro de vômitos não biliosos após as mamadas desde o\nnascimento, associado a choro e arqueamento do tronco e recusa alimentar. Trata-se\nprovavelmente de:","options":{"A":"Alergia a proteína do leite de vaca.","B":"Refluxo Gastrointestinal patológico.","C":"Estenose hipertrófica do piloro.","D":"Erro inato do metabolismo.","E":"Excesso de alimentação."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-168523","number":"168523","sourceNumber":"168523","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente com 8 meses de vida é levado pela mãe à Unidade Básica de Saúde\n(UBS), que relata que a criança,\nanteriormente hígida, vem apresentando, há 8 dias, evacuações\nlíquidas, sem muco e sem sangue, com hiperemia perianal e fezes explosivas, chegando a\napresentar cerca de dez episódios em 24 horas. O lactente não está aceitando bem a alimentação,\nnem o soro caseiro, apresentando vômitos. O médico da UBS encaminha o paciente a um\n\nPronto-Socorro público para avaliação, dada a não aceitação do soro de reidratação oral oferecido,\ncom total de seis episódios de vômitos em\numa hora, mesmo com fracionamento do soro. Ao\nexame, constatam-se os seguintes achados: temperatura axilar igual a 36 °C, letargia, olhos muito\nencovados, fontanela deprimida, prega cutânea que se desfaz em mais de 2 segundos e mucosas\nsecas. Em face do presente caso clínico, o diagnóstico e a conduta adequados são","options":{"A":"diarreia aguda com desitratação; iniciar hidratação por gastróclise com soro de reidratação oral,\n50 mL/kg de peso, em 2 horas.","B":"diarreia persistente com desidratação; iniciar antiemético, antidiarreico e soro de reidratação\noral, 50 mL/kg de peso, em 2 horas.","C":"diarreia aguda com desidratação grave; iniciar hidratação venosa com solução fisiológica 0,9%,\n20 mL/kg de peso, em 30 minutos.","D":"diarreia persistente com desidratação grave; iniciar hidratação venosa com solução\nglicofisiológica 1:2, 100 mL/kg de peso, em 4 horas."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-168449","number":"168449","sourceNumber":"168449","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança com 4 anos de idade é atendida em Unidade de Pronto Atendimento por\napresentar, há 5 dias, quadro de febre de 38 °C, tosse e coriza hialina. Há 2 dias, a paciente\npassou a apresentar febre mais elevada (acima de 38,5 °C), episódios de vômito e recusa\nalimentar. O exame clínico revela: paciente em regular estado geral com frequência respiratória de\n42 irpm, estertores crepitantes em base de hemitórax direito e tiragem subcostal, sem sibilância;\npressão arterial e frequência cardíaca normais. Pelo quadro clínico apresentado, o diagnóstico e a\nconduta corretos são","options":{"A":"pneumonia; antibioticoterapia oral, com acompanhamento clínico ambulatorial, solicitação de\nradiografia de tórax e retorno em 48 horas.","B":"pneumonia muito grave; antibioticoterapia venosa, com suporte ventilatório invasivo e internação\nem unidade de terapia intensiva pediátrica.","C":"pneumonia grave; antibioticoterapia venosa, com monitorização da oxigenação por oximetria de\npulso e internação hospitalar em enfermaria pediátrica.","D":"pneumonia com derrame pleural; antibioticoterapia endovenosa, com realização de\ntoracocentese e internação em unidade de terapia intensiva pediátrica."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-168524","number":"168524","sourceNumber":"168524","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança com 10 meses de vida é atendida em um ambulatório de Pediatria. A mãe\nrelata que o apetite da criança está preservado, apesar da existência de regurgitações\n\npós-prandiais, choro persistente, principalmente à noite e após as mamadas, e acrescenta que,\napesar do espessamento dos alimentos, não houve melhora da situação clínica. A criança\napresenta ganho ponderal e desenvolvimento adequados para a idade e, na história pregressa,\nrelata dois episódios de broncoespasmo e um de otite média aguda. Nesse caso, a conduta\nadequada é iniciar a administração de","options":{"A":"metoclopramida.","B":"domperidona.","C":"bromoprida.","D":"ranitidina."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-159595","number":"159595","sourceNumber":"159595","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Com relação à vigilância em saúde, julgue o próximo item. O aumento do número de\ncasos de óbitos por coqueluche nos últimos\nanos se deve a uma falha na cobertura vacinal, uma\nvez que a imunidade conferida pela vacina é permanente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-159596","number":"159596","sourceNumber":"159596","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Com relação à vigilância em saúde, julgue o próximo item. O tratamento para a\ncoqueluche é o uso de antibiótico macrolídeo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-129058","number":"129058","sourceNumber":"129058","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Ao verificar a condição de vacinação de um adolescente, o pediatra encontrou a\nseguinte situação: BCG: sem cicatriz no braço;\nhepatite B: incompleta; e febre amarela: última dose\nhá treze anos. Com base nesse caso hipotético, assinale a alternativa que apresenta a conduta\ncorreta a ser adotada pelo pediatra.","options":{"A":"Não se deve vaciná-lo contra BCG, mas se devem completar as três doses da vacina contra\nhepatite B e deve-se vaciná-lo contra febre amarela.","B":"Deve-se vaciná-lo contra BCG e contra febre amarela e devem-se completar as três doses da\nvacina contra hepatite B.","C":"Deve-se vaciná-lo contra BCG e devem-se completar as três doses da vacina contra hepatite B,\nmas não se deve vaciná-lo contra febre amarela.","D":"Não se deve vaciná-lo contra BCG, mas se devem aplicar as três doses da vacina contra\nhepatite B e deve-se vaciná-lo contra febre amarela.","E":"Não se deve vaciná-lo contra BCG nem contra febre amarela, mas se devem completar as três\ndoses da vacina contra hepatite B."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-133964","number":"133964","sourceNumber":"133964","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 6 meses é levado para o centro de saúde com história de sintomas gripais,\nhá três dias, para atualização vacinal.\nEncontra-se aparentemente hígido e são negados\nantecedentes patológicos dignos de nota. Quanto à atualização vacinal da criança, assinale a\nalternativa CORRETA:","options":{"A":"Não deve ser aplicada nenhuma vacina, pois a criança apresenta-se doente.","B":"Devem ser aplicadas as vacinas pentavalente (DPT + Hib + HB), VOP e antipneumocócica.","C":"Devem ser aplicadas as vacinas pentavalente (DPT + Hib + HB), VIP VORH (rotavírus) e\nantipneumocócica.","D":"É importante aplicar as vacinas tríplice viral, VOP e antipneumocócica.","E":"É preciso aplicar as vacinas tríplice viral, VIP, VORH (rotavírus) e antipneumocócica."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-104737","number":"104737","sourceNumber":"104737","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A respeito da vacina penta, é correto afirmar que é prevenção","options":{"A":"secundária constituída somente contra doenças causadas por bactérias.","B":"primária contra duas doenças bacterianas e três doenças virais.","C":"primária contra três doenças bacterianas e duas virais.","D":"secundária somente contra doenças causadas por bactérias.","E":"primária contra quatro doenças bacterianas e uma viral."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-104786","number":"104786","sourceNumber":"104786","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Nos últimos quinze anos, ocorreram modificações importantes no esquema rotineiro de\nvacinação das crianças. Foi introduzida, aos quinze meses de idade, a tríplice viral, que protege\ncontra:","options":{"A":"Rubéola, hepatite B e sarampo.","B":"Sarampo, caxumba e rubéola.","C":"Hepatite A, rubéola e gripe.","D":"Poliomielite, sarampo e rubéola.","E":"Rubéola, caxumba e poliomielite."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97804","number":"97804","sourceNumber":"97804","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente com quatro meses de idade nasceu a termo com peso de 3 kg. Desde o\nnascimento, faz uso de leite materno complementado com fórmula láctea. Atualmente pesa 5,5 kg.\nHá um mês iniciou quadro de diarreia, com seis evacuações ao dia e raios de sangue e fezes não\nexplosivas. No exame físico foi observado que a criança estava em bom estado geral, bem nutrida,\nhidratada e que não havia hiperemia perianal. Nesse caso, a conduta indicada é:","options":{"A":"suspender a fórmula láctea e oferecer aleitamento materno exclusivamente.","B":"manter o aleitamento materno e substituir a fórmula láctea por hidrolisado proteico.","C":"manter o aleitamento materno complementado com fórmula láctea e associar um probiótico.","D":"suspender o aleitamento materno e a fórmula láctea, substituindo-os por fórmula à base de soja."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97771","number":"97771","sourceNumber":"97771","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um adolescente com 12 anos de idade é trazido à consulta na Unidade Básica de\nSaúde com relato de febre variando entre\n38,8°C e 39 °C, há dois dias, acompanhada de dor de\ngarganta, manchas vermelhas pelo corpo e desânimo. Na anamnese refere também náuseas e dor\nabdominal. Ao exame o paciente apresenta queda do estado geral, exantema máculo-papular não\npruriginoso em membros, tronco e região glútea. As amígdalas mostram-se muito hipertrofiadas,\ncom presença de exsudato; presença de linfoadenopatia submandibular, cervical anterior e\nepitroclear. Aparelho respiratório e cardiovascular sem alterações. Abdome difusamente doloroso,\ncom fígado palpável a 2 cm de rebordo costal direito e baço a 3 cm do rebordo costal esquerdo. O\nhemograma apresenta leucocitose de 14.000 células/mm³ com 20% de linfócitos atípicos, sem\noutras alterações importantes, e o teste rápido para pesquisa de antígeno estreptocócico do grupo\nA é negativo. Diante do quadro clínico e laboratorial do paciente, qual o diagnóstico e conduta?","options":{"A":"Amigdalite estreptocócica: prescrever penicilina ou derivados por dez dias e reavaliar o\npaciente.","B":"Escarlatina; prescrever antirmicrobiano e analgésico, orientando que o paciente evite esforços\nfísicos.","C":"Infecção pelo vírus da rubéola; prescrever anti-histamínico, analgésico e afastar o paciente de\ngestantes.","D":"Mononucleose infecciosa: prescrever analgésico e antitérmico, não sendo necessário o uso de\nantimicrobianos."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97828","number":"97828","sourceNumber":"97828","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um paciente com 25 anos de idade é encaminhado pela Unidade de Saúde da Família\ndo seu bairro para avaliação no Ambulatório\nde Clínica Médica por apresentar quadro de diarreia\nnão acompanhada de cólicas há 5 meses, com três a quatro evacuações ao dia, em grande\nquantidade, sem presença de muco ou sangue. O paciente refere perda de 15 kg nesse período,\nsem que tenha modificado a sua dieta ou apresentado mudança de apetite. O paciente trouxe à\nconsulta cinco exames protoparasitológicos das fezes realizados nesse período, sendo que o\nprimeiro demonstrou a presença de tricocéfalos, o que motivou tratamento, por duas vezes, com\nalbendazol durante 3 dias, sem melhora do quadro. O paciente apresentou igualmente\nhemogramas que demonstravam anemia hipocrômica, microcítica, com anisocitose, sem alteração\nnas séries branca ou megacariocítica. A investigação complementar indicada e o diagnóstico são:","options":{"A":"realizar pesquisa (dosagem) de gordura fecal e, se anormal, considerar a realização de biópsia\nde intestino delgado pela possibilidade de\ndoença celíaca.","B":"realizar tomografia computadorizada de abdome para avaliar a ocorrência de calcificações\npancreáticas e determinar o diagnóstico de pancreatite crônica.","C":"realizar colonoscopia com biópsias de intestino devido à possibilidade de doença inflamatória\nintestinal, como a retocolite ulcerativa.","D":"realizar dosagens de hormônio estimulador da tireoide (TSH) e de T4 livre para avaliar a\npossibilidade de hipertireoidismo."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97765","number":"97765","sourceNumber":"97765","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um médico de uma Emergência Pediátrica recebe um lactente com quatro meses de\nidade que apresenta dificuldade respiratória. A mãe refere que a criança vinha apresentando coriza\nhá três dias e que há um dia surgiu cansaço progressivo e dificuldade para mamar. Não houve\nfebre no período. Não há relato de internações anteriores. Gestação e parto sem intercorrências.\n\nAo exame físico lactente apresenta-se eutrófico e em bom estado geral, corado e hidratado.\nFrequência respiratória de 43 incursões por minuto\ncom leve tiragem intercostal. A ausculta\nrespiratória demonstra a presença de sibilos difusos e aumento do tempo expiratório. A ausculta\ncardíaca é normal e o abdome, plano, flácido, indolor e sem visceromegalias. Uma radiografia de\ntórax evidencia bilateralmente: hiperinsuflação pulmonar, retificação das cúpulas diafragmáticas e\ninfiltrado intersticial discreto. A gasometria arterial mostra os seguintes resultados: PH = 7,41;\nPO2\n\n= 58; PCO2 = 38; BE = 0,4; HCO3 = 24; SaO2 = 89%. Considerando a principal hipótese\ndiagnóstica e as condições clínicas da criança, o tratamento indicado é:","options":{"A":"hidratação e oxigenoterapia.","B":"cabeceira elevada e corticoide.","C":"aspiração nasal e broncodilatador.","D":"mínimo manuseio e medicação antiviral."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97751","number":"97751","sourceNumber":"97751","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um lactente, com oito meses e meio de idade, é atendido na Unidade Básica de Saúde\ncom diarreia líquida, com média de sete\nevacuações ao dia, vômitos e febre. Os sintomas\niniciaram-se há dois dias, juntamente com coriza e tosse. Desde os quatro meses de idade, o\nlactente alimenta-se com leite materno, mamadeira (leite de vaca diluído ao meio e farinha) e papa\nde vegetais (cada uma dessas refeições, duas vezes ao dia). Ao exame físico, o médico observou\nchoro intenso e sem lágrimas, olhos fundos, boca seca, enchimento capilar prejudicado e sinal da\nprega desaparecendo lentamente. O lactente está recusando a alimentação, exceto leite materno,\nque mama avidamente. A conduta indicada para esse lactente é hidratação","options":{"A":"oral (70 ml/kg em até 4 horas) e manutenção do aleitamento materno. Após a melhora,\nalimentação normal, sem utilização de leite de vaca e derivados.","B":"oral (100 ml/kg em 4 horas) e manutenção do aleitamento materno. Após a melhora,\nreadequação alimentar, corrigindo-se o preparo das mamadeiras.","C":"venosa (100 ml/kg de soro glicofisiológico em 2 horas) e suspensão da amamentação. Após a\nmelhora, readequação alimentar, corrigindo-se o preparo das mamadeiras.","D":"venosa (100 ml/kg de Ringer lactado em 2 horas) e suspensão da amamentação. Após a\nmelhora retomada da alimentação normal, sem leite de vaca e derivados."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97791","number":"97791","sourceNumber":"97791","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança, do sexo feminino, com 2 anos de idade foi internada na enfermaria de um\nhospital com história de diarreia há 4 meses, com 7 a 8 evacuações por dia, caracterizadas por\nfezes volumosas e de odor fétido. Ao exame físico: estado geral comprometido, palidez cutânea,\nemagrecimento, hipotrofia muscular mais evidente em região glútea e distensão abdominal. Não há\noutros achados significativos. O diagnóstico CORRETO e a sequência da investigação diagnóstica\nsão:","options":{"A":"Diarreia funcional; dosagem de eletrólitos séricos e pesquisa da gordura fecal.","B":"Doença celíaca; dosagem de anticorpos antiendomísio e antitransglutaminase e biópsia\nintestinal.","C":"Doença de Crohn; dosagem do ASCA (Anticorpo Antissaccharomyces Cerevisiae) e enema\nopaco.","D":"Retocolite ulcerativa; dosagem do p-ANCA (anticorpo perinuclear contra estruturas\ncitoplasmáticas do neutrófilo) e biópsia de cólon."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97768","number":"97768","sourceNumber":"97768","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança do sexo masculino com dois anos de idade chega à Emergência\napresentando febre alta, salivação profusa,\nvoz abafada, desconforto respiratório, agitação e\nansiedade. O quadro iniciou-se há cerca de 8 horas, com dificuldade para deglutir, que piorou muito\nna última hora. A criança nunca foi à Unidade Básica de Saúde para vacinação. Ao exame físico o\nmédico observou temperatura axilar de 39,8 °C, aparência toxêmica, corpo inclinado para frente,\ncom hiperextensão do pescoço, protusão do queixo e posicionamento da língua para fora, fazendo\na saliva escorrer pela boca, além de estridor inspiratório. A conduta neste caso é:","options":{"A":"oxigenoterapia, intubação eletiva e ceftriaxona por via endovenosa.","B":"radiografia lateral do pescoço, corticoide e cefotaxime por via endovenosa.","C":"nebulização com adrenalina, laringoscopia e ampicilina por via endovenosa.","D":"nebulização com beta-adrenérgico, radiografia de tórax e amoxicilina por via oral."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-97786","number":"97786","sourceNumber":"97786","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança com três anos de idade, desnutrida, com internaçâo prévia há dez dias, é\nlevada a atendimento na Emergência Médica. A criança apresenta há dois dias quadro de febre\nnão aferida, tosse e dificuldade para respirar. A mãe refere que o paciente não está conseguindo\ningerir líquidos e que vomitou várias vezes nas últimas 24h. Ao exame físico, o médico observou\nque a criança apresenta regular estado geral, febre de 38.5°C, desidratação leve, taquidispneia,\ncom tiragem intercostal, presença de estertores crepitantes e diminuição do murmúrio vesicular em\nhemitórax esquerdo; frequência cardíaca = 130 bpm, frequência respiratória = 64 irpm e saturação\nde oxigênio = 91%. A radiografia de tórax é mostrada (VER IMAGEM). O agente etiológico e o\ntratamento da pneumonia apresentada pela criança são:","options":{"A":"Haemophilus influenzae; penicilina cristalina.","B":"Streptococcus pneumoniae; penicilina procaína.","C":"Staphylococcus aureus; ceftriaxona associada à oxacilina.","D":"Mycoplasma pneumoniae; antibioticoterapia com macrolídios."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-354123","number":"354123","sourceNumber":"354123","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Uma criança com 5 meses de idade é atendida no Pronto Socorro por ter iniciado, há 3\ndias, quadro de tosse produtiva e desconforto respiratório progressivo nas últimas 24 horas. A mãe\nrelata que a criança nasceu prematura de 29 semanas, tendo permanecido internada por 40 dias,\nvacinação em dia. A mãe informa, ainda, que a lactente não está? conseguindo sugar o seio\nmaterno. Ao exame clínico observa-se: temperatura axilar = 38,8 oC; frequência respiratória (FR) =\n65 irpm; frequência cardíaca (FC) = 155 bpm; tiragem intercostal e retração de fúrcula; sibilos\nexpiratórios difusos; saturação de oxigênio = 96%. A radiografia mostra hiperinsuflação pulmonar,\nsem condensações. Nesse caso clínico, o diagnóstico e conduta terapêutica recomendada são,\nrespectivamente:","options":{"A":"traqueobronquite, devendo a criança ser medicada com antibióticos e liberada para casa.","B":"traqueobronquite, sendo necessária oxigenoterapia urgente e internação imediata em UTI.","C":"bronquiolite, devendo a criança ser submetida a terapia de resgate com broncodilatador e ser\nreavaliada em 24 horas.","D":"bronquiolite, devendo-se iniciar tratamento imediato da criança em regime de internação\nhospitalar.","E":"epiglotite, devendo a criança receber antibioticoterapia específica e ser liberada para casa."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-352180","number":"352180","sourceNumber":"352180","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente com 2 meses, nascido de parto normal, domiciliar, sem pré-natal adequado.\nMãe nega intercorrências neonatais. Está em\naleitamento materno exclusivo. Há 15 dias iniciou\ncom tosse e secreção ocular amarelada. O quadro intensificou há 3 dias com tosse persistente e\n\"cansaço\". Nega febre. Exame físico com bom estado geral, acianótico, temperatura axilar: 36,8ºC,\nfrequência respiratória: 68 ipm, tiragens intercostais, ausculta pulmonar com crepitações esparsas\nbilateralmente sem sibilos. Saturação de oxigênio de 94%. A radiografia de tórax evidenciou\ninfiltrado intersticial bilateral e hiperinsuflação. Qual a provável etiologia do quadro descrito?","options":{"A":"Chlamydia trachomatis.","B":"Staphylococcus aureus.","C":"Streptococcus pneumoniae.","D":"Streptococcus beta hemolítico do grupo B."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-352158","number":"352158","sourceNumber":"352158","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente, 20 meses, iniciou com febre de 38,5ºC, recusa alimentar e irritabilidade. Mãe\nnega quadro gripal prévio e refere que seu\nfilho está com dor no ouvido direito. Pais fumantes. A\nmãe o amamentou até o 18º mês de vida. Calendário vacinal em dia de acordo com o Programa\nNacional de Imunizações. Ao exame físico a criança apresenta bom estado geral, dor à mobilização\nda orelha direita e à otoscopia notou-se hiperemia e abaulamento de membrana timpânica direita\ncom presença de efusão. Qual o tratamento inicial indicado para o caso:","options":{"A":"Azitromicina e sintomáticos.","B":"Amoxicilina e sintomáticos.","C":"Clindamicina e sintomáticos.","D":"Timpanocentese e clindamicina."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-351586","number":"351586","sourceNumber":"351586","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Um menino de 6 anos de idade tem história de 6 dias de vômitos, agitação intermitente,\nperíodos em que fica inconsolável e perda\nde peso de 0,3 kg. Ao exame sua fontanela anterior se\nencontra achatada e suas membranas mucosas estão secas. O exame abdominal não demonstra\nnada digno de nota. Os dados laboratoriais são os seguintes: Na = 130; CI = 87; CO = 30. Uma\nultrassonografia do abdome revela piloro de 3,5mm x 12mm. É CORRETO afirmar que a próxima\nprovidência mais apropriada no tratamento dessa criança é:","options":{"A":"Uma piloromiotomia.","B":"O monitoramento do pH esofágico.","C":"Iniciar a terapia por inibidores da bomba de prótons.","D":"Iniciar a reposição líquida intravenosa."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-368171","number":"368171","sourceNumber":"368171","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de um ano de idade chega ao pronto-socorro com tosse há cinco dias, de\ninício seca e, a seguir, produtiva,\nassociada a dispneia progressiva e surgimento de sibilância.\nApresenta coriza hialina e febre baixa. Antecedentes pessoais: nasceu prematuro e permaneceu na\nUTI neonatal por 30 dias, com uso de ventilação pulmonar mecânica por 15 dias. Ao exame físico,\napresenta-se: em regular estado geral; com desnutrição leve; hidratado; afebril; corado; com\ncianose de extremidades; FR = 80 irpm. Na inspeção torácica, é observado uso de musculatura\nacessória importante, e, na ausculta pulmonar, presença difusa de sibilos e estertores\nsubcrepitantes. Diante desse caso, qual é o provável diagnóstico?","options":{"A":"Broncopneumonia.","B":"Crise de asma.","C":"Bronquiolite viral aguda.","D":"Displasia broncopulmonar."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-346852","number":"346852","sourceNumber":"346852","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pedro, dois anos e seis meses, sexo masculino, previamente hígido, é levado pela mãe\nao pediatra por apresentar quadro de tosse e\nchiado no peito nos últimos sete dias. Exame físico:\nativo, FR: 45irpm, sem sinais de toxemia. A ausculta respiratória mostrou roncos e sibilos\ndisseminados, discreta diminuição do murmúrio vesicular em todo hemitórax direito. Radiografia do\ntórax: hiperinsuflação à direita com discreto desvio das estruturas do mediastino para a esquerda.\nConsiderando o caso descrito, é CORRETO afirmar que a hipótese diagnóstica e a conduta para\nesse paciente são:","options":{"A":"Síndrome do lactente sibilante e prednisolona 1mg/kg/dia por cinco dias.","B":"Enfisema lobar congênito e tomografia de tórax.","C":"Aspiração de corpo estranho e broncoscopia.","D":"Asma e salbutamol 2 jatos, com espaçador, com intervalos de 20 minutos, três vezes."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-320437","number":"320437","sourceNumber":"320437","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Adolescente, sexo masculino, 10 anos, apresenta febre diária há 5 dias, acompanhada\nde faringite e fadiga, que se intensificou nos\núltimos dias. Iniciou amoxicilina há três dias sem\nmelhora. Refere náuseas ao se alimentar e dor à deglutição. Exame físico: discreto edema em\npálpebras superiores, febril, com linfonodos cervicais aumentados, faringite exsudativa e erupção\ncutânea macular eritematosa leve no tronco e nos braços. O diagnóstico e conduta nesse caso são:","options":{"A":"Faringite estreptocócica; trocar para amoxicilina-clavulanato.","B":"Doença de Kawasaki; imunoglobulina venosa e AAS.","C":"Difteria; penicilina cristalina venosa.","D":"Dengue; internação e sintomáticos.","E":"Mononucleose infecciosa; sintomáticos."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-336277","number":"336277","sourceNumber":"336277","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Menino, 8 anos chega ao PS com relato de febre alta (39,7°C) e dor de garganta\niniciados há 4 dias sem melhora com\nazitromicina iniciada há 48 horas. Ao exame: exsudato\npurulento sobre as amígdalas, hiperemia de pilar anterior, petéquias em palato, linfadenomegalia\ngeneralizada e ponta de baço palpável. A conduta terapêutica indicada é:","options":{"A":"Suspender azitromicina","B":"Manter azitromicina e reavaliar em 48 horas","C":"Aplicar dose única de penicilina benzatina","D":"Associar amoxicilina"},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-321178","number":"321178","sourceNumber":"321178","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A Alergia Alimentar (AA) é um tema importante em pediatria, pois se pode associar a\nsignificativa morbidade, com impacto negativo na sobrevida e na qualidade de vida da criança, se\nnão for tratada adequadamente. Assim, sobre a alergia à proteína do leite de vaca, é CORRETO\nafirmar que:","options":{"A":"Na síndrome da enterocolite induzida por proteína alimentar, uma hipersensibilidade\ngastrointestinal a alimentos mediada por\nIgE, deve ser considerada, por sua gravidade, assim como\na reação anafilática, uma urgência entre as crianças com APLV.","B":"Os pacientes portadores de proctite ou proctocolite alérgicas são, em geral recém- nascidos e\nlactentes, em sua grande maioria em uso de leite materno exclusivo, sendo a reação causada pelas\nproteínas alimentares ingeridas pela mãe nutriz e presentes no leite materno.","C":"Nas enteropatias induzidas por proteínas alimentares, pode-se observar um quadro de má\nabsorção, de início insidioso, que pode se\napresentar com diarreia crônica (fezes aquosas e\nácidas), eritema perianal, distensão abdominal, vômitos, anemia, perda de peso e insuficiência do\ncrescimento. Nesse caso, a família deve ser informada que a criança possui alergia à lactose e o\ntratamento consiste na dieta de restrição da proteína do leite de vaca.","D":"O tratamento da APLV baseia-se na exclusão das proteínas do leite de vaca da dieta,\ndevendo-se também evitar a inalação e o contato com a pele, e manter as necessidades\nnutricionais do paciente. Para os recém-nascidos e lactentes em aleitamento materno,\nrecomenda-se substituição do aleitamento por fórmulas de partida."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-337639","number":"337639","sourceNumber":"337639","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"De acordo com a Organização Mundial da Saúde (OMS), 13,2% dos óbitos na infância\nestão relacionados à doença diarreica. Sobre a diarreia crônica, é CORRETO afirmar que:","options":{"A":"A diarreia osmótica é causada por nutrientes não absorvidos no lúmen intestinal, como por\nexemplo em pacientes com doença celíaca.","B":"O gastrinoma (síndrome de Zollinger-Ellison) caracteriza-se fundamentalmente por distensão\nabdominal e extrema dificuldade evacuatória decorrente da ausência dos gânglios mioentéricos.","C":"As fezes volumosas, de aspecto brilhante, odor pútrido e que boiam no vaso sanitário\ncaracterizam a esteatorreia, frequentemente\nobservada em pacientes com intolerância à lactose.","D":"A diarreia crônica é definida como perda entérica fecal de pelo menos 20g/kg/dia em lactentes e\n100g/dia para crianças maiores, pelo prazo superior a 7 dias de duração."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-321180","number":"321180","sourceNumber":"321180","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A pneumonia é uma inflamação do parênquima dos pulmões. Embora a maioria dos\ncasos de pneumonia seja causada por\nmicrorganismos, pode ser também causada por causas não\ninfecciosas. Sobre a doença em questão, é CORRETO afirmar que:","options":{"A":"O Staphylococcus aureus é o patógeno mais comum dentre as pneumonias de causa\ninfecciosas.","B":"Embora possa ter causas bacterianas e virais, as manifestações clínicas não possuem\ndiferenças sendo caracterizadas geralmente por\nrinite, tosse, febre alta, taquipneia e aumento do\nesforço respiratório.","C":"Desidratação, vômitos, imunodeficiência ou idade menor que 1 ano são fatores que sugerem a\nnecessidade de hospitalização em crianças com pneumonia.","D":"A radiografia de tórax pode confirmar o diagnóstico de pneumonia, além de poder evidenciar\ncomplicações, como derrame pleural ou empiema. No exame é observado hiperinsuflação, com\ninfiltrados intersticiais bilaterais e congestão peribrônquica."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-334755","number":"334755","sourceNumber":"334755","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A laringotraqueobronquite é a causa mais comum de obstrução de vias aéreas\nsuperiores em crianças, respondendo por 90%\ndos casos de estridor. Na laringotraqueobronquite é\ncorreto afirmar:","options":{"A":"A etiologia bacteriana é a mais comum, sendo os principais agentes o pneumococo e o\nHaemophylus.","B":"Acomete principalmente crianças com menos de um ano de idade, com predomínio do sexo\nfeminino (3 vezes mais comum no sexo feminino).","C":"Quando a etiologia é viral, os principais agentes são os vírus parainfluenza (tipos 1, 2 e 3),\ninfluenza A e B e vírus respiratório sincicial.","D":"A etiologia viral é a mais comum, sendo os principais agentes os vírus adenovírus, pneumovírus\ne rinovírus."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-334757","number":"334757","sourceNumber":"334757","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A diarreia aguda é uma enfermidade muito comum em pediatria e nela é correto\nafirmar:","options":{"A":"As parasitoses são as principais causadoras das diarreias infecciosas.","B":"A diarreia aguda pode ter causas infecciosas e não infecciosas. Mundialmente, as causas não\ninfecciosas apresentam uma maior prevalência e são causadas principalmente por alergias,\nintolerâncias e erros alimentares.","C":"Entre os vírus, o rotavírus é o principal responsável por episódios de diarreia aguda, mas\ngeralmente as infecções são autolimitadas e raramente necessitam de hospitalização.","D":"A diarreia provocada pela Escherichia coli enteropatogênica apresenta muco e é sem sangue,\nporém pode apresentar dor abdominal, vômitos\ne febre."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-334761","number":"334761","sourceNumber":"334761","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de 3 anos de idade, apresenta há quatro dias febre de início agudo,\ntaquipneia, tosse e diminuição do apetite. Ao\nexame apresenta frequência respiratória aumentada\ncom presença de tiragem subcostal. O hemograma mostra aumento de leucócitos, neutrófilos\nbastões aumentados e proteína C reativa (PCR) de 45 mg/dL. Na radiografia de tórax foi\nvisualizado condensação pulmonar a direita. Nesse quadro é correto afirmar:","options":{"A":"Como os vírus podem ser responsáveis por até 90% das pneumonias no 1° ano de vida e por\n50% dos casos na idade escolar, a criança\ndeverá ir para casa com sintomáticos e retornar com 48\nhoras caso mantenha a febre.","B":"No Brasil, considerando-se os valores atuais da concentração inibitória mínima (CIM) necessária\nde penicilina para tratamento da pneumonia\nadquirida na comunidade (PAC) por pneumococo, há\nfrequentemente cepas com taxas de resistência absoluta. Logo, o tratamento ambulatorial deverá\nser feito com dose dobrada de amoxicilina + clavulanato de potássio.","C":"Uma PCR acima de 40 diferencia PAC viral de bacteriana de forma segura e confirma presença\nde pneumococo.","D":"A criança deve ser hospitalizada e iniciado tratamento com antibiótico."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-335113","number":"335113","sourceNumber":"335113","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente feminina com dois anos de idade é atendida por uma equipe de PSF, que\nrecebeu recentemente a capacitação para Atenção\nIntegral às Doenças Prevalentes da Infância\n(AIDPI). Tem diarreia há quatro dias, com sangue nas fezes. Previamente hígida. Está hidratada,\nalerta e sem outras alterações ao exame. Assinale a conduta que a equipe deve adotar\ncorretamente para esse caso, de acordo com as orientações do AIDPI.","options":{"A":"Considerar que a paciente tem quadro grave e encaminhar para o hospital mais próximo.","B":"Considerar que a paciente deverá ficar em observação na Unidade Básica de Saúde, recebendo\nterapia de reidratação oral (TRO).","C":"Considerar que a paciente deverá receber TRO, antibiótico para Shigella e que pode manter\nseguimento ambulatorial.","D":"Considerar que a paciente tem anemia grave e deve ser solicitado hemograma e cinética do\nferro e prescrita reposição de ferro."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-306702","number":"306702","sourceNumber":"306702","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pedro, 4 anos chega ao PS com relato de 24h de adinamia, febre alta refratária a\nantitérmicos e sonolência. Recebeu 1 dose de Penicilina Benzatina para tratamento de pneumonia\nhá 3 dias. Ao exame: sonolento, pouco responsivo aos comandos verbais, sem sinais meníngeos,\npalidez cutânea, FC: 142 bpm, PA: 80x65 mmHg, pulsos finos, FR: 36 irpm, SpO2 93%, TAX\n39,4°C, ausculta pulmonar abolida em hemitórax esquerdo, presença de tiragem subcostal e de\nfúrcula. Abdome atípico, discretamente doloroso, fígado 2 cm RCD. Lesões impetiginosas\ninfectadas em panturrilha direita. O antibiótico indicado para o tratamento deste paciente é:","options":{"A":"Penicilina Cristalina","B":"Ciprofloxacina","C":"Vancomicina","D":"Azitromicina"},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291625","number":"291625","sourceNumber":"291625","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de um ano de idade é levado ao pronto socorro com quadro de febre, vômitos\ne diarreia aquosa sem sangue ou muco há 48\nhoras. Exame físico: sonolento, hipoativo, olhos\nfundos com mucosa seca e ausência de lágrimas, pulso débil e enchimento capilar > 4 segundos,\nPressão arterial sistólica 50 mmhg. Peso na admissão: 10 kg. A conduta é:","options":{"A":"Glicose 25% -200 ml endovenoso em 30 minutos.","B":"Soro fisiológico 400 ml endovenoso em 1 hora.","C":"Fisiológico e glicosado (meio a meio) 500 ml IV em duas horas.","D":"Soro de reidratação oral 100 ml via oral em 24 horas.","E":"Ringer lactato 200 ml endovenoso em 20 minutos."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291626","number":"291626","sourceNumber":"291626","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Pré-escolar, quatro anos, apresenta há cinco dias secreção e obstrução nasal, e hoje\niniciou febre com piora da tosse e queda do estado geral. Exame físico: eupneico, sem dificuldade\nrespiratória. Oroscopia: hiperemia de faringe com drenagem de secreção posterior e visualização\nde crostas amareladas no vestíbulo nasal. A conduta indicada neste caso é utilizar:","options":{"A":"Antibioticoterapia oral e soro fisiológico nasal.","B":"Anti-histamínico oral e nafazolina nasal.","C":"Soro fisiológico e nafazolina nasais.","D":"Corticoide de baixa potência e soro fisiológico nasais.","E":"Corticoide oral e soro fisiológico nasal."},"answer":"A","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291936","number":"291936","sourceNumber":"291936","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"A desidratação aguda na infância tem como causa principal perdas gastrointestinais por\ndiarreia aguda. No Brasil, em décadas passadas, era a maior causa de morbidade e mortalidade na\nprimeira infância. Nesse sentido, a desidratação na criança é uma enfermidade importante e de\ngrande impacto socioeconômico e, consequentemente, importante para a tomada de políticas\npúblicas. Sobre essa doença, é CORRETO afirmar que:","options":{"A":"A vacinação contra o rotavírus não contribui para a diminuição da morbimortalidade da doença.","B":"A desidratação pode ser classificada de acordo com a porcentagem de perda ponderal. Na\ndesidratação leve, existem perdas de até 10% dos líquidos, na moderada até 30%; e na grave,\nacima de 30% de perdas.","C":"Alguns sinais na anamnese e no exame físico da criança levam o médico a se atentar sobre\ndesidratação importante na criança, como depressão da fontanela, anúria ou oligúria, alteração de\nturgor e elasticidade da pele, entre outros.","D":"Em casos de desidratação leve, devemos orientar à família que ofereçam sopas, sucos e, se\npossível, soro de hidratação para atletas."},"answer":"C","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291631","number":"291631","sourceNumber":"291631","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente de 60 dias, nascido de parto normal, apresenta quadro subfebril, tosse\nparoxística, dispneia discreta, anorexia, tiragem subcostal e intercostal baixa. História de\nconjuntivite prévia. Radiografia de tórax: infiltrado intersticial. A conduta indicada é:","options":{"A":"Internar / Sintomaticos.","B":"Tratar ambulatorialmente / Sintomaticos.","C":"Tratar ambulatorialmente / Antibiotico.","D":"Internar/ Ecocardiograma.","E":"Internar / Antibiótico endovenoso."},"answer":"E","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291632","number":"291632","sourceNumber":"291632","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Lactente, sexo feminino, nove meses, apresentou três episódios de choro, seguido de\nparada da respiração e cianose de lábios.\nPerda da consciência, seguida de abalos clônicos breves\nde membros superiores e inferiores. Todos os episódios foram precedidos por contrariedade, raiva\nou medo. Os episódios são breves, duram no máximo um minuto, e após os mesmos, a criança\ndesperta bem e retorna ao habitual. Segundo a mãe, a lactente engatinha, senta-se sem apoio,\nsegura alimentos para comer, balbucia sons polissilábicos, exibe reação de estranhamento,\nresponde quando chamada pelo nome e brinca com o espelho. Esse quadro clínico sugere:","options":{"A":"Refluxo gastroesofágico.","B":"Síncope convulsiva.","C":"Crise convulsiva tônico-clônica generalizada.","D":"Crise de perda de fôlego","E":"Crise convulsiva focal."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-291633","number":"291633","sourceNumber":"291633","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Bebê de três meses de idade foi levado à emergência de um hospital público, por\napresentar febre baixa, cansaço, chiado no\npeito, e dificuldade respiratória. A mãe informa que ele\niniciou com um resfriado há cinco dias, e notou piora da tosse e surgimento de cansaço que deixou\nele com os lábios arroxeados e com dificuldade para mamar. Ao exame físico: Apresentava-se\ngemente, choro intenso, com batimento de asa de nariz, acianótico, com tiragem intercostal e\nretração subcostal, sibilos expiratórios disseminados. FR: 70 irpm, FC: 155 bpm e T:37,0° C e\nSaO2=90%. Qual diagnóstico e conduta:","options":{"A":"Bronqueolite / Internação hospitalar: oxigênioterapia, hidratação venosa, nebulização com\nsolução salina hipertônica, corticoide inalatório.","B":"Bronqueolite / Internação hospitalar: oxigênioterapia, hidratação venosa, nebulização com\nsolução salina hipertônica.","C":"Asma / Internação hospitalar: oxigênioterapia, hidratação venosa, nebulização com beta 2 curta\nduração, corticoide oral.","D":"Asma / Tratamento ambulatorial: Corticoide oral e inalatório, beta 2 curta duração.","E":"Pneumonia / Internação hospitalar: oxigênioterapia, hidratação venosa, antibioticoterpia venosa."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-313309","number":"313309","sourceNumber":"313309","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Sobre o Plano C para tratamento da Diarreia, a solução intravenosa, de imediato, é\nadministrada no seguinte esquema terapêutico:","options":{"A":"Dê 200 mL/kg de ringer lactato ou soro fisiológico: Primeiro: 80mL/kg em 1h Depois: 120mL/kg\nem 5h.","B":"Dê 100 mL/kg de ringer lactato ou soro fisiológico: Primeiro: 70mL/kg em 1h Depois: 30mL/kg em\n5h.","C":"Dê 200 mL/kg de ringer lactato ou soro fisiológico: Primeiro: 50mL/kg em 1h Depois: 150mL/kg\nem 5h.","D":"Dê 100 mL/kg de ringer lactato ou soro fisiológico: Primeiro: 30mL/kg em 1h Depois: 70mL/kg\nem 5h.","E":"Dê 200 mL/kg de ringer lactato ou soro fisiológico: Primeiro: 130mL/kg em 1h Depois: 70mL/kg\nem 5h."},"answer":"D","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-304876","number":"304876","sourceNumber":"304876","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Luana, lactente de 2 meses, é levada à consulta de Pronto Socorro com queixa de\nepisódios de regurgitação várias vezes ao\ndia, choro frequente, especialmente no fim da tarde, que\nocorre em média de 3 a 4 dias por semana. Está em aleitamento materno exclusivo, nasceu de\nparto normal, sem intercorrências, peso ao nascer 3030g. O peso atual é 4600g, o desenvolvimento\nneuropsicomotor é adequado e não há anormalidades no exame físico. Sobre o caso, podemos\nafirmar:","options":{"A":"Trata-se de Doença de Refluxo Gastroesofágico (DRGE) e deve ser iniciado o tratamento com\nprocinéticos e antagonistas anti H2.","B":"Trata-se de refluxo fisiológico. Orientar que a mãe mantenha a criança em posição elevada por\nmais tempo após as mamadas.","C":"Trata-se de refluxo fisiológico e deve ser iniciado fórmula infantil espessada para melhorar os\nepisódios de regurgitação.","D":"Deve ser solicitado pHmetria e endoscopia digestiva alta para melhor elucidação do quadro."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-4-304878","number":"304878","sourceNumber":"304878","collectionBlock":"medcurso:medcurso-pediatria-ped-4","collectionLabel":"Medcurso · PED 4","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 4","subtopic":"","stem":"Paciente de três anos foi internado devido a tosse e febre alta, 3 a 4 vezes ao dia, de\nevolução há 5 dias, com condensação localizada em contorno cardíaco direito no RX de tórax. A\nhipótese diagnóstica na internação foi de pneumonia comunitária sendo prescrito penicilina\ncristalina. Com 24 horas de internação, a febre diminuiu de intensidade, houve melhora discreta do\nquadro geral de acordo com observação da mãe, e o Raio X que foi repetido, evidenciou um\naumento da condensação pulmonar em relação ao Raio X de internação. Qual a melhor conduta?","options":{"A":"Trocar o antibiótico para ceftriaxona.","B":"Manter a penicilina.","C":"Trocar para amoxicilina com clavulanato.","D":"Associar garamicina."},"answer":"B","source":"Pediatria/PED 4/PED 4.txt","sourceLabel":"Medcurso · PED 4","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 4","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
